window.NEURO = {"decks": [{"id": "av", "title": "Auditory & vestibular disorders"}, {"id": "oph", "title": "Ophthalmic pharmacology"}, {"id": "va", "title": "Visual & auditory physiology"}], "questions": [{"id": "Q001", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [3, 4], "page": 3, "ref": "slide-av-3", "stem": "A 3-year-old has recurrent ear infections and persistent amber-colored eardrums between episodes. Audiometry shows an air-bone gap. Which process best explains the persistent hearing deficit?", "options": [{"text": "Cholesteatoma", "why": "Keratinizing squamous tissue in the middle ear can erode ossicles and cause conductive loss, retraction debris, and chronic drainage."}, {"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}, {"text": "Otitis media with effusion", "why": "Residual middle-ear fluid restricts tympanic membrane and ossicular motion, causing conductive hearing loss. Tympanostomy can restore ventilation in appropriately selected children."}], "answer": 4, "image": "figure-effusion.jpg"}, {"id": "Q002", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [6, 7], "page": 6, "ref": "slide-av-6", "stem": "An infant fails newborn hearing screening and has bilateral profound SNHL on ABR. Testing identifies biallelic GJB2 variants. There is no family history. What is the most likely diagnosis?", "options": [{"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}, {"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Connexin-26-related hearing loss", "why": "GJB2 encodes connexin 26, a gap-junction protein important for cochlear ion homeostasis. Recessive inheritance explains unaffected parents and an apparently negative family history."}], "answer": 4, "image": null}, {"id": "Q003", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [8, 9, 51], "page": 8, "ref": "slide-av-8", "stem": "A 55-year-old has five years of progressive left SNHL, persistent unilateral high-pitched tinnitus, and veering to the left. MRI shows the enhancing internal auditory canal/cerebellopontine angle lesion pictured. Which diagnosis fits?", "options": [{"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Cholesteatoma", "why": "Keratinizing squamous tissue in the middle ear can erode ossicles and cause conductive loss, retraction debris, and chronic drainage."}, {"text": "Vestibular schwannoma", "why": "Asymmetric SNHL with unilateral tinnitus prompts evaluation for retrocochlear pathology. The enhancing vestibular nerve mass supports vestibular schwannoma."}, {"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}], "answer": 2, "image": "figure-schwannoma.jpg"}, {"id": "Q004", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [39], "page": 39, "ref": "slide-av-39", "stem": "A patient has reduced hearing with a canal completely occluded by dark wax. Bone thresholds are normal. Which diagnosis is most likely?", "options": [{"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Cerumen impaction", "why": "Wax blocks sound reaching the tympanic membrane and causes conductive loss. Removal addresses the obstruction when performed appropriately."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}], "answer": 1, "image": "figure-wax.jpg"}, {"id": "Q005", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [39], "page": 39, "ref": "slide-av-39", "stem": "A child has congenital absence of a patent external auditory canal but preserved cochlear bone-conduction responses. Which diagnosis explains the deficit?", "options": [{"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid causes conductive loss and often an amber or dull tympanic membrane; it does not primarily damage the cochlear nerve."}, {"text": "Connexin-26-related hearing loss", "why": "GJB2 variants can cause congenital nonsyndromic sensorineural loss, often recessive and present without a known family history."}, {"text": "Ototoxic cochlear injury", "why": "Aminoglycosides, cisplatin, loop diuretics, and salicylates can impair inner-ear function; reversibility and target vary by agent."}, {"text": "Congenital aural atresia", "why": "Aural atresia prevents ordinary air-conducted sound transmission. Preserved cochlear function allows consideration of bone-conduction hearing rehabilitation."}], "answer": 4, "image": null}, {"id": "Q006", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [40, 41], "page": 40, "ref": "slide-av-40", "stem": "A young adult has progressive conductive hearing loss with a normal-appearing drum. Surgery identifies stapes fixation. Which diagnosis fits?", "options": [{"text": "Otosclerosis", "why": "Otosclerotic remodeling commonly fixes the stapes footplate and impairs oval-window transmission; stapes surgery or amplification may help selected patients."}, {"text": "Cholesteatoma", "why": "Keratinizing squamous tissue in the middle ear can erode ossicles and cause conductive loss, retraction debris, and chronic drainage."}, {"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}, {"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid causes conductive loss and often an amber or dull tympanic membrane; it does not primarily damage the cochlear nerve."}], "answer": 0, "image": null}, {"id": "Q007", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [40], "page": 40, "ref": "slide-av-40", "stem": "A chronically draining ear contains a retraction pocket filled with keratin debris and eroded ossicles. Which diagnosis is most likely?", "options": [{"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}, {"text": "Cholesteatoma", "why": "Cholesteatoma can enlarge and erode middle-ear structures, producing conductive loss and serious complications. It is not simply free wax in the external canal."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Connexin-26-related hearing loss", "why": "GJB2 variants can cause congenital nonsyndromic sensorineural loss, often recessive and present without a known family history."}], "answer": 1, "image": null}, {"id": "Q008", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [40, 41], "page": 40, "ref": "slide-av-40", "stem": "After ear trauma, examination shows an eardrum defect and audiometry shows preserved bone thresholds with reduced air thresholds. Which diagnosis best explains the loss?", "options": [{"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Tympanic membrane perforation", "why": "A perforation reduces effective mechanical sound transfer. Tympanoplasty is a repair option when indicated; the deficit is conductive unless additional injury exists."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Ototoxic cochlear injury", "why": "Aminoglycosides, cisplatin, loop diuretics, and salicylates can impair inner-ear function; reversibility and target vary by agent."}, {"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}], "answer": 1, "image": null}, {"id": "Q009", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [47], "page": 47, "ref": "slide-av-47", "stem": "An 80-year-old has gradually progressive bilateral symmetric high-frequency hearing loss and difficulty understanding speech in a crowded room. What is the most likely diagnosis?", "options": [{"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Presbycusis", "why": "Aging-related cochlear and neural degeneration commonly causes symmetric SNHL and reduced word recognition. Noise exposure, vascular disease, smoking, and genetic susceptibility can contribute."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}], "answer": 3, "image": null}, {"id": "Q010", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [48], "page": 48, "ref": "slide-av-48", "stem": "A factory worker has a bilateral audiometric notch around 4 kHz after years of unprotected machine noise. What is the most likely diagnosis?", "options": [{"text": "Noise-induced hearing loss", "why": "Noise commonly damages the 3–6 kHz region. Human cochlear hair cells do not meaningfully regenerate, so persistent injury can produce permanent threshold shifts."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}], "answer": 0, "image": null}, {"id": "Q011", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "A patient develops high-frequency SNHL while receiving cisplatin. Which category best explains the deficit?", "options": [{"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid causes conductive loss and often an amber or dull tympanic membrane; it does not primarily damage the cochlear nerve."}, {"text": "Ototoxic cochlear injury", "why": "Cisplatin can cause irreversible outer hair cell injury, often initially affecting high frequencies. Baseline and follow-up auditory monitoring help detect toxicity."}, {"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}], "answer": 2, "image": null}, {"id": "Q012", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [50], "page": 50, "ref": "slide-av-50", "stem": "A patient awakens with markedly reduced hearing in one ear. Audiometry shows a 35-dB loss at three adjacent frequencies arising over 48 hours. What diagnosis should be urgently considered?", "options": [{"text": "Sudden sensorineural hearing loss", "why": "The common definition is at least 30 dB across three contiguous frequencies within 72 hours. Prompt assessment distinguishes SNHL from conductive causes and supports time-sensitive treatment. "}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Connexin-26-related hearing loss", "why": "GJB2 variants can cause congenital nonsyndromic sensorineural loss, often recessive and present without a known family history."}, {"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}], "answer": 0, "image": null}, {"id": "Q013", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [8, 9], "page": 8, "ref": "slide-av-8", "stem": "The pictured audiogram shows much worse left-ear thresholds than right-ear thresholds. Persistent unilateral tinnitus accompanies the loss. Which diagnosis warrants exclusion with MRI?", "options": [{"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}, {"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Vestibular schwannoma", "why": "Asymmetric SNHL raises concern for retrocochlear lesions. Audiometry identifies the asymmetry; MRI, rather than the audiogram alone, establishes a tumor."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}], "answer": 2, "image": "figure-asymmetric.jpg"}, {"id": "Q014", "deck": "av", "topic": "Hearing disorder diagnosis", "pages": [47, 48], "page": 47, "ref": "slide-av-47", "stem": "A retired worker has a slowly progressive downsloping symmetric sensorineural audiogram without an isolated focal middle-ear abnormality. Which age-associated condition is likely contributing?", "options": [{"text": "Presbycusis", "why": "Presbycusis and prior noise injury can coexist. A symmetric high-frequency pattern is compatible with aging; a new major asymmetry requires separate evaluation."}, {"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt inner-ear or neural hearing decline over hours to days requires urgent audiometric and otologic assessment; gradual loss has a different time course."}, {"text": "Ototoxic cochlear injury", "why": "Aminoglycosides, cisplatin, loop diuretics, and salicylates can impair inner-ear function; reversibility and target vary by agent."}], "answer": 0, "image": null}, {"id": "Q015", "deck": "av", "topic": "Audiogram interpretation", "pages": [26, 29], "page": 26, "ref": "slide-av-26", "stem": "Air and bone thresholds are approximately 10 dB HL across tested frequencies. Which classification is most appropriate?", "options": [{"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Normal hearing", "why": "Thresholds near 0–20/25 dB HL are generally considered normal in adults, depending on the convention. There is no significant elevation or air-bone gap."}], "answer": 4, "image": "figure-normal.jpg"}, {"id": "Q016", "deck": "av", "topic": "Audiogram interpretation", "pages": [24, 26, 31, 36], "page": 24, "ref": "slide-av-24", "stem": "The audiogram shows elevated air thresholds with near-normal masked bone thresholds and a large air-bone gap. What type of hearing loss is present?", "options": [{"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Conductive hearing loss", "why": "A large air-bone gap with near-normal bone thresholds identifies impaired outer/middle-ear transmission rather than primary cochlear loss."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}], "answer": 1, "image": "figure-conductive.jpg"}, {"id": "Q017", "deck": "av", "topic": "Audiogram interpretation", "pages": [24, 30, 37, 44], "page": 24, "ref": "slide-av-24", "stem": "Air and bone thresholds are elevated to similar levels in the affected frequencies, without a substantial gap. What type of hearing loss is present?", "options": [{"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}, {"text": "Sensorineural hearing loss", "why": "Both routes are impaired because they ultimately depend on the cochlea and auditory nerve. Similar air/bone thresholds do not mean normal hearing."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}], "answer": 3, "image": "figure-sensorineural.jpg"}, {"id": "Q018", "deck": "av", "topic": "Audiogram interpretation", "pages": [32, 38], "page": 32, "ref": "slide-av-32", "stem": "The audiogram shows elevated bone thresholds and even worse air thresholds. Which classification is most appropriate?", "options": [{"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}, {"text": "Mixed hearing loss", "why": "Elevated bone thresholds establish a sensorineural component; the additional air-bone gap establishes a conductive component."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}], "answer": 3, "image": "figure-mixed.jpg"}, {"id": "Q019", "deck": "av", "topic": "Audiogram interpretation", "pages": [35, 36], "page": 35, "ref": "slide-av-35", "stem": "A lesion blocks sound in the external auditory canal while the cochlea and nerve remain functional. What hearing loss category is expected?", "options": [{"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Conductive hearing loss", "why": "External canal and middle-ear lesions impair mechanical delivery to the cochlea and typically create an air-bone gap."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}], "answer": 1, "image": null}, {"id": "Q020", "deck": "av", "topic": "Audiogram interpretation", "pages": [35, 37], "page": 35, "ref": "slide-av-35", "stem": "Selective destruction of cochlear hair cells causes which category of hearing loss?", "options": [{"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Sensorineural hearing loss", "why": "Cochlear sensory damage impairs both air- and bone-conducted hearing. Bone conduction bypasses the middle ear, not the cochlea."}, {"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}], "answer": 2, "image": null}, {"id": "Q021", "deck": "av", "topic": "Audiogram interpretation", "pages": [35, 38], "page": 35, "ref": "slide-av-35", "stem": "A patient with longstanding cochlear hearing loss develops a middle-ear effusion. Which category now best describes the combined deficit?", "options": [{"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Mixed hearing loss", "why": "A new conductive component is superimposed on existing SNHL. The audiogram shows elevated bone thresholds plus worse air thresholds."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}], "answer": 1, "image": null}, {"id": "Q022", "deck": "av", "topic": "Audiogram interpretation", "pages": [20], "page": 20, "ref": "slide-av-20", "stem": "A patient hears quiet pure tones but struggles to localize sounds and interpret complex acoustic patterns after cortical injury. Which category best fits?", "options": [{"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Auditory cortex contributes to hearing in noise, temporal judgment, localization, and complex sound interpretation; peripheral detection alone does not capture these functions."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}], "answer": 1, "image": null}, {"id": "Q023", "deck": "av", "topic": "Hearing tests", "pages": [21], "page": 21, "ref": "slide-av-21", "stem": "A clinician stands behind a patient, masks the opposite ear, and asks the patient to repeat quietly spoken letters or numbers. Which type of assessment is this?", "options": [{"text": "Weber test", "why": "A midline tuning fork tests lateralization: toward the poorer ear in conductive loss and toward the better ear in unilateral SNHL."}, {"text": "Whispered voice screening", "why": "A voice screen estimates hearing impairment at the bedside. Distance, technique, masking, and examiner intensity affect performance; formal testing quantifies a deficit."}, {"text": "Pure-tone audiometry", "why": "Frequency-specific threshold testing quantifies air and bone hearing levels; masked testing is needed when crossover could mislead."}, {"text": "Auditory brainstem response", "why": "ABR records time-locked neural responses from the auditory nerve/brainstem and permits objective assessment in infants or uncooperative patients."}, {"text": "Word recognition testing", "why": "Speech discrimination scores measure recognition of presented words, rather than simply the softest pure tone detected."}], "answer": 1, "image": null}, {"id": "Q024", "deck": "av", "topic": "Hearing tests", "pages": [22], "page": 22, "ref": "slide-av-22", "stem": "Which bedside test places a vibrating tuning fork in the midline to assess whether the sound lateralizes?", "options": [{"text": "Tympanometry", "why": "Changing canal pressure measures middle-ear admittance/compliance and pressure; it does not directly measure cochlear sensory function."}, {"text": "Word recognition testing", "why": "Speech discrimination scores measure recognition of presented words, rather than simply the softest pure tone detected."}, {"text": "Auditory brainstem response", "why": "ABR records time-locked neural responses from the auditory nerve/brainstem and permits objective assessment in infants or uncooperative patients."}, {"text": "Pure-tone audiometry", "why": "Frequency-specific threshold testing quantifies air and bone hearing levels; masked testing is needed when crossover could mislead."}, {"text": "Weber test", "why": "Weber compares relative perception between ears. Lateralization must be interpreted with Rinne and the broader clinical examination."}], "answer": 4, "image": null}, {"id": "Q025", "deck": "av", "topic": "Hearing tests", "pages": [22], "page": 22, "ref": "slide-av-22", "stem": "Which bedside test compares sound heard beside the external canal with sound heard from the mastoid?", "options": [{"text": "Pure-tone audiometry", "why": "Frequency-specific threshold testing quantifies air and bone hearing levels; masked testing is needed when crossover could mislead."}, {"text": "MRI of the internal auditory canals", "why": "MRI with appropriate sequences and contrast can identify vestibular schwannoma and other retrocochlear lesions in asymmetric SNHL."}, {"text": "Rinne test", "why": "Rinne compares AC and BC in one ear. A positive Rinne, AC greater than BC, does not exclude SNHL."}, {"text": "Weber test", "why": "A midline tuning fork tests lateralization: toward the poorer ear in conductive loss and toward the better ear in unilateral SNHL."}, {"text": "Word recognition testing", "why": "Speech discrimination scores measure recognition of presented words, rather than simply the softest pure tone detected."}], "answer": 2, "image": null}, {"id": "Q026", "deck": "av", "topic": "Hearing tests", "pages": [23, 24, 25], "page": 23, "ref": "slide-av-23", "stem": "Which test measures the softest detected tones at several frequencies using headphones and a mastoid vibrator?", "options": [{"text": "Word recognition testing", "why": "Speech discrimination scores measure recognition of presented words, rather than simply the softest pure tone detected."}, {"text": "Tympanometry", "why": "Changing canal pressure measures middle-ear admittance/compliance and pressure; it does not directly measure cochlear sensory function."}, {"text": "MRI of the internal auditory canals", "why": "MRI with appropriate sequences and contrast can identify vestibular schwannoma and other retrocochlear lesions in asymmetric SNHL."}, {"text": "Rinne test", "why": "This compares air with bone conduction at one ear. Air greater than bone occurs normally and in SNHL; bone at least as good as air suggests conductive loss."}, {"text": "Pure-tone audiometry", "why": "Air testing evaluates the entire pathway; bone testing bypasses external/middle-ear transmission. A sound-treated booth and calibration improve reliability."}], "answer": 4, "image": null}, {"id": "Q027", "deck": "av", "topic": "Hearing tests", "pages": [25], "page": 25, "ref": "slide-av-25", "stem": "A patient detects pure tones reasonably well but recognizes only 48% of words presented at an appropriate audible level. Which test quantifies this additional deficit?", "options": [{"text": "Word recognition testing", "why": "Word recognition measures speech discrimination and provides information beyond threshold sensitivity. Poor recognition influences hearing rehabilitation decisions."}, {"text": "Auditory brainstem response", "why": "ABR records time-locked neural responses from the auditory nerve/brainstem and permits objective assessment in infants or uncooperative patients."}, {"text": "MRI of the internal auditory canals", "why": "MRI with appropriate sequences and contrast can identify vestibular schwannoma and other retrocochlear lesions in asymmetric SNHL."}, {"text": "Pure-tone audiometry", "why": "Frequency-specific threshold testing quantifies air and bone hearing levels; masked testing is needed when crossover could mislead."}, {"text": "Rinne test", "why": "This compares air with bone conduction at one ear. Air greater than bone occurs normally and in SNHL; bone at least as good as air suggests conductive loss."}], "answer": 0, "image": null}, {"id": "Q028", "deck": "av", "topic": "Hearing tests", "pages": [33], "page": 33, "ref": "slide-av-33", "stem": "Which test measures middle-ear pressure, compliance, and ear canal volume using a probe seal?", "options": [{"text": "Tympanometry", "why": "Tympanometry assesses middle-ear mechanics. A flat trace or negative-pressure peak requires interpretation with canal volume and otoscopy."}, {"text": "Weber test", "why": "A midline tuning fork tests lateralization: toward the poorer ear in conductive loss and toward the better ear in unilateral SNHL."}, {"text": "Whispered voice screening", "why": "This is a bedside hearing screen, but it does not replace calibrated audiometry or identify all types of hearing loss."}, {"text": "MRI of the internal auditory canals", "why": "MRI with appropriate sequences and contrast can identify vestibular schwannoma and other retrocochlear lesions in asymmetric SNHL."}, {"text": "Rinne test", "why": "This compares air with bone conduction at one ear. Air greater than bone occurs normally and in SNHL; bone at least as good as air suggests conductive loss."}], "answer": 0, "image": null}, {"id": "Q029", "deck": "av", "topic": "Hearing tests", "pages": [6, 34], "page": 6, "ref": "slide-av-6", "stem": "A 3-month-old cannot perform behavioral audiometry reliably. Which test objectively assesses auditory neural responses?", "options": [{"text": "Weber test", "why": "A midline tuning fork tests lateralization: toward the poorer ear in conductive loss and toward the better ear in unilateral SNHL."}, {"text": "MRI of the internal auditory canals", "why": "MRI with appropriate sequences and contrast can identify vestibular schwannoma and other retrocochlear lesions in asymmetric SNHL."}, {"text": "Whispered voice screening", "why": "This is a bedside hearing screen, but it does not replace calibrated audiometry or identify all types of hearing loss."}, {"text": "Auditory brainstem response", "why": "Scalp-recorded responses after acoustic stimuli permit objective hearing assessment in infants. ABR can estimate thresholds and evaluate neural timing."}, {"text": "Tympanometry", "why": "Changing canal pressure measures middle-ear admittance/compliance and pressure; it does not directly measure cochlear sensory function."}], "answer": 3, "image": null}, {"id": "Q030", "deck": "av", "topic": "Hearing tests", "pages": [9, 51], "page": 9, "ref": "slide-av-9", "stem": "A patient has progressive unilateral SNHL and a substantial interaural word-recognition difference. Which study best assesses a retrocochlear mass?", "options": [{"text": "Word recognition testing", "why": "Speech discrimination scores measure recognition of presented words, rather than simply the softest pure tone detected."}, {"text": "MRI of the internal auditory canals", "why": "MRI evaluates vestibular nerve and cerebellopontine angle lesions. A normal otoscopic examination does not exclude such pathology."}, {"text": "Weber test", "why": "A midline tuning fork tests lateralization: toward the poorer ear in conductive loss and toward the better ear in unilateral SNHL."}, {"text": "Pure-tone audiometry", "why": "Frequency-specific threshold testing quantifies air and bone hearing levels; masked testing is needed when crossover could mislead."}, {"text": "Whispered voice screening", "why": "This is a bedside hearing screen, but it does not replace calibrated audiometry or identify all types of hearing loss."}], "answer": 1, "image": null}, {"id": "Q031", "deck": "av", "topic": "Tuning fork interpretation", "pages": [22], "page": 22, "ref": "slide-av-22", "stem": "A left middle-ear effusion causes conductive loss. Which tuning fork pattern is expected?", "options": [{"text": "Weber to the right; left Rinne air greater than bone", "why": "This pattern is more compatible with left SNHL than left conductive loss."}, {"text": "Weber to the right; normal bone thresholds exclude conductive loss", "why": "Normal cochlear bone thresholds actually support an isolated conductive component."}, {"text": "Weber to the left; left Rinne bone at least as good as air", "why": "Conductive loss makes Weber lateralize toward the affected ear and can reverse Rinne when sufficiently large."}, {"text": "Weber midline; Rinne always proves normal thresholds", "why": "Rinne does not quantify thresholds, and unilateral conductive loss usually lateralizes Weber."}, {"text": "Weber direction cannot change with middle-ear disease", "why": "Conductive disease is a classic cause of Weber lateralization."}], "answer": 2, "image": null}, {"id": "Q032", "deck": "av", "topic": "Tuning fork interpretation", "pages": [22], "page": 22, "ref": "slide-av-22", "stem": "A patient has left cochlear SNHL and intact right hearing. Which pattern is expected?", "options": [{"text": "Weber midline in every unilateral loss", "why": "Asymmetric hearing can cause lateralization."}, {"text": "Normal right hearing makes all left testing impossible", "why": "Contralateral masking can prevent crossover and permit ear-specific assessment."}, {"text": "Rinne must be negative in all SNHL", "why": "Rinne is typically positive in SNHL."}, {"text": "Weber to the right; Rinne air greater than bone", "why": "Weber lateralizes toward the better-hearing ear in unilateral SNHL. AC remains better than BC even though both are impaired."}, {"text": "Weber to the left; left Rinne bone greater than air", "why": "This is a classic conductive-loss pattern."}], "answer": 3, "image": null}, {"id": "Q033", "deck": "av", "topic": "Audiometry principles", "pages": [24, 26], "page": 24, "ref": "slide-av-24", "stem": "Why does bone-conduction testing help identify a conductive component?", "options": [{"text": "It measures only vestibular responses", "why": "The test assesses auditory thresholds."}, {"text": "It bypasses the cochlea and directly activates cortex", "why": "Bone-conducted hearing still requires cochlear and neural function."}, {"text": "It removes all need for contralateral masking", "why": "Bone conduction can stimulate the opposite cochlea, making masking important."}, {"text": "It bypasses external and middle-ear mechanical transmission", "why": "Bone vibration stimulates the cochlea more directly. A gap between air and bone thresholds identifies an additional transmission deficit."}, {"text": "It directly measures middle-ear fluid volume", "why": "Tympanometry and otoscopy assess middle-ear status; bone thresholds do not measure fluid volume."}], "answer": 3, "image": null}, {"id": "Q034", "deck": "av", "topic": "Audiometry principles", "pages": [26], "page": 26, "ref": "slide-av-26", "stem": "On a standard audiogram, what does moving downward on the vertical axis mean?", "options": [{"text": "A higher dB HL threshold and poorer hearing sensitivity", "why": "Audiograms plot increasing hearing level downward. A lower-positioned point means a louder test tone was needed."}, {"text": "Better word recognition by definition", "why": "Pure-tone thresholds do not directly equal speech recognition scores."}, {"text": "A lower threshold and better sensitivity", "why": "This reverses the standard audiogram axis."}, {"text": "A higher sound frequency", "why": "Frequency is plotted on the horizontal axis."}, {"text": "Greater middle-ear compliance", "why": "Compliance is a tympanometric measurement."}], "answer": 0, "image": null}, {"id": "Q035", "deck": "av", "topic": "Audiometry principles", "pages": [26, 28], "page": 26, "ref": "slide-av-26", "stem": "What does 0 dB HL mean?", "options": [{"text": "Complete absence of acoustic energy", "why": "Zero on the hearing-level scale does not mean no sound exists."}, {"text": "A 0% word recognition score", "why": "Word recognition is a separate percentage measure."}, {"text": "A completely immobile tympanic membrane", "why": "Membrane mechanics are assessed by tympanometry."}, {"text": "A reference threshold based on normal hearing for that frequency", "why": "dB HL is referenced to normal auditory thresholds, not absolute absence of sound. Different frequencies have different physical reference intensities."}, {"text": "Profound deafness", "why": "Profound loss requires much higher thresholds."}], "answer": 3, "image": null}, {"id": "Q036", "deck": "av", "topic": "Hearing loss severity", "pages": [27, 28], "page": 27, "ref": "slide-av-27", "stem": "A measured adult threshold is 35 dB HL. Using common lecture-style categories, how is its severity classified?", "options": [{"text": "Moderately severe loss", "why": "A common adult range is about 56–70 dB HL."}, {"text": "Severe loss", "why": "A common adult range is about 71–90 dB HL."}, {"text": "Profound loss", "why": "Thresholds above about 90 dB HL are generally considered profound; residual hearing and speech benefit still require assessment."}, {"text": "Mild loss", "why": "A 35-dB threshold is within a common mild range. Severity describes the threshold, not whether the loss is conductive or sensorineural."}, {"text": "Moderate loss", "why": "A common adult range is about 41–55 dB HL."}], "answer": 3, "image": null}, {"id": "Q037", "deck": "av", "topic": "Hearing loss severity", "pages": [27, 28], "page": 27, "ref": "slide-av-27", "stem": "An adult threshold is 50 dB HL. Which common category applies?", "options": [{"text": "Moderate loss", "why": "A threshold near 50 dB HL lies in a typical moderate range; exact cutoffs vary slightly across conventions."}, {"text": "Moderately severe loss", "why": "A common adult range is about 56–70 dB HL."}, {"text": "Mild loss", "why": "A commonly used adult range is roughly 26–40 dB HL; schemes vary, especially in children."}, {"text": "Severe loss", "why": "A common adult range is about 71–90 dB HL."}, {"text": "Profound loss", "why": "Thresholds above about 90 dB HL are generally considered profound; residual hearing and speech benefit still require assessment."}], "answer": 0, "image": null}, {"id": "Q038", "deck": "av", "topic": "Hearing loss severity", "pages": [27, 28], "page": 27, "ref": "slide-av-27", "stem": "An adult threshold is 65 dB HL. Which category best fits?", "options": [{"text": "Mild loss", "why": "A commonly used adult range is roughly 26–40 dB HL; schemes vary, especially in children."}, {"text": "Moderate loss", "why": "A common adult range is about 41–55 dB HL."}, {"text": "Profound loss", "why": "Thresholds above about 90 dB HL are generally considered profound; residual hearing and speech benefit still require assessment."}, {"text": "Severe loss", "why": "A common adult range is about 71–90 dB HL."}, {"text": "Moderately severe loss", "why": "A typical moderately severe range is approximately 56–70 dB HL."}], "answer": 4, "image": null}, {"id": "Q039", "deck": "av", "topic": "Hearing loss severity", "pages": [27, 28], "page": 27, "ref": "slide-av-27", "stem": "An adult threshold is 80 dB HL. Which category best fits?", "options": [{"text": "Profound loss", "why": "Thresholds above about 90 dB HL are generally considered profound; residual hearing and speech benefit still require assessment."}, {"text": "Moderately severe loss", "why": "A common adult range is about 56–70 dB HL."}, {"text": "Moderate loss", "why": "A common adult range is about 41–55 dB HL."}, {"text": "Mild loss", "why": "A commonly used adult range is roughly 26–40 dB HL; schemes vary, especially in children."}, {"text": "Severe loss", "why": "An 80-dB threshold is commonly classified as severe rather than profound."}], "answer": 4, "image": null}, {"id": "Q040", "deck": "av", "topic": "Hearing loss severity", "pages": [6, 27, 28], "page": 6, "ref": "slide-av-6", "stem": "An infant has reliable thresholds around 105 dB HL bilaterally. Which severity category fits?", "options": [{"text": "Profound loss", "why": "Thresholds above about 90 dB HL are profound. Objective testing and aided benefit guide rehabilitation; the number alone does not determine every treatment decision."}, {"text": "Moderately severe loss", "why": "A common adult range is about 56–70 dB HL."}, {"text": "Moderate loss", "why": "A common adult range is about 41–55 dB HL."}, {"text": "Mild loss", "why": "A commonly used adult range is roughly 26–40 dB HL; schemes vary, especially in children."}, {"text": "Severe loss", "why": "A common adult range is about 71–90 dB HL."}], "answer": 0, "image": null}, {"id": "Q041", "deck": "av", "topic": "Tympanogram interpretation", "pages": [33], "page": 33, "ref": "slide-av-33", "stem": "Tympanometry shows a normal compliance peak centered near 0 daPa. Which pattern is present?", "options": [{"text": "Type B: flat trace with large canal volume", "why": "A perforation or patent tympanostomy tube exposes additional volume and can create a flat trace with high measured volume."}, {"text": "Type C: peak at negative pressure", "why": "This suggests negative middle-ear pressure, often from obstructive Eustachian tube dysfunction."}, {"text": "Type A: normal peak near atmospheric pressure", "why": "A type A trace supports normal middle-ear mechanics. Cochlear hearing loss can still exist despite this pattern."}, {"text": "Type Ad: unusually high compliance", "why": "An excessively mobile system can occur with ossicular discontinuity or a thin/atrophic tympanic membrane; it differs from a flat effusion trace."}, {"text": "Type B: flat trace with normal canal volume", "why": "This commonly supports middle-ear effusion when the drum is intact and the probe is functioning properly."}], "answer": 2, "image": null}, {"id": "Q042", "deck": "av", "topic": "Tympanogram interpretation", "pages": [3, 33], "page": 3, "ref": "slide-av-3", "stem": "An intact amber tympanic membrane is accompanied by a flat tympanogram and normal canal volume. Which interpretation fits?", "options": [{"text": "Type B: flat trace with normal canal volume", "why": "Middle-ear effusion reduces movement and produces a flat trace. Canal volume helps distinguish fluid from a perforation or tube."}, {"text": "Type Ad: unusually high compliance", "why": "An excessively mobile system can occur with ossicular discontinuity or a thin/atrophic tympanic membrane; it differs from a flat effusion trace."}, {"text": "Type A: normal peak near atmospheric pressure", "why": "This usually reflects normal middle-ear pressure and compliance; a normal tympanogram does not exclude SNHL."}, {"text": "Type B: flat trace with large canal volume", "why": "A perforation or patent tympanostomy tube exposes additional volume and can create a flat trace with high measured volume."}, {"text": "Type C: peak at negative pressure", "why": "This suggests negative middle-ear pressure, often from obstructive Eustachian tube dysfunction."}], "answer": 0, "image": null}, {"id": "Q043", "deck": "av", "topic": "Tympanogram interpretation", "pages": [4, 33], "page": 4, "ref": "slide-av-4", "stem": "A child with a patent tympanostomy tube has a flat tympanogram and large canal volume. Which interpretation fits?", "options": [{"text": "Type A: normal peak near atmospheric pressure", "why": "This usually reflects normal middle-ear pressure and compliance; a normal tympanogram does not exclude SNHL."}, {"text": "Type B: flat trace with large canal volume", "why": "The open tube permits the probe to measure connected middle-ear volume. This is different from an intact fluid-filled middle ear."}, {"text": "Type Ad: unusually high compliance", "why": "An excessively mobile system can occur with ossicular discontinuity or a thin/atrophic tympanic membrane; it differs from a flat effusion trace."}, {"text": "Type B: flat trace with normal canal volume", "why": "This commonly supports middle-ear effusion when the drum is intact and the probe is functioning properly."}, {"text": "Type C: peak at negative pressure", "why": "This suggests negative middle-ear pressure, often from obstructive Eustachian tube dysfunction."}], "answer": 1, "image": null}, {"id": "Q044", "deck": "av", "topic": "Tympanogram interpretation", "pages": [5, 33], "page": 5, "ref": "slide-av-5", "stem": "A retracted drum has a tympanometric peak at strongly negative pressure. Which pattern is present?", "options": [{"text": "Type B: flat trace with large canal volume", "why": "A perforation or patent tympanostomy tube exposes additional volume and can create a flat trace with high measured volume."}, {"text": "Type A: normal peak near atmospheric pressure", "why": "This usually reflects normal middle-ear pressure and compliance; a normal tympanogram does not exclude SNHL."}, {"text": "Type B: flat trace with normal canal volume", "why": "This commonly supports middle-ear effusion when the drum is intact and the probe is functioning properly."}, {"text": "Type Ad: unusually high compliance", "why": "An excessively mobile system can occur with ossicular discontinuity or a thin/atrophic tympanic membrane; it differs from a flat effusion trace."}, {"text": "Type C: peak at negative pressure", "why": "Obstructive Eustachian tube dysfunction can produce negative middle-ear pressure and drum retraction. A type C trace alone does not prove infected fluid."}], "answer": 4, "image": null}, {"id": "Q045", "deck": "av", "topic": "Hearing rehabilitation", "pages": [3, 4], "page": 3, "ref": "slide-av-3", "stem": "A child with persistent middle-ear fluid and clinically significant hearing difficulty improves after placement of a small eardrum ventilation device. Which intervention was used?", "options": [{"text": "Prompt corticosteroid-based evaluation/treatment for sudden SNHL", "why": "Time-sensitive otologic assessment can lead to systemic or intratympanic corticosteroid treatment after considering risks and alternatives."}, {"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair can restore damaged tympanic membrane/ossicular mechanics when the lesion is suitable."}, {"text": "Tympanostomy tube", "why": "A tube ventilates the middle ear and permits drainage without depending on normal Eustachian tube opening. Selection follows clinical duration, hearing, and infection criteria rather than every isolated effusion."}, {"text": "Balloon dilation of the Eustachian tube", "why": "Dilation can improve selected chronic obstructive Eustachian tube dysfunction; it is not a treatment for a patulous tube."}], "answer": 3, "image": "figure-tube.jpg"}, {"id": "Q046", "deck": "av", "topic": "Hearing rehabilitation", "pages": [5], "page": 5, "ref": "slide-av-5", "stem": "Which newer procedure targets selected chronic obstructive Eustachian tube dysfunction by expanding its cartilaginous segment?", "options": [{"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair can restore damaged tympanic membrane/ossicular mechanics when the lesion is suitable."}, {"text": "Bone-conduction hearing device", "why": "This bypasses external/middle-ear transmission by vibrating the skull and requires adequate cochlear function at the receiving side."}, {"text": "Balloon dilation of the Eustachian tube", "why": "Balloon dilation is distinct from eardrum tube placement and from management of a patulous tube. Proper patient selection is important."}, {"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}], "answer": 2, "image": "figure-balloon.jpg"}, {"id": "Q047", "deck": "av", "topic": "Hearing rehabilitation", "pages": [45, 47], "page": 45, "ref": "slide-av-45", "stem": "An older adult has aidable bilateral SNHL and retains useful word recognition. Which device primarily increases acoustic input?", "options": [{"text": "Bone-conduction hearing device", "why": "This bypasses external/middle-ear transmission by vibrating the skull and requires adequate cochlear function at the receiving side."}, {"text": "Conventional hearing aid", "why": "A hearing aid uses a microphone, processing/amplification, and a receiver to deliver sound. It does not bypass cochlear transduction in the way an implant does."}, {"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair can restore damaged tympanic membrane/ossicular mechanics when the lesion is suitable."}, {"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}], "answer": 1, "image": null}, {"id": "Q048", "deck": "av", "topic": "Hearing rehabilitation", "pages": [39, 42, 43], "page": 39, "ref": "slide-av-39", "stem": "A patient with bilateral canal atresia has good cochlear bone thresholds. Which device can bypass the absent canals and middle-ear route?", "options": [{"text": "Tympanostomy tube", "why": "A ventilation tube bypasses Eustachian tube dysfunction and ventilates the middle ear in selected persistent effusion/recurrent infection cases."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}, {"text": "Bone-conduction hearing device", "why": "Skull vibration reaches the cochlea while bypassing the conductive obstruction. Percutaneous systems cross the skin; transcutaneous systems transmit across intact skin."}, {"text": "Balloon dilation of the Eustachian tube", "why": "Dilation can improve selected chronic obstructive Eustachian tube dysfunction; it is not a treatment for a patulous tube."}, {"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair can restore damaged tympanic membrane/ossicular mechanics when the lesion is suitable."}], "answer": 2, "image": null}, {"id": "Q049", "deck": "av", "topic": "Hearing rehabilitation", "pages": [6, 7, 44, 46], "page": 6, "ref": "slide-av-6", "stem": "An infant has profound bilateral cochlear loss and minimal benefit from an appropriate hearing-aid trial. Auditory nerve integrity is adequate. Which intervention can bypass damaged hair cells?", "options": [{"text": "Prompt corticosteroid-based evaluation/treatment for sudden SNHL", "why": "Time-sensitive otologic assessment can lead to systemic or intratympanic corticosteroid treatment after considering risks and alternatives."}, {"text": "Bone-conduction hearing device", "why": "This bypasses external/middle-ear transmission by vibrating the skull and requires adequate cochlear function at the receiving side."}, {"text": "Cochlear implant", "why": "Implant electrodes stimulate spiral ganglion/auditory nerve pathways. Early appropriate auditory and language rehabilitation supports development; timing and candidacy are individualized."}, {"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair can restore damaged tympanic membrane/ossicular mechanics when the lesion is suitable."}], "answer": 2, "image": null}, {"id": "Q050", "deck": "av", "topic": "Hearing rehabilitation", "pages": [41], "page": 41, "ref": "slide-av-41", "stem": "A patient with stapes fixation undergoes placement of a small piston prosthesis. Which operation is described?", "options": [{"text": "Stapedotomy with prosthesis", "why": "A prosthesis transmits ossicular vibration past the fixed stapes footplate. This treats the conductive mechanism rather than regenerating cochlear cells."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}, {"text": "Prompt corticosteroid-based evaluation/treatment for sudden SNHL", "why": "Time-sensitive otologic assessment can lead to systemic or intratympanic corticosteroid treatment after considering risks and alternatives."}, {"text": "Balloon dilation of the Eustachian tube", "why": "Dilation can improve selected chronic obstructive Eustachian tube dysfunction; it is not a treatment for a patulous tube."}, {"text": "Bone-conduction hearing device", "why": "This bypasses external/middle-ear transmission by vibrating the skull and requires adequate cochlear function at the receiving side."}], "answer": 0, "image": null}, {"id": "Q051", "deck": "av", "topic": "Hearing rehabilitation", "pages": [40, 41], "page": 40, "ref": "slide-av-40", "stem": "Chronic disease has damaged the eardrum and ossicular chain while cochlear thresholds are preserved. Which reconstructive option targets the deficit?", "options": [{"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Balloon dilation of the Eustachian tube", "why": "Dilation can improve selected chronic obstructive Eustachian tube dysfunction; it is not a treatment for a patulous tube."}, {"text": "Conventional hearing aid", "why": "Amplification makes acoustic input more audible but still depends on functioning cochlear sensory/neural pathways."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}, {"text": "Tympanoplasty or ossicular reconstruction", "why": "Repair addresses the mechanical transmission abnormality. It cannot reverse an unrelated sensorineural component."}], "answer": 4, "image": null}, {"id": "Q052", "deck": "av", "topic": "Hearing rehabilitation", "pages": [50], "page": 50, "ref": "slide-av-50", "stem": "A patient has a new 40-dB unilateral SNHL across three adjacent frequencies within two days. Which approach is most appropriate?", "options": [{"text": "Balloon dilation of the Eustachian tube", "why": "Dilation can improve selected chronic obstructive Eustachian tube dysfunction; it is not a treatment for a patulous tube."}, {"text": "Prompt corticosteroid-based evaluation/treatment for sudden SNHL", "why": "Sudden SNHL warrants urgent assessment. Corticosteroids may be offered early; intratympanic treatment has an important salvage role. Waiting months can miss a therapeutic window."}, {"text": "Cochlear implant", "why": "An electrode array directly stimulates auditory nerve elements, bypassing severely damaged cochlear hair-cell transduction; it does not restore normal hair cells."}, {"text": "Stapedotomy with prosthesis", "why": "This bypasses a fixed stapes in selected otosclerosis cases to improve conductive transmission."}, {"text": "Tympanostomy tube", "why": "A ventilation tube bypasses Eustachian tube dysfunction and ventilates the middle ear in selected persistent effusion/recurrent infection cases."}], "answer": 1, "image": null}, {"id": "Q053", "deck": "av", "topic": "Hearing rehabilitation", "pages": [42, 43], "page": 42, "ref": "slide-av-42", "stem": "What distinguishes a percutaneous from a transcutaneous bone-conduction system?", "options": [{"text": "Percutaneous systems regenerate hair cells", "why": "These devices transfer vibration rather than regenerate sensory cells."}, {"text": "Transcutaneous systems require an open external canal", "why": "They can bypass external canal obstruction."}, {"text": "Both are ordinary air-conduction earbuds", "why": "Their defining route is skull vibration, not conventional ear-canal sound delivery."}, {"text": "Only a percutaneous device bypasses the cochlea entirely", "why": "Neither provides hearing without an effective receiving cochlea/neural pathway."}, {"text": "A percutaneous abutment crosses the skin; a transcutaneous system transmits across intact skin", "why": "Both aim to bypass a conductive pathway. Skin care, transmission efficiency, anatomy, and device candidacy influence selection."}], "answer": 4, "image": null}, {"id": "Q054", "deck": "av", "topic": "Hearing rehabilitation", "pages": [6, 7, 46], "page": 6, "ref": "slide-av-6", "stem": "Why does early rehabilitation matter in an infant with profound bilateral hearing loss?", "options": [{"text": "Auditory and language development depend on timely accessible input", "why": "Appropriate amplification, implantation when indicated, and language services support development. A good outcome in the lecture case is illustrative rather than guaranteed."}, {"text": "Cochlear implants directly stimulate the visual cortex", "why": "They stimulate auditory neural elements, not visual cortex."}, {"text": "All congenital loss resolves spontaneously by school age", "why": "Many genetic profound losses persist."}, {"text": "Speech exposure is unnecessary after implantation", "why": "Rehabilitation and accessible language remain important."}, {"text": "A negative family history excludes genetic disease", "why": "Recessive or de novo conditions can occur without known affected relatives."}], "answer": 0, "image": null}, {"id": "Q055", "deck": "av", "topic": "Vestibular schwannoma surgery", "pages": [10], "page": 10, "ref": "slide-av-10", "stem": "A translabyrinthine approach is chosen to remove a vestibular schwannoma from an ear with nonserviceable hearing. What is the key tradeoff?", "options": [{"text": "It reliably preserves normal hearing in every operated ear", "why": "The labyrinth is sacrificed in this approach."}, {"text": "It removes only external canal wax", "why": "The operation accesses a deep skull-base tumor."}, {"text": "It intentionally transects the facial nerve in all cases", "why": "Facial nerve preservation is an important surgical goal."}, {"text": "It requires removal of the contralateral cochlea", "why": "The operation is directed to the affected side."}, {"text": "It sacrifices the labyrinth and residual hearing while providing access to the CPA", "why": "Drilling through the labyrinth provides exposure for tumor removal and facial nerve preservation, but this is not a hearing-preserving approach."}], "answer": 4, "image": null}, {"id": "Q056", "deck": "av", "topic": "Asymmetric hearing loss", "pages": [51], "page": 51, "ref": "slide-av-51", "stem": "Which interaural difference is a screening clue cited in the lecture for asymmetric SNHL?", "options": [{"text": "An isolated conductive gap with normal cochlear thresholds", "why": "That describes a conductive rather than asymmetric sensorineural mechanism."}, {"text": "A one-point word recognition difference in every patient", "why": "Small test variation is not equivalent to the substantial asymmetry cited."}, {"text": "About 10 dB across two test frequencies or more than 15 percentage points in word recognition", "why": "The lecture uses these teaching thresholds. Actual MRI referral criteria vary; clinical context and the complete audiogram matter."}, {"text": "Only a unilateral negative-pressure tympanogram", "why": "That suggests a middle-ear pressure issue rather than defining SNHL asymmetry."}, {"text": "Exactly the same air and bone thresholds on both sides", "why": "Symmetry does not create the cited concern."}], "answer": 2, "image": null}, {"id": "Q057", "deck": "av", "topic": "Ototoxicity", "pages": [49, 104], "page": 49, "ref": "slide-av-49", "stem": "After prolonged antibiotic therapy, a patient develops oscillopsia and bilateral vestibular hypofunction. Which listed drug is a characteristic cause?", "options": [{"text": "Gentamicin", "why": "Gentamicin can injure vestibular hair cells and cause persistent imbalance with gaze instability. Hearing may be relatively less affected in some patients."}, {"text": "High-dose aspirin", "why": "Salicylates can cause tinnitus and usually reversible hearing changes, involving cochlear biochemical effects and outer hair-cell function."}, {"text": "Cisplatin", "why": "Platinum chemotherapy can cause permanent outer hair-cell injury, often beginning with high-frequency loss."}, {"text": "Furosemide", "why": "A loop diuretic can disrupt stria vascularis function and the endocochlear potential; toxicity is often dose/rate related and can be reversible."}, {"text": "Amoxicillin", "why": "This common penicillin is not one of the classic direct cochleotoxic agents in the lecture; treating an infection is distinct from aminoglycoside hair-cell injury."}], "answer": 0, "image": null}, {"id": "Q058", "deck": "av", "topic": "Ototoxicity", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "A patient receives a high-rate IV loop diuretic infusion and develops transient hearing decline associated with altered stria vascularis function. Which drug fits?", "options": [{"text": "Furosemide", "why": "Loop diuretics can reduce the endocochlear potential. Dose, infusion rate, renal status, and concurrent ototoxic exposures affect risk."}, {"text": "High-dose aspirin", "why": "Salicylates can cause tinnitus and usually reversible hearing changes, involving cochlear biochemical effects and outer hair-cell function."}, {"text": "Amoxicillin", "why": "This common penicillin is not one of the classic direct cochleotoxic agents in the lecture; treating an infection is distinct from aminoglycoside hair-cell injury."}, {"text": "Gentamicin", "why": "An aminoglycoside can damage cochlear and vestibular hair cells, often irreversibly; gentamicin is especially notable for vestibular toxicity."}, {"text": "Cisplatin", "why": "Platinum chemotherapy can cause permanent outer hair-cell injury, often beginning with high-frequency loss."}], "answer": 0, "image": null}, {"id": "Q059", "deck": "av", "topic": "Ototoxicity", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "A patient taking large analgesic doses develops tinnitus that improves after the medication is withdrawn. Which agent best fits?", "options": [{"text": "Amoxicillin", "why": "This common penicillin is not one of the classic direct cochleotoxic agents in the lecture; treating an infection is distinct from aminoglycoside hair-cell injury."}, {"text": "Furosemide", "why": "A loop diuretic can disrupt stria vascularis function and the endocochlear potential; toxicity is often dose/rate related and can be reversible."}, {"text": "Gentamicin", "why": "An aminoglycoside can damage cochlear and vestibular hair cells, often irreversibly; gentamicin is especially notable for vestibular toxicity."}, {"text": "High-dose aspirin", "why": "Salicylate-associated tinnitus and threshold changes are often reversible, unlike many aminoglycoside or platinum injuries."}, {"text": "Cisplatin", "why": "Platinum chemotherapy can cause permanent outer hair-cell injury, often beginning with high-frequency loss."}], "answer": 3, "image": null}, {"id": "Q060", "deck": "av", "topic": "Ototoxicity", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "Which antineoplastic agent is classically associated with irreversible high-frequency outer hair-cell damage?", "options": [{"text": "Gentamicin", "why": "An aminoglycoside can damage cochlear and vestibular hair cells, often irreversibly; gentamicin is especially notable for vestibular toxicity."}, {"text": "Cisplatin", "why": "Cisplatin cochleotoxicity is commonly permanent and can progress with cumulative exposure. This differs from the often reversible salicylate effect."}, {"text": "Furosemide", "why": "A loop diuretic can disrupt stria vascularis function and the endocochlear potential; toxicity is often dose/rate related and can be reversible."}, {"text": "Amoxicillin", "why": "This common penicillin is not one of the classic direct cochleotoxic agents in the lecture; treating an infection is distinct from aminoglycoside hair-cell injury."}, {"text": "High-dose aspirin", "why": "Salicylates can cause tinnitus and usually reversible hearing changes, involving cochlear biochemical effects and outer hair-cell function."}], "answer": 1, "image": null}, {"id": "Q061", "deck": "av", "topic": "Ototoxicity", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "Which cochlear region is often affected first in aminoglycoside-associated hearing loss?", "options": [{"text": "Basal-turn outer hair cells", "why": "The basal cochlea encodes high frequencies, and outer hair cells are often more susceptible than inner hair cells. Initial high-frequency loss can precede wider impairment."}, {"text": "Only the tympanic membrane", "why": "Ototoxicity is an inner-ear process, not solely mechanical drum injury."}, {"text": "Only the auditory cortex with preserved cochlear function", "why": "The described toxicity directly affects inner-ear tissues."}, {"text": "Only apical low-frequency cells in every case", "why": "That reverses the characteristic basal high-frequency susceptibility."}, {"text": "Only the external auditory canal", "why": "Canal obstruction causes conductive loss rather than classic cochleotoxic injury."}], "answer": 0, "image": null}, {"id": "Q062", "deck": "av", "topic": "Ototoxicity", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "Which strategy can help reduce preventable ototoxic exposure during necessary therapy?", "options": [{"text": "Use appropriate dosing/infusion practices, monitor relevant levels and renal function, and investigate early tinnitus or hearing change", "why": "Risk reduction depends on the agent and indication. Audiometric monitoring is useful; no strategy guarantees complete protection."}, {"text": "Assume normal renal function is irrelevant", "why": "Reduced clearance can increase toxic exposure."}, {"text": "Ignore tinnitus until complete deafness develops", "why": "Early symptoms can precede severe irreversible injury."}, {"text": "Assume all drug-induced loss is reversible", "why": "Aminoglycoside and cisplatin injury may persist."}, {"text": "Give every drug as the fastest possible IV bolus", "why": "Rapid high exposure can increase risk for some agents."}], "answer": 0, "image": null}, {"id": "Q063", "deck": "av", "topic": "Noise exposure", "pages": [48], "page": 48, "ref": "slide-av-48", "stem": "Under the lecture's OSHA-style 5-dB exchange rule, doubling sound level from 90 to 95 dBA changes an 8-hour permissible duration to what?", "options": [{"text": "8 hours", "why": "This ignores the exchange rule."}, {"text": "4 hours", "why": "A 5-dB increase halves duration under the OSHA exchange rule. This is separate from the more protective NIOSH 85-dBA/8-hour recommendation with a 3-dB exchange rate."}, {"text": "16 hours", "why": "Increasing exposure level shortens, rather than lengthens, allowable duration."}, {"text": "1 hour", "why": "One 5-dB increment halves eight hours to four, not one."}, {"text": "24 hours", "why": "That greatly increases noise dose rather than maintaining it."}], "answer": 1, "image": null}, {"id": "Q064", "deck": "av", "topic": "Noise exposure", "pages": [48], "page": 48, "ref": "slide-av-48", "stem": "NIOSH recommends 85 dBA for eight hours with a 3-dB exchange rate. What equivalent duration applies at 88 dBA?", "options": [{"text": "24 hours", "why": "This far exceeds the same-dose duration."}, {"text": "6 hours", "why": "This is not the 3-dB equal-energy tradeoff."}, {"text": "4 hours", "why": "A 3-dB rise halves the duration under NIOSH. The lecture combines an 85-dBA warning with an OSHA-style 5-dB rule; the standards should not be conflated."}, {"text": "16 hours", "why": "This changes duration in the wrong direction."}, {"text": "8 hours", "why": "This would double the NIOSH daily dose."}], "answer": 2, "image": null}, {"id": "Q065", "deck": "av", "topic": "Noise injury", "pages": [48], "page": 48, "ref": "slide-av-48", "stem": "Hearing thresholds worsen after loud music but return toward baseline after rest. What is this called?", "options": [{"text": "Temporary threshold shift", "why": "A reversible postexposure threshold change differs from persistent injury. Repeated exposure can still contribute to lasting damage."}, {"text": "Normal cochlear regeneration of all lost hair cells", "why": "Humans do not meaningfully replace destroyed cochlear hair cells."}, {"text": "A vestibular schwannoma", "why": "A tumor does not typically produce this reversible noise-linked pattern."}, {"text": "Permanent threshold shift by definition", "why": "Recovery toward baseline is inconsistent with permanent threshold elevation."}, {"text": "Conductive ossicular fixation", "why": "Noise-induced cochlear effects are not stapes fixation."}], "answer": 0, "image": null}, {"id": "Q066", "deck": "av", "topic": "Tinnitus differential", "pages": [53, 54], "page": 53, "ref": "slide-av-53", "stem": "A patient hears constant ringing in a quiet room, but there is no external sound and the examiner cannot hear it. Which classification fits?", "options": [{"text": "Patulous Eustachian tube", "why": "An abnormally open tube can cause respiratory and voice autophony and aural fullness; this differs from an obstructed tube."}, {"text": "Obstructive Eustachian tube dysfunction", "why": "Failure of normal opening can produce negative middle-ear pressure and effusion; it is not the same as a persistently open tube."}, {"text": "Subjective nonpulsatile tinnitus", "why": "Tinnitus is sound perception without an external acoustic stimulus. Subjective tinnitus is perceived only by the affected person."}, {"text": "Middle-ear muscle myoclonus", "why": "Tensor tympani or stapedius contractions can cause repetitive clicking that may be audible to an examiner and need not match the pulse."}, {"text": "Vascular pulsatile tinnitus", "why": "Pulse-synchronous sound suggests a vascular source such as arterial disease, venous abnormality, shunt, or intracranial hypertension; it warrants targeted evaluation."}], "answer": 2, "image": null}, {"id": "Q067", "deck": "av", "topic": "Tinnitus differential", "pages": [54, 55, 56, 58], "page": 54, "ref": "slide-av-54", "stem": "A patient hears a whoosh synchronized with the heartbeat that accelerates during exercise. Which category requires evaluation for vascular causes?", "options": [{"text": "Patulous Eustachian tube", "why": "An abnormally open tube can cause respiratory and voice autophony and aural fullness; this differs from an obstructed tube."}, {"text": "Subjective nonpulsatile tinnitus", "why": "Only the patient perceives the sound; cochlear injury and altered central auditory activity can contribute even without an external source."}, {"text": "Obstructive Eustachian tube dysfunction", "why": "Failure of normal opening can produce negative middle-ear pressure and effusion; it is not the same as a persistently open tube."}, {"text": "Retrotympanic vascular mass", "why": "A red pulsatile mass behind the drum can cause pulsatile tinnitus and requires evaluation before invasive manipulation."}, {"text": "Vascular pulsatile tinnitus", "why": "Pulse synchrony suggests a vascular mechanism. Some pulsatile tinnitus is not audible to an examiner, so pulsatile and objectively audible are overlapping rather than identical categories."}], "answer": 4, "image": null}, {"id": "Q068", "deck": "av", "topic": "Tinnitus differential", "pages": [55, 60], "page": 55, "ref": "slide-av-55", "stem": "A patient has intermittent clicking that does not track the heartbeat. The examiner can occasionally hear the click and suspects stapedius contractions. Which diagnosis fits?", "options": [{"text": "Patulous Eustachian tube", "why": "An abnormally open tube can cause respiratory and voice autophony and aural fullness; this differs from an obstructed tube."}, {"text": "Retrotympanic vascular mass", "why": "A red pulsatile mass behind the drum can cause pulsatile tinnitus and requires evaluation before invasive manipulation."}, {"text": "Vascular pulsatile tinnitus", "why": "Pulse-synchronous sound suggests a vascular source such as arterial disease, venous abnormality, shunt, or intracranial hypertension; it warrants targeted evaluation."}, {"text": "Middle-ear muscle myoclonus", "why": "Middle-ear muscle spasm can create mechanically generated objective tinnitus. Tensor tympani and stapedius are the lecture examples."}, {"text": "Subjective nonpulsatile tinnitus", "why": "Only the patient perceives the sound; cochlear injury and altered central auditory activity can contribute even without an external source."}], "answer": 3, "image": null}, {"id": "Q069", "deck": "av", "topic": "Tinnitus differential", "pages": [55, 61], "page": 55, "ref": "slide-av-55", "stem": "A patient hears the breathing and speaking voice unusually loudly in the affected ear and has aural fullness. The Eustachian tube remains abnormally open. What is the diagnosis?", "options": [{"text": "Middle-ear muscle myoclonus", "why": "Tensor tympani or stapedius contractions can cause repetitive clicking that may be audible to an examiner and need not match the pulse."}, {"text": "Vascular pulsatile tinnitus", "why": "Pulse-synchronous sound suggests a vascular source such as arterial disease, venous abnormality, shunt, or intracranial hypertension; it warrants targeted evaluation."}, {"text": "Subjective nonpulsatile tinnitus", "why": "Only the patient perceives the sound; cochlear injury and altered central auditory activity can contribute even without an external source."}, {"text": "Obstructive Eustachian tube dysfunction", "why": "Failure of normal opening can produce negative middle-ear pressure and effusion; it is not the same as a persistently open tube."}, {"text": "Patulous Eustachian tube", "why": "Respiratory and phonatory autophony are characteristic clues. An open tube is different from the obstructive dysfunction treated by ventilation or selected balloon dilation."}], "answer": 4, "image": null}, {"id": "Q070", "deck": "av", "topic": "Tinnitus differential", "pages": [57], "page": 57, "ref": "slide-av-57", "stem": "Otoscopy in a patient with pulsatile tinnitus reveals the red lesion behind the tympanic membrane shown here. Which finding best describes the concern?", "options": [{"text": "Patulous Eustachian tube", "why": "An abnormally open tube can cause respiratory and voice autophony and aural fullness; this differs from an obstructed tube."}, {"text": "Subjective nonpulsatile tinnitus", "why": "Only the patient perceives the sound; cochlear injury and altered central auditory activity can contribute even without an external source."}, {"text": "Retrotympanic vascular mass", "why": "A vascular middle-ear mass, such as a paraganglioma, can produce pulse-synchronous tinnitus. The image alone does not establish every possible vascular diagnosis; blind biopsy should be avoided."}, {"text": "Obstructive Eustachian tube dysfunction", "why": "Failure of normal opening can produce negative middle-ear pressure and effusion; it is not the same as a persistently open tube."}, {"text": "Middle-ear muscle myoclonus", "why": "Tensor tympani or stapedius contractions can cause repetitive clicking that may be audible to an examiner and need not match the pulse."}], "answer": 2, "image": "figure-vascular-mass.jpg"}, {"id": "Q071", "deck": "av", "topic": "Tinnitus differential", "pages": [3, 5, 61], "page": 3, "ref": "slide-av-3", "stem": "A patient has drum retraction, negative middle-ear pressure, and intermittent effusion rather than loud breathing autophony. Which Eustachian tube problem fits?", "options": [{"text": "Retrotympanic vascular mass", "why": "A red pulsatile mass behind the drum can cause pulsatile tinnitus and requires evaluation before invasive manipulation."}, {"text": "Patulous Eustachian tube", "why": "An abnormally open tube can cause respiratory and voice autophony and aural fullness; this differs from an obstructed tube."}, {"text": "Obstructive Eustachian tube dysfunction", "why": "Obstruction impairs pressure equalization and ventilation. Patulous dysfunction reflects excessive openness and has a different symptom pattern."}, {"text": "Vascular pulsatile tinnitus", "why": "Pulse-synchronous sound suggests a vascular source such as arterial disease, venous abnormality, shunt, or intracranial hypertension; it warrants targeted evaluation."}, {"text": "Middle-ear muscle myoclonus", "why": "Tensor tympani or stapedius contractions can cause repetitive clicking that may be audible to an examiner and need not match the pulse."}], "answer": 2, "image": null}, {"id": "Q072", "deck": "av", "topic": "Tinnitus mechanisms", "pages": [63, 64, 65], "page": 63, "ref": "slide-av-63", "stem": "Which model explains subjective tinnitus through diminished cochlear input and reduced inhibition at higher auditory centers?", "options": [{"text": "Reduced peripheral input with increased central gain", "why": "The deafferentation/loss-of-inhibition model proposes compensatory central hyperactivity. It is a mechanistic framework rather than proof of one cause in every patient."}, {"text": "Abnormal hair-cell activity after cochlear injury", "why": "Disordered cochlear signaling is one proposed contributor to subjective tinnitus; it is not the only mechanism."}, {"text": "Turbulent or abnormal vascular flow", "why": "Arterial/venous lesions can produce pulse-synchronous sound; this differs from typical nonpulsatile auditory deafferentation."}, {"text": "Mechanical muscle-generated sound", "why": "Stapedius or tensor tympani contractions create an actual internal sound rather than purely central phantom perception."}, {"text": "Abnormal spontaneous auditory nerve activity", "why": "Injured or metabolically altered fibers may generate activity without an external acoustic stimulus."}], "answer": 0, "image": null}, {"id": "Q073", "deck": "av", "topic": "Tinnitus mechanisms", "pages": [63], "page": 63, "ref": "slide-av-63", "stem": "After neural injury, individual cochlear nerve fibers fire without an external stimulus. Which proposed tinnitus mechanism is illustrated?", "options": [{"text": "Mechanical muscle-generated sound", "why": "Stapedius or tensor tympani contractions create an actual internal sound rather than purely central phantom perception."}, {"text": "Abnormal spontaneous auditory nerve activity", "why": "Spontaneous firing from injured or metabolically altered auditory fibers may contribute to phantom sound perception."}, {"text": "Abnormal hair-cell activity after cochlear injury", "why": "Disordered cochlear signaling is one proposed contributor to subjective tinnitus; it is not the only mechanism."}, {"text": "Reduced peripheral input with increased central gain", "why": "Deafferentation can reduce inhibitory control and increase central auditory activity, providing a model for subjective tinnitus."}, {"text": "Turbulent or abnormal vascular flow", "why": "Arterial/venous lesions can produce pulse-synchronous sound; this differs from typical nonpulsatile auditory deafferentation."}], "answer": 1, "image": null}, {"id": "Q074", "deck": "av", "topic": "Tinnitus mechanisms", "pages": [63], "page": 63, "ref": "slide-av-63", "stem": "A hypothesis attributes tinnitus to repetitive cochlear sensory-cell discharge following hearing injury. Which mechanism is described?", "options": [{"text": "Turbulent or abnormal vascular flow", "why": "Arterial/venous lesions can produce pulse-synchronous sound; this differs from typical nonpulsatile auditory deafferentation."}, {"text": "Mechanical muscle-generated sound", "why": "Stapedius or tensor tympani contractions create an actual internal sound rather than purely central phantom perception."}, {"text": "Reduced peripheral input with increased central gain", "why": "Deafferentation can reduce inhibitory control and increase central auditory activity, providing a model for subjective tinnitus."}, {"text": "Abnormal spontaneous auditory nerve activity", "why": "Injured or metabolically altered fibers may generate activity without an external acoustic stimulus."}, {"text": "Abnormal hair-cell activity after cochlear injury", "why": "The disordered hair-cell theory links peripheral injury to abnormal signaling interpreted as sound. Central changes may coexist."}], "answer": 4, "image": null}, {"id": "Q075", "deck": "av", "topic": "Tinnitus mechanisms", "pages": [56, 58], "page": 56, "ref": "slide-av-56", "stem": "A vascular shunt produces a pulse-synchronous sound. Which mechanism is responsible?", "options": [{"text": "Abnormal hair-cell activity after cochlear injury", "why": "Disordered cochlear signaling is one proposed contributor to subjective tinnitus; it is not the only mechanism."}, {"text": "Turbulent or abnormal vascular flow", "why": "The sound tracks circulation rather than ordinary external acoustic input. Vascular anatomy and pressure relationships guide the workup."}, {"text": "Reduced peripheral input with increased central gain", "why": "Deafferentation can reduce inhibitory control and increase central auditory activity, providing a model for subjective tinnitus."}, {"text": "Abnormal spontaneous auditory nerve activity", "why": "Injured or metabolically altered fibers may generate activity without an external acoustic stimulus."}, {"text": "Mechanical muscle-generated sound", "why": "Stapedius or tensor tympani contractions create an actual internal sound rather than purely central phantom perception."}], "answer": 1, "image": null}, {"id": "Q076", "deck": "av", "topic": "Tinnitus mechanisms", "pages": [60], "page": 60, "ref": "slide-av-60", "stem": "The examiner hears clicks during involuntary stapedius contractions. Which mechanism is responsible?", "options": [{"text": "Mechanical muscle-generated sound", "why": "Middle-ear muscle activity can generate a real internally produced acoustic signal. This is distinct from a purely phantom nonpulsatile percept."}, {"text": "Turbulent or abnormal vascular flow", "why": "Arterial/venous lesions can produce pulse-synchronous sound; this differs from typical nonpulsatile auditory deafferentation."}, {"text": "Abnormal spontaneous auditory nerve activity", "why": "Injured or metabolically altered fibers may generate activity without an external acoustic stimulus."}, {"text": "Abnormal hair-cell activity after cochlear injury", "why": "Disordered cochlear signaling is one proposed contributor to subjective tinnitus; it is not the only mechanism."}, {"text": "Reduced peripheral input with increased central gain", "why": "Deafferentation can reduce inhibitory control and increase central auditory activity, providing a model for subjective tinnitus."}], "answer": 0, "image": null}, {"id": "Q077", "deck": "av", "topic": "Tinnitus assessment", "pages": [58, 59], "page": 58, "ref": "slide-av-58", "stem": "Which targeted imaging approaches may evaluate suspected vascular pulsatile tinnitus?", "options": [{"text": "Routine lumbar spine radiography", "why": "This does not evaluate cranial vascular sources of tinnitus."}, {"text": "No imaging or assessment regardless of pulse synchrony", "why": "Persistent pulse-synchronous symptoms can signal important vascular disease."}, {"text": "Blind middle-ear biopsy before assessing vascularity", "why": "Manipulating an uncharacterized vascular lesion can cause bleeding."}, {"text": "Only an external canal swab", "why": "A swab cannot exclude a vascular shunt or venous abnormality."}, {"text": "MRA/MRV or CT angiographic approaches selected for the suspected cause", "why": "Vascular and temporal-bone imaging are tailored to the history and examination; catheter angiography is reserved for selected cases rather than every patient."}], "answer": 4, "image": null}, {"id": "Q078", "deck": "av", "topic": "Tinnitus assessment", "pages": [58], "page": 58, "ref": "slide-av-58", "stem": "A patient has pulsatile tinnitus, headaches, transient visual obscurations, and papilledema. Which associated condition should be considered?", "options": [{"text": "Ordinary age-related hearing loss as the complete explanation", "why": "Presbycusis alone does not explain the neurologic/ocular findings."}, {"text": "Benign wax impaction as the complete explanation", "why": "Wax cannot account for papilledema."}, {"text": "Idiopathic intracranial hypertension after exclusion of secondary causes", "why": "Raised ICP can produce pulsatile tinnitus and papilledema. The diagnosis requires appropriate evaluation, not symptoms alone."}, {"text": "A patulous tube as the complete explanation", "why": "Autophony does not explain pressure-related disc edema."}, {"text": "Isolated subjective tinnitus from noise exposure only", "why": "Papilledema and headache require an intracranial-pressure workup."}], "answer": 2, "image": null}, {"id": "Q079", "deck": "av", "topic": "Tinnitus assessment", "pages": [66], "page": 66, "ref": "slide-av-66", "stem": "In hearing-loss-associated tinnitus, how can perceived pitch relate to the audiogram?", "options": [{"text": "Tinnitus requires normal thresholds at every frequency", "why": "Hearing impairment commonly coexists."}, {"text": "A pitch match establishes a vestibular schwannoma", "why": "Pitch does not independently diagnose a retrocochlear mass."}, {"text": "Pitch must always equal the lowest tested frequency", "why": "There is no such universal rule."}, {"text": "It may correspond to the frequency region of greatest hearing loss", "why": "The deck emphasizes correlation with a high-frequency loss region, often 3–8 kHz. A population association is not a rule for every patient or proof of a specific lesion."}, {"text": "Tinnitus pitch measures middle-ear pressure", "why": "Pitch matching and tympanometry measure different properties."}], "answer": 3, "image": null}, {"id": "Q080", "deck": "av", "topic": "Tinnitus management", "pages": [67, 68, 69, 70], "page": 67, "ref": "slide-av-67", "stem": "A patient with persistent bothersome nonpulsatile tinnitus and aidable hearing loss asks about advertised supplements. Which approach has the best clinical basis?", "options": [{"text": "Audiologic care, hearing-aid evaluation, and tinnitus-focused behavioral management", "why": "Education, addressing hearing loss, and CBT-based approaches can reduce distress. Commercial supplement claims do not establish efficacy; treating anxiety or insomnia is distinct from curing tinnitus."}, {"text": "Recommend every advertised supplement as a proven cure", "why": "Marketing images in the deck are not evidence of benefit."}, {"text": "Promise that one drug will eliminate tinnitus in all patients", "why": "No universal curative medication is established."}, {"text": "Prescribe benzodiazepines routinely as a definitive tinnitus cure", "why": "They are not routinely recommended solely for persistent primary tinnitus and have important risks."}, {"text": "Avoid all sound exposure indefinitely", "why": "Reasonable hearing protection differs from harmful overavoidance or withdrawal from daily activities."}], "answer": 0, "image": null}, {"id": "Q081", "deck": "av", "topic": "Tinnitus management", "pages": [68], "page": 68, "ref": "slide-av-68", "stem": "Why should depression, sleep difficulty, TMJ symptoms, or cervical muscle tension be assessed in a patient with tinnitus?", "options": [{"text": "Their presence eliminates the need for hearing assessment", "why": "Audiologic evaluation remains important."}, {"text": "Each requires the same medication regardless of cause", "why": "Targeted treatment depends on the actual associated disorder."}, {"text": "Each condition proves a vascular shunt", "why": "These associations do not establish a vascular source."}, {"text": "All tinnitus is caused by psychiatric illness", "why": "Peripheral hearing injury and other mechanisms can be present."}, {"text": "Treating relevant associated conditions can reduce symptom burden and distress", "why": "Management is individualized. An antidepressant may treat comorbid depression without being a proven direct cure for the tinnitus percept."}], "answer": 4, "image": null}, {"id": "Q082", "deck": "av", "topic": "Tinnitus pharmacology", "pages": [69], "page": 69, "ref": "slide-av-69", "stem": "The lecture lists gabapentin as a GABA-related compound. What is its principal pharmacologic target?", "options": [{"text": "The alpha-2-delta subunit of voltage-gated calcium channels", "why": "Gabapentin is structurally related to GABA but is not a direct GABA receptor agonist. Its mechanism does not establish routine efficacy for primary tinnitus."}, {"text": "Direct activation of GABA-A receptors", "why": "Benzodiazepines enhance GABA-A signaling; gabapentin does not act as a direct GABA-A agonist."}, {"text": "Irreversible inhibition of acetylcholinesterase", "why": "That is an organophosphate-type cholinergic mechanism."}, {"text": "Direct activation of GABA-B receptors", "why": "Baclofen is the classic GABA-B agonist, not gabapentin."}, {"text": "Selective beta-2 blockade of ciliary epithelium", "why": "That is an ocular beta-blocker mechanism rather than gabapentin pharmacology."}], "answer": 0, "image": null}, {"id": "Q083", "deck": "av", "topic": "Tinnitus management", "pages": [68, 69], "page": 68, "ref": "slide-av-68", "stem": "Which interpretation of the lecture's antidepressant, anticonvulsant, and tranquilizer list is most accurate?", "options": [{"text": "Anticonvulsants remove vascular shunts", "why": "A structural vascular cause requires cause-specific evaluation."}, {"text": "These are discussed options, not routine proven drugs for every case of primary tinnitus", "why": "Evidence-based tinnitus care distinguishes treatment of distress or comorbid conditions from direct suppression of the percept. Blanket use of these drug classes is not recommended solely for primary tinnitus."}, {"text": "SSRIs permanently restore lost cochlear hair cells", "why": "They do not regenerate human cochlear sensory cells."}, {"text": "All tinnitus must be treated first with chronic benzodiazepines", "why": "This is not routine evidence-based care."}, {"text": "Every listed drug has established equal curative efficacy", "why": "The evidence does not support this claim."}], "answer": 1, "image": null}, {"id": "Q084", "deck": "av", "topic": "Tinnitus management", "pages": [68], "page": 68, "ref": "slide-av-68", "stem": "A patient takes prescribed low-dose aspirin for a major cardiovascular indication and reads the lecture instruction to avoid ASA. What is the best interpretation?", "options": [{"text": "Tinnitus proves the patient has no cardiovascular risk", "why": "Auditory symptoms do not negate the original indication."}, {"text": "All aspirin doses inevitably cause irreversible deafness", "why": "Salicylate auditory effects are commonly dose-related and reversible."}, {"text": "Review dose, indication, and symptoms with the treating clinician rather than stopping automatically", "why": "High-dose salicylates can cause tinnitus. A blanket instruction to stop indicated antiplatelet therapy ignores the balance of cardiovascular benefit and auditory risk."}, {"text": "Stop all cardiovascular drugs without discussion", "why": "This can create preventable risk."}, {"text": "Increase aspirin to treat the tinnitus", "why": "High doses can worsen salicylate-related symptoms."}], "answer": 2, "image": null}, {"id": "Q085", "deck": "av", "topic": "Vestibular differential", "pages": [11, 12, 74, 75, 77, 78], "page": 11, "ref": "slide-av-11", "stem": "An 82-year-old with cataracts, reduced joint sensation, and age-related vestibular decline feels unstable when walking. Which concept best explains the additive balance problem?", "options": [{"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Multisensory disequilibrium", "why": "Balance integrates vision, proprioception, and vestibular input. Impairment of multiple inputs reduces redundancy and increases fall risk."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}], "answer": 2, "image": null}, {"id": "Q086", "deck": "av", "topic": "Vestibular differential", "pages": [85, 86, 87, 88], "page": 85, "ref": "slide-av-85", "stem": "A woman has 15-second spinning spells when rolling onto her right side in bed. She has no hearing change or focal neurologic deficit. Right Dix-Hallpike produces transient torsional-upbeating nystagmus. Which diagnosis fits?", "options": [{"text": "Posterior canal BPPV", "why": "Brief position-triggered spells and the characteristic positional nystagmus indicate posterior canal BPPV, usually from utricular otoconia in the canal."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}], "answer": 0, "image": null}, {"id": "Q087", "deck": "av", "topic": "Vestibular differential", "pages": [85, 90], "page": 85, "ref": "slide-av-85", "stem": "After a viral-like illness, a patient has continuous severe vertigo for two days with nausea and unidirectional horizontal-torsional nystagmus. Hearing is unchanged. Which peripheral diagnosis is favored after excluding stroke?", "options": [{"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Vestibular neuritis", "why": "Vestibular neuritis affects vestibular function without the new cochlear loss expected in labyrinthitis. Symptoms peak early and improve as peripheral recovery and central compensation occur."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}], "answer": 1, "image": null}, {"id": "Q088", "deck": "av", "topic": "Vestibular differential", "pages": [85, 91], "page": 85, "ref": "slide-av-85", "stem": "A patient with acute middle-ear infection develops severe vertigo and new SNHL. Which complication is most concerning?", "options": [{"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Labyrinthitis", "why": "Cochlear plus vestibular involvement suggests labyrinthitis. Suppurative disease can spread from middle ear or meninges and requires urgent infection-directed care."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}], "answer": 1, "image": null}, {"id": "Q089", "deck": "av", "topic": "Vestibular differential", "pages": [85, 92, 96], "page": 85, "ref": "slide-av-85", "stem": "A 48-year-old has repeated spontaneous vertigo lasting 90 minutes with left aural fullness, roaring tinnitus, and fluctuating low-frequency SNHL. Which diagnosis fits?", "options": [{"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Meniere disease", "why": "The classic tetrad is episodic vertigo, fluctuating hearing loss, tinnitus, and fullness. Attacks last much longer than typical posterior canal BPPV."}], "answer": 4, "image": null}, {"id": "Q090", "deck": "av", "topic": "Vestibular differential", "pages": [49, 85, 104], "page": 49, "ref": "slide-av-49", "stem": "After gentamicin treatment, a patient sees the environment bob while walking and is unstable in darkness. Head impulse testing is abnormal in both directions. Which diagnosis fits?", "options": [{"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular hair-cell injury reduces the VOR, causing oscillopsia with head movement. Loss of visual compensation worsens balance in darkness."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}], "answer": 3, "image": null}, {"id": "Q091", "deck": "av", "topic": "Vestibular differential", "pages": [84, 85], "page": 84, "ref": "slide-av-84", "stem": "A patient has acute sustained dizziness, dysarthria, limb ataxia, and direction-changing gaze-evoked nystagmus. Which category requires urgent exclusion?", "options": [{"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Central vestibular lesion", "why": "Neurologic deficits and central ocular motor signs raise concern for posterior circulation disease. These should not be attributed to a benign peripheral diagnosis without evaluation."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}], "answer": 3, "image": null}, {"id": "Q092", "deck": "av", "topic": "Vestibular differential", "pages": [84], "page": 84, "ref": "slide-av-84", "stem": "A patient has recurrent vertigo with photophobia and migraine headaches but no documented fluctuating SNHL. Which listed diagnosis should be considered?", "options": [{"text": "Vestibular migraine", "why": "Migraine-associated vestibular episodes are a common dizziness differential shown in the lecture diagram. The history differs from the cochlear tetrad of Meniere disease."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}], "answer": 0, "image": null}, {"id": "Q093", "deck": "av", "topic": "Vestibular differential", "pages": [84], "page": 84, "ref": "slide-av-84", "stem": "An older adult feels faint when standing; orthostatic BP falls substantially. There is no spinning or positional nystagmus. Which category best explains the episode?", "options": [{"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Orthostatic presyncope", "why": "Dizziness is a broad symptom. Orthostatic hypoperfusion is distinguished from vestibular vertigo by triggers, associated symptoms, and measured hemodynamics."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}], "answer": 3, "image": null}, {"id": "Q094", "deck": "av", "topic": "Vestibular differential", "pages": [86, 90], "page": 86, "ref": "slide-av-86", "stem": "A patient has continuous vertigo even while motionless, rather than isolated seconds-long spells after specific positions. Hearing is normal. Which peripheral syndrome is more likely than BPPV?", "options": [{"text": "Vestibular neuritis", "why": "Head movement worsens many vestibular disorders, but BPPV is characterized by brief triggered episodes. A sustained acute vestibular syndrome requires a broader, including central, evaluation."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 0, "image": null}, {"id": "Q095", "deck": "av", "topic": "Vestibular differential", "pages": [91, 96], "page": 91, "ref": "slide-av-91", "stem": "Which diagnosis is more likely when acute sustained vertigo and new hearing loss occur together during a serious ear infection?", "options": [{"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Labyrinthitis", "why": "Labyrinthitis involves cochlear as well as vestibular structures. Meniere disease is typically episodic and not defined by an acute infectious spread."}], "answer": 4, "image": null}, {"id": "Q096", "deck": "av", "topic": "Vestibular differential", "pages": [97], "page": 97, "ref": "slide-av-97", "stem": "A patient with years of recurrent vertigo and fluctuating hearing loss now has fewer acute attacks but chronic imbalance and persistent moderate hearing impairment. Which disorder has this described late course?", "options": [{"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Meniere disease", "why": "A late 'burnt-out' pattern can include reduced attack frequency with chronic disequilibrium and lasting hearing loss. The lecture’s 50-dB/50%-WRS description is illustrative rather than universal."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}], "answer": 1, "image": null}, {"id": "Q097", "deck": "av", "topic": "Vestibular end organs", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "Which end organ is most important for detecting horizontal translation in a car?", "options": [{"text": "Saccule", "why": "The saccular macula is especially sensitive to vertical linear acceleration and gravity-related orientation."}, {"text": "Utricle", "why": "The utricular macula is oriented to detect horizontal linear acceleration and head tilt. It belongs to the otolith system."}, {"text": "Semicircular canals", "why": "Canal cristae detect angular acceleration through endolymph-induced cupular deflection; they are not primarily linear-acceleration sensors."}, {"text": "Spiral ganglion", "why": "Spiral ganglion neurons carry cochlear auditory signals to the brainstem; vestibular afferent cell bodies are in the vestibular ganglion."}, {"text": "Cochlea", "why": "Cochlear hair cells transduce acoustic vibrations for hearing, rather than serving as the primary vestibular acceleration sensors."}], "answer": 1, "image": null}, {"id": "Q098", "deck": "av", "topic": "Vestibular end organs", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "Which end organ is especially relevant when an elevator begins accelerating upward?", "options": [{"text": "Saccule", "why": "The saccule preferentially detects vertical linear acceleration. The semicircular canals encode angular acceleration rather than elevator translation."}, {"text": "Cochlea", "why": "Cochlear hair cells transduce acoustic vibrations for hearing, rather than serving as the primary vestibular acceleration sensors."}, {"text": "Semicircular canals", "why": "Canal cristae detect angular acceleration through endolymph-induced cupular deflection; they are not primarily linear-acceleration sensors."}, {"text": "Utricle", "why": "The utricular macula primarily detects horizontal linear acceleration and head tilt relative to gravity; its otoconia can dislodge into a semicircular canal."}, {"text": "Spiral ganglion", "why": "Spiral ganglion neurons carry cochlear auditory signals to the brainstem; vestibular afferent cell bodies are in the vestibular ganglion."}], "answer": 0, "image": null}, {"id": "Q099", "deck": "av", "topic": "Vestibular end organs", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "Which structures are primarily stimulated when the head begins rotating to the right?", "options": [{"text": "Saccule", "why": "The saccular macula is especially sensitive to vertical linear acceleration and gravity-related orientation."}, {"text": "Spiral ganglion", "why": "Spiral ganglion neurons carry cochlear auditory signals to the brainstem; vestibular afferent cell bodies are in the vestibular ganglion."}, {"text": "Semicircular canals", "why": "Angular acceleration displaces endolymph relative to the canal and deflects the cupula over the crista hair cells."}, {"text": "Utricle", "why": "The utricular macula primarily detects horizontal linear acceleration and head tilt relative to gravity; its otoconia can dislodge into a semicircular canal."}, {"text": "Cochlea", "why": "Cochlear hair cells transduce acoustic vibrations for hearing, rather than serving as the primary vestibular acceleration sensors."}], "answer": 2, "image": null}, {"id": "Q100", "deck": "av", "topic": "Vestibular end organs", "pages": [72, 86, 87], "page": 72, "ref": "slide-av-72", "stem": "Otoconia causing typical posterior canal BPPV most commonly originate from which end organ?", "options": [{"text": "Saccule", "why": "The saccular macula is especially sensitive to vertical linear acceleration and gravity-related orientation."}, {"text": "Spiral ganglion", "why": "Spiral ganglion neurons carry cochlear auditory signals to the brainstem; vestibular afferent cell bodies are in the vestibular ganglion."}, {"text": "Semicircular canals", "why": "Canal cristae detect angular acceleration through endolymph-induced cupular deflection; they are not primarily linear-acceleration sensors."}, {"text": "Utricle", "why": "Dislodged utricular otoconia can enter a semicircular canal or adhere to its cupula. They are not normally produced by cochlear auditory hair cells."}, {"text": "Cochlea", "why": "Cochlear hair cells transduce acoustic vibrations for hearing, rather than serving as the primary vestibular acceleration sensors."}], "answer": 3, "image": null}, {"id": "Q101", "deck": "av", "topic": "Vestibular end organs", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "Which inner-ear structure contains the sensory organ for sound rather than gravity or acceleration?", "options": [{"text": "Semicircular canals", "why": "Canal cristae detect angular acceleration through endolymph-induced cupular deflection; they are not primarily linear-acceleration sensors."}, {"text": "Utricle", "why": "The utricular macula primarily detects horizontal linear acceleration and head tilt relative to gravity; its otoconia can dislodge into a semicircular canal."}, {"text": "Spiral ganglion", "why": "Spiral ganglion neurons carry cochlear auditory signals to the brainstem; vestibular afferent cell bodies are in the vestibular ganglion."}, {"text": "Cochlea", "why": "The organ of Corti in the cochlea supports hearing. Utricle, saccule, and canals support vestibular sensing."}, {"text": "Saccule", "why": "The saccular macula is especially sensitive to vertical linear acceleration and gravity-related orientation."}], "answer": 3, "image": null}, {"id": "Q102", "deck": "av", "topic": "Vestibular transduction", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "What mechanically stimulates canal hair cells during angular acceleration?", "options": [{"text": "Light-induced cGMP breakdown", "why": "This is photoreceptor transduction."}, {"text": "An air-bone gap in the external canal", "why": "This is an audiometric conductive-loss concept, not vestibular transduction."}, {"text": "Endolymph movement deflecting the cupula", "why": "Fluid inertia bends the cupula and hair bundles at the canal crista. Otolith maculae instead use an otoconial membrane for linear/gravitational signals."}, {"text": "Sound vibration of the tympanic membrane alone", "why": "This is the initial auditory conduction step, not the canal acceleration mechanism."}, {"text": "Direct stapes contact with vestibular nerve axons", "why": "Stapes motion acts through inner-ear fluid, not direct axonal contact."}], "answer": 2, "image": null}, {"id": "Q103", "deck": "av", "topic": "Vestibular transduction", "pages": [72, 73], "page": 72, "ref": "slide-av-72", "stem": "Which feature distinguishes otolith organs from semicircular canals?", "options": [{"text": "Canals contain the organ of Corti", "why": "The organ of Corti is cochlear."}, {"text": "Otolith organs detect only high-frequency sound", "why": "Their main function is vestibular orientation and translation sensing."}, {"text": "Otolith organs have no hair cells", "why": "Macular hair cells are their sensory transducers."}, {"text": "Otolith organs use a weighted membrane to sense linear acceleration and gravity", "why": "Utricle and saccule contain otoconia. Canals use a cupula and endolymph dynamics to detect angular acceleration."}, {"text": "Only canals are inner-ear structures", "why": "Both are in the vestibular labyrinth."}], "answer": 3, "image": null}, {"id": "Q104", "deck": "av", "topic": "Balance integration", "pages": [74, 75], "page": 74, "ref": "slide-av-74", "stem": "Which three major sensory streams support stable stance?", "options": [{"text": "Only vision, with vestibular input unnecessary", "why": "Vestibular function contributes strongly during movement and when vision is unreliable."}, {"text": "Only hearing, taste, and smell", "why": "These are not the three primary balance streams illustrated."}, {"text": "Vestibular, visual, and proprioceptive input", "why": "These inputs are integrated with CNS processing and motor output. Losing one increases dependence on the others."}, {"text": "Only the labyrinth without central integration", "why": "Vestibular nuclei, cerebellum, and other CNS systems integrate and adapt the input."}, {"text": "Only joint receptors, with vision irrelevant", "why": "Visual information contributes to orientation and stability."}], "answer": 2, "image": null}, {"id": "Q105", "deck": "av", "topic": "Balance integration", "pages": [76], "page": 76, "ref": "slide-av-76", "stem": "What is the principal role of the vestibulo-ocular reflex?", "options": [{"text": "Amplify external sounds at the tympanic membrane", "why": "This is middle-ear mechanics rather than VOR function."}, {"text": "Keep retinal images stable during head movement", "why": "The VOR produces compensatory eye movement opposite head movement, maintaining gaze on a target."}, {"text": "Produce endolymph in the cochlea", "why": "Stria vascularis contributes to endolymph homeostasis."}, {"text": "Generate conscious language comprehension", "why": "This involves cortical auditory-language networks."}, {"text": "Contract the pupil in bright light", "why": "The pupillary light reflex is a different circuit."}], "answer": 1, "image": null}, {"id": "Q106", "deck": "av", "topic": "Balance integration", "pages": [76, 78], "page": 76, "ref": "slide-av-76", "stem": "What is the principal role of vestibulospinal responses?", "options": [{"text": "Transmit smell from the nose", "why": "This is an olfactory pathway."}, {"text": "Replace all visual feedback", "why": "Postural control continues to use multiple sensory inputs."}, {"text": "Convert sound into cochlear receptor potentials", "why": "This is auditory transduction."}, {"text": "Produce pupil dilation for an eye examination", "why": "This is autonomic iris pharmacology."}, {"text": "Adjust postural muscles to maintain orientation and balance", "why": "Vestibular signals influence axial and limb motor activity to stabilize the body as the head and center of gravity move."}], "answer": 4, "image": null}, {"id": "Q107", "deck": "av", "topic": "Balance integration", "pages": [77], "page": 77, "ref": "slide-av-77", "stem": "Which visual problems can worsen balance?", "options": [{"text": "Only color-vision deficiency in every case", "why": "The lecture emphasizes acuity, ocular motor function, and binocular vision rather than a universal isolated color effect."}, {"text": "Visual deficits cannot interact with vestibular loss", "why": "Loss of visual compensation can substantially worsen vestibular imbalance."}, {"text": "Reduced acuity, impaired binocular vision, or abnormal ocular motor control", "why": "Clear visual targets and coordinated eyes support orientation and gaze stability; cataracts and ocular motor disease can reduce these contributions."}, {"text": "A normal retina guarantees normal balance", "why": "Vestibular, proprioceptive, and central deficits can still impair balance."}, {"text": "Vision contributes only when both ears are deaf", "why": "Visual orientation is routinely used for balance."}], "answer": 2, "image": null}, {"id": "Q108", "deck": "av", "topic": "Balance integration", "pages": [78], "page": 78, "ref": "slide-av-78", "stem": "Why can joint disease or reduced sensation at the hips, knees, and ankles worsen balance?", "options": [{"text": "It prevents retinal photopigment formation", "why": "Vitamin A pathways, not joint input, supply retinal chromophore."}, {"text": "It directly destroys cochlear hair cells", "why": "Joint dysfunction does not inherently cause cochleotoxic injury."}, {"text": "It removes all motor strength in every patient", "why": "Proprioceptive impairment can affect balance even without complete weakness."}, {"text": "It improves accuracy by removing conflicting inputs in all cases", "why": "Reduced reliable input usually decreases sensory redundancy."}, {"text": "It reduces proprioceptive feedback used to adjust the center of gravity", "why": "Joint and somatic input helps estimate body position and support postural corrections. Orthopedic and sensory problems can add to vestibular deficits."}], "answer": 4, "image": null}, {"id": "Q109", "deck": "av", "topic": "Multisensory conflict", "pages": [79, 80], "page": 79, "ref": "slide-av-79", "stem": "A patient with vestibular hypofunction remains reasonably stable on a firm floor with eyes open. Which concept explains the benefit of intact vision and joint sensation?", "options": [{"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Multisensory disequilibrium", "why": "Balance systems can compensate for one impaired input by relying on the other two. This question concerns multisensory integration, not proof that every input is normal."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}], "answer": 1, "image": null}, {"id": "Q110", "deck": "av", "topic": "Multisensory conflict", "pages": [79, 80, 81], "page": 79, "ref": "slide-av-79", "stem": "A patient with vestibular loss becomes markedly more unstable when the eyes close, while joint sensation remains available. Which conceptual problem is illustrated?", "options": [{"text": "Multisensory disequilibrium", "why": "Removing visual compensation leaves greater dependence on proprioception. An abnormal balance test must be interpreted with sensory and motor examination."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}, {"text": "Meniere disease", "why": "Spontaneous episodic vertigo with fluctuating, often low-frequency SNHL, tinnitus, and aural fullness fits Meniere disease rather than brief positional spells."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 0, "image": null}, {"id": "Q111", "deck": "av", "topic": "Multisensory conflict", "pages": [79, 80, 81, 82], "page": 79, "ref": "slide-av-79", "stem": "A patient has vestibular impairment and poor vision; standing on foam now further destabilizes the patient. What best explains this deterioration?", "options": [{"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Multisensory disequilibrium", "why": "Foam reduces the reliability of somatosensory information. When all three streams are compromised, redundancy is greatly reduced."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 1, "image": null}, {"id": "Q112", "deck": "av", "topic": "Multisensory conflict", "pages": [79, 80, 83], "page": 79, "ref": "slide-av-79", "stem": "After visual impairment improves, a vestibular-loss patient becomes steadier on a firm surface. Which principle is illustrated?", "options": [{"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Multisensory disequilibrium", "why": "Restoring one reliable sensory stream can improve compensation for another deficit. Improvement does not necessarily mean vestibular hair cells regenerated."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 2, "image": null}, {"id": "Q113", "deck": "av", "topic": "BPPV mechanism", "pages": [86, 87], "page": 86, "ref": "slide-av-86", "stem": "What distinguishes canalithiasis from cupulolithiasis?", "options": [{"text": "Bacterial versus viral invasion of the cochlea", "why": "Those are infectious distinctions, not the two otoconial mechanisms."}, {"text": "Anterior chamber versus trabecular outflow", "why": "These are ocular, not vestibular, structures."}, {"text": "Cochlear versus cortical hearing loss", "why": "These terms describe vestibular particle mechanics."}, {"text": "Free particles within a canal versus particles attached to the cupula", "why": "Both involve displaced otoconia. Particle location changes the mechanics and can affect nystagmus duration and response to maneuvers."}, {"text": "Normal aging versus an RB1 mutation", "why": "Neither defines the particle locations."}], "answer": 3, "image": null}, {"id": "Q114", "deck": "av", "topic": "BPPV testing", "pages": [86, 88], "page": 86, "ref": "slide-av-86", "stem": "Which Dix-Hallpike finding supports typical posterior canal BPPV?", "options": [{"text": "No positional symptoms but continuous vertigo for days", "why": "That is a sustained vestibular syndrome rather than classic brief triggered BPPV."}, {"text": "Pulsatile tinnitus alone", "why": "That requires a different, often vascular, assessment."}, {"text": "Brief torsional-upbeating nystagmus after positioning with the affected ear down", "why": "The response is aligned with the posterior canal and often has a short latency and fatigability. The lecture's geotropic shorthand should not replace the full torsional-upbeat description."}, {"text": "Persistent pure downbeat nystagmus with focal neurologic deficits", "why": "This is a central warning pattern and is not typical posterior canal BPPV."}, {"text": "Only a low-frequency air-bone gap", "why": "That is an auditory conductive finding."}], "answer": 2, "image": "figure-dix.jpg"}, {"id": "Q115", "deck": "av", "topic": "BPPV treatment", "pages": [86, 89], "page": 86, "ref": "slide-av-86", "stem": "What is the goal of the Epley maneuver?", "options": [{"text": "Remove a vestibular schwannoma", "why": "A tumor requires separate management."}, {"text": "Destroy both vestibular nerves", "why": "Epley is nonablative and does not transect nerves."}, {"text": "Treat all dizziness regardless of localization", "why": "Canal-specific repositioning is used for the appropriate BPPV phenotype."}, {"text": "Move canal otoconia back toward the utricle", "why": "Sequential head/body positions use gravity to clear particles from the posterior canal. It is a mechanical repositioning treatment."}, {"text": "Increase endolymph production", "why": "That is not its mechanism."}], "answer": 3, "image": "figure-epley.jpg"}, {"id": "Q116", "deck": "av", "topic": "BPPV treatment", "pages": [86, 89], "page": 86, "ref": "slide-av-86", "stem": "A patient has confirmed posterior canal BPPV. Which approach is preferred over indefinite vestibular suppressant medication?", "options": [{"text": "Antibiotics for all positional vertigo", "why": "BPPV is not normally an infection."}, {"text": "Canalith repositioning or referral to a clinician who performs it", "why": "Repositioning targets the cause. Routine long-term suppressants can cause sedation and do not clear the displaced particles."}, {"text": "Chronic benzodiazepines as the only necessary treatment", "why": "These do not reposition otoconia and can increase fall risk."}, {"text": "Immediate labyrinthectomy in every case", "why": "This destructive operation is not ordinary BPPV treatment."}, {"text": "Cochlear implantation", "why": "This treats selected hearing loss, not a canal particle problem."}], "answer": 1, "image": null}, {"id": "Q117", "deck": "av", "topic": "Vestibular neuritis", "pages": [90], "page": 90, "ref": "slide-av-90", "stem": "Why is new hearing loss important in an apparent vestibular neuritis case?", "options": [{"text": "It makes stroke impossible", "why": "Some posterior circulation events affect auditory and vestibular structures."}, {"text": "Hearing loss is required for vestibular neuritis", "why": "The classic syndrome lacks new cochlear loss."}, {"text": "It proves BPPV", "why": "BPPV usually lacks a new auditory deficit."}, {"text": "It always represents wax regardless of otoscopy", "why": "The deficit requires actual localization."}, {"text": "It suggests cochlear/labyrinthine involvement or another diagnosis", "why": "Pure vestibular neuritis usually spares hearing. Acute hearing loss with vertigo can also occur in vascular disease, so it should not automatically be assumed benign."}], "answer": 4, "image": null}, {"id": "Q118", "deck": "av", "topic": "Labyrinthitis", "pages": [91], "page": 91, "ref": "slide-av-91", "stem": "How can infection or inflammatory products reach the labyrinth?", "options": [{"text": "Through an intact lens capsule", "why": "The lens is unrelated to ear infection spread."}, {"text": "Only through the external pinna without any intervening pathway", "why": "This ignores the anatomic routes described."}, {"text": "Spread from the middle ear or intracranial/meningeal spaces through relevant interfaces", "why": "The lecture lists middle-ear routes, internal auditory canal, and cochlear aqueduct. Toxic/inflammatory mediators and frank bacteria can cause different severities."}, {"text": "Only after surgical destruction of both ears", "why": "Labyrinthitis can occur without surgery."}, {"text": "Only by a visual cortex lesion", "why": "Cortical visual injury is not a route of labyrinthine infection."}], "answer": 2, "image": null}, {"id": "Q119", "deck": "av", "topic": "Labyrinthitis", "pages": [91], "page": 91, "ref": "slide-av-91", "stem": "Suppurative labyrinthitis is suspected in a patient with bacterial ear infection, vertigo, and new hearing loss. Which treatment principle is essential?", "options": [{"text": "Only an Epley maneuver", "why": "Repositioning does not treat suppurative disease."}, {"text": "Urgent antibiotics and management of the infectious source, with supportive vestibular care", "why": "Vestibular suppressants or antiemetics alone do not control bacterial infection. Steroids may be considered in selected circumstances, but cannot replace antibiotics/source management."}, {"text": "Treat with hearing-aid fitting before addressing infection", "why": "Rehabilitation does not replace acute source control."}, {"text": "Delay treatment until permanent deafness confirms the diagnosis", "why": "Delay can worsen complications."}, {"text": "Only long-term meclizine", "why": "Symptom suppression does not eradicate infection."}], "answer": 1, "image": null}, {"id": "Q120", "deck": "av", "topic": "Vestibular treatment", "pages": [90, 105, 109], "page": 90, "ref": "slide-av-90", "stem": "After exclusion of a central cause, a patient with vestibular neuritis has severe nausea early in the illness. Which overall plan best balances immediate comfort with recovery?", "options": [{"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}, {"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Short-term symptom relief followed by rehabilitation", "why": "Brief symptom-directed medication may help acutely, while activity and vestibular rehabilitation support compensation. Corticosteroid benefit is context-dependent rather than guaranteed."}], "answer": 4, "image": null}, {"id": "Q121", "deck": "av", "topic": "Vestibular treatment", "pages": [98], "page": 98, "ref": "slide-av-98", "stem": "During a severe Meniere attack, a patient needs nausea control and temporary reduction of vestibular symptoms. Which management category is appropriate?", "options": [{"text": "Vestibular rehabilitation", "why": "Gaze, stance, gait, and habituation exercises promote central adaptation and sensory reweighting rather than regrowing lost hair cells."}, {"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Vestibular nerve section", "why": "Selective section aims to control disabling vertigo while preserving cochlear function when feasible; it is an invasive intracranial procedure."}, {"text": "Short-term symptom relief followed by rehabilitation", "why": "Meclizine or selected sedating agents reduce acute vestibular symptoms; antiemetics such as ondansetron address nausea. Ondansetron is not a vestibular suppressant in the same mechanistic sense."}], "answer": 4, "image": null}, {"id": "Q122", "deck": "av", "topic": "Vestibular treatment", "pages": [100], "page": 100, "ref": "slide-av-100", "stem": "A refractory Meniere patient undergoes an operation intended to improve endolymphatic sac pressure/drainage without intentionally destroying the labyrinth. Which procedure is this?", "options": [{"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This is a sac-directed nonablative operation. The presence of hydrops does not guarantee success, and evidence/selection must be discussed."}, {"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Vestibular nerve section", "why": "Selective section aims to control disabling vertigo while preserving cochlear function when feasible; it is an invasive intracranial procedure."}, {"text": "Short-term symptom relief followed by rehabilitation", "why": "Acute suppressants/antiemetics may help severe vertigo, but prolonged suppression can hinder compensation and increase sedation."}], "answer": 1, "image": null}, {"id": "Q123", "deck": "av", "topic": "Vestibular treatment", "pages": [101], "page": 101, "ref": "slide-av-101", "stem": "A patient has disabling refractory unilateral vertigo and nonserviceable hearing. The operation deliberately removes or destroys labyrinthine function. Which procedure is described?", "options": [{"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}, {"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Vestibular rehabilitation", "why": "Gaze, stance, gait, and habituation exercises promote central adaptation and sensory reweighting rather than regrowing lost hair cells."}, {"text": "Labyrinthectomy", "why": "Labyrinthectomy is ablative and sacrifices residual hearing. Compensation requires an effective contralateral system and central adaptation."}, {"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}], "answer": 3, "image": null}, {"id": "Q124", "deck": "av", "topic": "Vestibular treatment", "pages": [102], "page": 102, "ref": "slide-av-102", "stem": "Which operation attempts to disconnect vestibular signals while retaining the cochlear nerve in selected severe refractory Meniere disease?", "options": [{"text": "Vestibular rehabilitation", "why": "Gaze, stance, gait, and habituation exercises promote central adaptation and sensory reweighting rather than regrowing lost hair cells."}, {"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Short-term symptom relief followed by rehabilitation", "why": "Acute suppressants/antiemetics may help severe vertigo, but prolonged suppression can hinder compensation and increase sedation."}, {"text": "Vestibular nerve section", "why": "Vestibular neurectomy may preserve hearing better than labyrinthectomy, though surgery carries intracranial and cranial nerve risks."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}], "answer": 3, "image": null}, {"id": "Q125", "deck": "av", "topic": "Vestibular treatment", "pages": [103], "page": 103, "ref": "slide-av-103", "stem": "A specialist treats refractory Meniere vertigo with a middle-ear injection intended to reduce vestibular sensory function. Which treatment is most consistent?", "options": [{"text": "Vestibular nerve section", "why": "Selective section aims to control disabling vertigo while preserving cochlear function when feasible; it is an invasive intracranial procedure."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}, {"text": "Intratympanic gentamicin", "why": "Gentamicin crosses into the inner ear and exploits vestibulotoxicity to reduce attacks. Hearing damage and excessive vestibular loss remain important risks."}, {"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}], "answer": 3, "image": "figure-intratympanic.jpg"}, {"id": "Q126", "deck": "av", "topic": "Vestibular treatment", "pages": [105, 106, 109], "page": 105, "ref": "slide-av-105", "stem": "A patient has persistent gaze instability and imbalance after unilateral vestibular injury. Which therapy targets adaptation rather than simply suppressing symptoms?", "options": [{"text": "Vestibular rehabilitation", "why": "Exercises promote compensation, gaze stability, sensory reweighting, and gait function. They depend on active CNS plasticity and individualized progression."}, {"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}], "answer": 0, "image": null}, {"id": "Q127", "deck": "av", "topic": "Vestibular treatment", "pages": [110], "page": 110, "ref": "slide-av-110", "stem": "The patient fixes the eyes on a stationary target while turning the head repeatedly, as shown. What treatment category is illustrated?", "options": [{"text": "Vestibular rehabilitation", "why": "Gaze-stabilization exercises train compensatory vestibulo-ocular performance. The goal is better visual stability during head movement."}, {"text": "Short-term symptom relief followed by rehabilitation", "why": "Acute suppressants/antiemetics may help severe vertigo, but prolonged suppression can hinder compensation and increase sedation."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Intratympanic gentamicin", "why": "Local aminoglycoside treatment chemically reduces vestibular function but can damage hearing; dosing and candidacy require specialist care."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}], "answer": 0, "image": "figure-gaze.jpg"}, {"id": "Q128", "deck": "av", "topic": "Vestibular treatment", "pages": [111, 112], "page": 111, "ref": "slide-av-111", "stem": "A therapist uses graded stance, gait, and sensory-conflict activities for persistent imbalance. Which approach is being used?", "options": [{"text": "Epley canalith repositioning", "why": "This treats posterior canal BPPV by moving displaced particles, not endolymphatic hydrops."}, {"text": "Endolymphatic sac decompression or shunt", "why": "This attempts a nonablative sac-directed approach in selected refractory Meniere cases; benefit and selection require discussion."}, {"text": "Vestibular nerve section", "why": "Selective section aims to control disabling vertigo while preserving cochlear function when feasible; it is an invasive intracranial procedure."}, {"text": "Labyrinthectomy", "why": "This destroys labyrinthine vestibular function and sacrifices hearing, usually reserved for severe refractory disease with nonserviceable hearing."}, {"text": "Vestibular rehabilitation", "why": "Balance retraining varies sensory reliability and task demands to improve integration. Computerized posturography can help assess sensory dependence but does not itself prove one diagnosis."}], "answer": 4, "image": null}, {"id": "Q129", "deck": "av", "topic": "Meniere pathophysiology", "pages": [92, 93, 94, 95], "page": 92, "ref": "slide-av-92", "stem": "Which histopathologic change is associated with Meniere disease?", "options": [{"text": "Loss of all external canal skin", "why": "This is not the classic Meniere correlate."}, {"text": "A keratin sac eroding the ossicles", "why": "This is cholesteatoma, a middle-ear lesion."}, {"text": "An isolated vestibular nerve tumor", "why": "That suggests schwannoma rather than hydrops."}, {"text": "Distention of the endolymphatic compartment", "why": "Endolymphatic hydrops is the classic correlate, including enlargement of the cochlear duct. Hydrops and symptoms have a complex relationship, so it is not a complete single-cause explanation in every case."}, {"text": "Stapes footplate fixation", "why": "This is otosclerosis, a conductive mechanism."}], "answer": 3, "image": "figure-hydrops.jpg"}, {"id": "Q130", "deck": "av", "topic": "Endolymph homeostasis", "pages": [95], "page": 95, "ref": "slide-av-95", "stem": "Which cells/structures contribute to endolymph production in the auditory and vestibular labyrinth?", "options": [{"text": "Only the tympanic membrane", "why": "The eardrum does not produce inner-ear endolymph."}, {"text": "Only the external canal ceruminous glands", "why": "These produce wax, not cochlear endolymph."}, {"text": "Only the malleus and incus", "why": "Ossicles transmit vibration rather than secrete endolymph."}, {"text": "Only retinal pigment epithelium", "why": "That tissue serves the eye, not the labyrinth."}, {"text": "Stria vascularis and vestibular dark cells", "why": "They help maintain the specialized endolymph ionic environment. Disrupted secretion, resorption, or homeostasis can contribute to hydrops."}], "answer": 4, "image": null}, {"id": "Q131", "deck": "av", "topic": "Meniere course", "pages": [96, 97], "page": 96, "ref": "slide-av-96", "stem": "Which hearing pattern is particularly characteristic early in Meniere disease?", "options": [{"text": "Normal hearing is required at all times", "why": "Documented SNHL is part of definite Meniere diagnostic assessment."}, {"text": "Only a 4-kHz noise notch with no episodic symptoms", "why": "That suggests noise injury rather than the classic Meniere pattern."}, {"text": "Complete recovery of all hearing is guaranteed between every attack", "why": "Residual or progressive loss can occur."}, {"text": "Fluctuating low-frequency sensorineural loss", "why": "Low-frequency cochlear impairment can accompany attacks; hearing may progressively worsen and flatten over time. Bilateral involvement is possible but not inevitable."}, {"text": "A stable isolated conductive gap from birth", "why": "That is a different mechanism and course."}], "answer": 3, "image": null}, {"id": "Q132", "deck": "av", "topic": "Meniere management", "pages": [98, 99], "page": 98, "ref": "slide-av-98", "stem": "Which maintenance measures are discussed in the lecture for Meniere disease?", "options": [{"text": "Only repeated Epley maneuvers regardless of symptoms", "why": "Epley treats canal BPPV, not the Meniere syndrome itself."}, {"text": "A cochlear implant as universal first-line vertigo prevention", "why": "Implants primarily rehabilitate selected hearing loss and are not universal Meniere maintenance treatment."}, {"text": "Unlimited noise exposure to retrain the cochlea", "why": "Noise can cause additional auditory injury."}, {"text": "Long-term high-dose gentamicin for every mild case", "why": "Destructive therapy is reserved for selected refractory disease because of hearing/vestibular risks."}, {"text": "Dietary/lifestyle counseling and selected diuretics or betahistine", "why": "The deck includes sodium reduction, moderation of caffeine/alcohol, sleep, and diuretics. Evidence varies and betahistine availability differs by country; these are not guaranteed cures."}], "answer": 4, "image": null}, {"id": "Q133", "deck": "av", "topic": "Meniere medications", "pages": [99], "page": 99, "ref": "slide-av-99", "stem": "Which medication is a carbonic anhydrase inhibitor mentioned as a diuretic option in the lecture?", "options": [{"text": "Hydrochlorothiazide", "why": "This is a thiazide, not a carbonic anhydrase inhibitor."}, {"text": "Acetazolamide", "why": "Diamox inhibits carbonic anhydrase. The same class also reduces aqueous production in ophthalmology; clinical use and risk assessment depend on the indication."}, {"text": "Meclizine", "why": "This is an antihistaminic vestibular suppressant, not a diuretic."}, {"text": "Betahistine", "why": "This is a histamine-related agent rather than a carbonic anhydrase inhibitor."}, {"text": "Triamterene", "why": "This is a potassium-sparing epithelial sodium-channel blocker."}], "answer": 1, "image": null}, {"id": "Q134", "deck": "av", "topic": "Meniere medications", "pages": [99], "page": 99, "ref": "slide-av-99", "stem": "Dyazide and Maxzide are commonly recognized combinations of which agents?", "options": [{"text": "Atropine and tropicamide", "why": "These are ocular antimuscarinics."}, {"text": "Gentamicin and cisplatin", "why": "These are ototoxic drug examples, not the diuretic product."}, {"text": "Meclizine and ondansetron", "why": "These are symptom-control agents rather than the named maintenance diuretic combination."}, {"text": "Acetazolamide and mannitol", "why": "These are carbonic anhydrase and osmotic agents, not the named combination."}, {"text": "Hydrochlorothiazide and triamterene", "why": "The combination pairs a thiazide with a potassium-sparing agent. Calling the entire product simply a potassium-sparing class omits its thiazide component."}], "answer": 4, "image": null}, {"id": "Q135", "deck": "av", "topic": "Meniere medications", "pages": [99], "page": 99, "ref": "slide-av-99", "stem": "Which statement best describes betahistine as discussed in the lecture?", "options": [{"text": "A prostaglandin eye-drop analog", "why": "That describes a different pharmacologic class."}, {"text": "A direct muscarinic agonist that clears canal particles", "why": "That neither identifies betahistine nor describes BPPV treatment correctly."}, {"text": "A ventilation tube inserted through the eardrum", "why": "Betahistine is a medication, not a tympanostomy device."}, {"text": "A histamine-related agent used for Meniere symptoms in some countries", "why": "It has histaminergic actions and is proposed to affect inner-ear circulation/neurotransmission. Efficacy certainty and regulatory availability vary; it is not a universal proven cure."}, {"text": "A platinum chemotherapy drug", "why": "That describes cisplatin rather than betahistine."}], "answer": 3, "image": null}, {"id": "Q136", "deck": "av", "topic": "Central compensation", "pages": [105, 106], "page": 105, "ref": "slide-av-105", "stem": "Which two broad phases of vestibular compensation are described?", "options": [{"text": "Permanent suppression of all sensory input followed by immobility", "why": "Active adaptation requires useful sensory experience and movement."}, {"text": "Universal hair-cell regeneration followed by new cochlear growth", "why": "Human sensory-cell replacement does not account for ordinary compensation."}, {"text": "Reduction of acute asymmetry followed by recalibration of neural activity", "why": "Central plasticity reduces static imbalance and adapts dynamic responses. Recovery depends on injury severity, remaining inputs, and CNS health."}, {"text": "Immediate normal function followed by inevitable complete paralysis", "why": "This is not the usual compensation framework."}, {"text": "Removal of the healthy labyrinth followed by elimination of vision", "why": "Destroying remaining inputs worsens redundancy."}], "answer": 2, "image": null}, {"id": "Q137", "deck": "av", "topic": "Central compensation", "pages": [107], "page": 107, "ref": "slide-av-107", "stem": "After initial vestibular recovery, illness and sedating medication lead to renewed imbalance. Which pattern is illustrated?", "options": [{"text": "Decompensation", "why": "Previously adequate compensation can deteriorate when health, medication exposure, or sensory conditions change. This differs from never achieving adequate recovery."}, {"text": "Successful complete recovery by definition", "why": "Symptoms have worsened again."}, {"text": "Pure conductive hearing loss as the only explanation", "why": "A middle-ear threshold gap does not explain the entire compensation course."}, {"text": "Normal aging without any clinical significance", "why": "Fall risk and functional deterioration warrant reassessment."}, {"text": "Guaranteed new bilateral hair-cell destruction", "why": "Renewed symptoms do not automatically prove a new peripheral structural injury."}], "answer": 0, "image": null}, {"id": "Q138", "deck": "av", "topic": "Central compensation", "pages": [107, 108], "page": 107, "ref": "slide-av-107", "stem": "Which feature can delay vestibular compensation?", "options": [{"text": "Graded gaze and balance practice in all cases", "why": "Appropriate rehabilitation generally promotes adaptation rather than uniformly delaying it."}, {"text": "Older age, CNS comorbidity, or prolonged vestibular suppressant exposure", "why": "Adaptation depends on CNS plasticity and adequate sensory experience. Recovery and residual deficits vary across patients."}, {"text": "Appropriate mobility training", "why": "Activity-based rehabilitation helps many patients."}, {"text": "A stable reliable proprioceptive system", "why": "Reliable remaining input supports balance."}, {"text": "Restored visual acuity", "why": "Reliable vision can support compensation."}], "answer": 1, "image": null}, {"id": "Q139", "deck": "av", "topic": "Vestibular rehabilitation", "pages": [109, 110, 111, 112], "page": 109, "ref": "slide-av-109", "stem": "What distinguishes habituation from simply avoiding all provoking movement?", "options": [{"text": "Permanent avoidance is required to create CNS plasticity", "why": "Avoidance can limit adaptive sensory experience."}, {"text": "Repeated graded exposure reduces an excessive response to a tolerated stimulus", "why": "Habituation exercises aim to decrease pathologic motion sensitivity. They are tailored to safety and diagnosis; they are not unrestricted exposure during an undiagnosed acute emergency."}, {"text": "It is identical to antibiotic eradication of infection", "why": "Behavioral adaptation and antimicrobial treatment are different mechanisms."}, {"text": "It restores lost cochlear hair cells", "why": "Habituation changes responses, not sensory-cell number."}, {"text": "Habituation means destroying the vestibular nerve", "why": "It is a learning/adaptation process, not ablation."}], "answer": 1, "image": null}, {"id": "Q140", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [2, 12], "page": 2, "ref": "slide-oph-2", "stem": "Which alpha-1 agonist dilates the pupil without directly paralyzing accommodation?", "options": [{"text": "Phenylephrine", "why": "Radial iris dilator contraction causes mydriasis. Unlike antimuscarinics, phenylephrine does not directly block ciliary accommodation."}, {"text": "Betaxolol", "why": "A relatively beta-1-selective blocker lowers IOP, with less beta-2 blockade than timolol but continued potential cardiopulmonary risk."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}, {"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}], "answer": 0, "image": null}, {"id": "Q141", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "Which muscarinic antagonist has the longest mydriatic/cycloplegic duration among atropine, cyclopentolate, and tropicamide?", "options": [{"text": "Apraclonidine", "why": "An alpha-2 agonist reduces aqueous production; local allergic reactions can limit sustained use."}, {"text": "Acetazolamide", "why": "A systemic carbonic anhydrase inhibitor reduces aqueous formation and can cause metabolic acidosis, hypokalemia, paresthesias, and stones."}, {"text": "Betaxolol", "why": "A relatively beta-1-selective blocker lowers IOP, with less beta-2 blockade than timolol but continued potential cardiopulmonary risk."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}, {"text": "Atropine", "why": "The lecture gives atropine roughly 7–14 days, cyclopentolate about 24 hours, and tropicamide about six hours; actual duration varies with patient and formulation."}], "answer": 4, "image": null}, {"id": "Q142", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "A diagnostic antimuscarinic eye drop has a lecture-listed duration of about six hours. Which agent fits?", "options": [{"text": "Tropicamide", "why": "Tropicamide is relatively short acting, making it useful for routine diagnostic dilation. It can still blur near vision and increase angle-closure risk in susceptible eyes."}, {"text": "Acetazolamide", "why": "A systemic carbonic anhydrase inhibitor reduces aqueous formation and can cause metabolic acidosis, hypokalemia, paresthesias, and stones."}, {"text": "Brimonidine", "why": "An alpha-2 agonist reduces aqueous production and increases uveoscleral outflow; allergy and CNS effects are relevant."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}, {"text": "Cyclopentolate", "why": "An antimuscarinic cycloplegic commonly used for refraction has an intermediate duration relative to tropicamide and atropine."}], "answer": 0, "image": null}, {"id": "Q143", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "A child receives cycloplegic refraction with an antimuscarinic whose lecture-listed duration is about 24 hours. Which agent fits?", "options": [{"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}, {"text": "Cyclopentolate", "why": "Cyclopentolate is intermediate in duration compared with shorter tropicamide and much longer atropine."}, {"text": "Tropicamide", "why": "A relatively short-acting muscarinic antagonist is used for diagnostic mydriasis and can also impair accommodation."}, {"text": "Pilocarpine", "why": "A direct muscarinic agonist contracts the iris sphincter and ciliary muscle, causing miosis and increasing trabecular outflow."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}], "answer": 1, "image": null}, {"id": "Q144", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "Which nonselective beta-blocker eye drop can worsen asthma while lowering aqueous production?", "options": [{"text": "Brimonidine", "why": "An alpha-2 agonist reduces aqueous production and increases uveoscleral outflow; allergy and CNS effects are relevant."}, {"text": "Timolol", "why": "Ophthalmic timolol can be absorbed systemically, producing beta-2 bronchospasm and beta-1 cardiac effects. Topical delivery does not eliminate systemic contraindications."}, {"text": "Acetazolamide", "why": "A systemic carbonic anhydrase inhibitor reduces aqueous formation and can cause metabolic acidosis, hypokalemia, paresthesias, and stones."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}, {"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}], "answer": 1, "image": null}, {"id": "Q145", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "Which glaucoma beta blocker is relatively beta-1 selective compared with timolol?", "options": [{"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}, {"text": "Betaxolol", "why": "Betaxolol is relatively beta-1 selective; the slide’s blanket description of all agents as beta-2 blockers is oversimplified. Selectivity does not make it risk-free in pulmonary or cardiac disease."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}, {"text": "Tropicamide", "why": "A relatively short-acting muscarinic antagonist is used for diagnostic mydriasis and can also impair accommodation."}], "answer": 1, "image": null}, {"id": "Q146", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [5, 10], "page": 5, "ref": "slide-oph-5", "stem": "Which listed glaucoma drug reduces aqueous synthesis through alpha-2 activation and secondarily increases uveoscleral outflow?", "options": [{"text": "Acetazolamide", "why": "A systemic carbonic anhydrase inhibitor reduces aqueous formation and can cause metabolic acidosis, hypokalemia, paresthesias, and stones."}, {"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}, {"text": "Phenylephrine", "why": "An alpha-1 agonist contracts the radial iris dilator, producing mydriasis without direct cycloplegia."}, {"text": "Brimonidine", "why": "Brimonidine is an alpha-2 agonist. Its mechanism differs from phenylephrine’s alpha-1-mediated dilation; local allergy and systemic sedation can occur."}], "answer": 4, "image": null}, {"id": "Q147", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [5], "page": 5, "ref": "slide-oph-5", "stem": "Which mixed alpha/beta agonist is no longer routinely used for glaucoma and should be avoided in angle-closure glaucoma because it can cause mydriasis?", "options": [{"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Epinephrine", "why": "Epinephrine can initially stimulate beta-mediated aqueous production, with later pressure-lowering effects through other actions. Pupil dilation can worsen angle closure in a susceptible eye."}, {"text": "Apraclonidine", "why": "An alpha-2 agonist reduces aqueous production; local allergic reactions can limit sustained use."}, {"text": "Pilocarpine", "why": "A direct muscarinic agonist contracts the iris sphincter and ciliary muscle, causing miosis and increasing trabecular outflow."}, {"text": "Brinzolamide", "why": "A topical carbonic anhydrase inhibitor lowers aqueous production; local irritation or taste disturbance can occur."}], "answer": 1, "image": null}, {"id": "Q148", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "An oral glaucoma medication causes tingling, low bicarbonate, and potassium depletion. Which agent is most likely?", "options": [{"text": "Acetazolamide", "why": "Systemic carbonic anhydrase inhibition causes renal bicarbonate loss and related adverse effects while also decreasing ciliary aqueous secretion."}, {"text": "Betaxolol", "why": "A relatively beta-1-selective blocker lowers IOP, with less beta-2 blockade than timolol but continued potential cardiopulmonary risk."}, {"text": "Apraclonidine", "why": "An alpha-2 agonist reduces aqueous production; local allergic reactions can limit sustained use."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}, {"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}], "answer": 0, "image": null}, {"id": "Q149", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "Which listed topical glaucoma drug inhibits carbonic anhydrase in ciliary epithelium?", "options": [{"text": "Dorzolamide", "why": "Dorzolamide is a topical CA inhibitor. It shares the aqueous-production mechanism of acetazolamide with generally lower systemic exposure."}, {"text": "Tropicamide", "why": "A relatively short-acting muscarinic antagonist is used for diagnostic mydriasis and can also impair accommodation."}, {"text": "Latanoprost", "why": "A PGF2-alpha analog increases uveoscleral outflow and can darken iris pigmentation and increase eyelashes."}, {"text": "Timolol", "why": "A nonselective beta blocker reduces aqueous production but can cause systemic bradycardia and bronchospasm."}, {"text": "Brimonidine", "why": "An alpha-2 agonist reduces aqueous production and increases uveoscleral outflow; allergy and CNS effects are relevant."}], "answer": 0, "image": null}, {"id": "Q150", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "Which listed topical carbonic anhydrase inhibitor can reduce aqueous production while limiting systemic exposure compared with oral acetazolamide?", "options": [{"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}, {"text": "Apraclonidine", "why": "An alpha-2 agonist reduces aqueous production; local allergic reactions can limit sustained use."}, {"text": "Brinzolamide", "why": "Brinzolamide, like dorzolamide, reduces aqueous production through ciliary carbonic anhydrase inhibition."}, {"text": "Phenylephrine", "why": "An alpha-1 agonist contracts the radial iris dilator, producing mydriasis without direct cycloplegia."}, {"text": "Tropicamide", "why": "A relatively short-acting muscarinic antagonist is used for diagnostic mydriasis and can also impair accommodation."}], "answer": 2, "image": null}, {"id": "Q151", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [6], "page": 6, "ref": "slide-oph-6", "stem": "An emergency IOP-lowering drug works by increasing serum osmolality. Which agent fits?", "options": [{"text": "Tropicamide", "why": "A relatively short-acting muscarinic antagonist is used for diagnostic mydriasis and can also impair accommodation."}, {"text": "Mannitol", "why": "IV mannitol shifts water from ocular tissues toward plasma. It is an osmotic approach rather than inhibition of aqueous synthesis."}, {"text": "Brinzolamide", "why": "A topical carbonic anhydrase inhibitor lowers aqueous production; local irritation or taste disturbance can occur."}, {"text": "Pilocarpine", "why": "A direct muscarinic agonist contracts the iris sphincter and ciliary muscle, causing miosis and increasing trabecular outflow."}, {"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}], "answer": 1, "image": null}, {"id": "Q152", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [7, 10], "page": 7, "ref": "slide-oph-7", "stem": "Which listed PGF2-alpha analog lowers IOP mainly by increasing uveoscleral outflow?", "options": [{"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Cyclopentolate", "why": "An antimuscarinic cycloplegic commonly used for refraction has an intermediate duration relative to tropicamide and atropine."}, {"text": "Timolol", "why": "A nonselective beta blocker reduces aqueous production but can cause systemic bradycardia and bronchospasm."}, {"text": "Latanoprost", "why": "Latanoprost increases uveoscleral outflow. Iris darkening and eyelash growth are characteristic local effects."}, {"text": "Netarsudil", "why": "A Rho kinase inhibitor lowers resistance in the conventional trabecular outflow pathway; conjunctival hyperemia is common."}], "answer": 3, "image": null}, {"id": "Q153", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [7], "page": 7, "ref": "slide-oph-7", "stem": "Which glaucoma-related drug is also marketed in a formulation for eyelash growth as Latisse?", "options": [{"text": "Phenylephrine", "why": "An alpha-1 agonist contracts the radial iris dilator, producing mydriasis without direct cycloplegia."}, {"text": "Apraclonidine", "why": "An alpha-2 agonist reduces aqueous production; local allergic reactions can limit sustained use."}, {"text": "Bimatoprost", "why": "Bimatoprost promotes eyelash growth and is used in glaucoma formulations. Cosmetic efficacy does not mean absence of pigmentation or ocular adverse effects."}, {"text": "Betaxolol", "why": "A relatively beta-1-selective blocker lowers IOP, with less beta-2 blockade than timolol but continued potential cardiopulmonary risk."}, {"text": "Pilocarpine", "why": "A direct muscarinic agonist contracts the iris sphincter and ciliary muscle, causing miosis and increasing trabecular outflow."}], "answer": 2, "image": null}, {"id": "Q154", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [8, 11], "page": 8, "ref": "slide-oph-8", "stem": "Which direct muscarinic agonist lowers IOP by contracting the ciliary muscle and increasing trabecular drainage?", "options": [{"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Pilocarpine", "why": "Pilocarpine activates muscarinic receptors directly, causing miosis and traction on the trabecular drainage apparatus."}, {"text": "Bimatoprost", "why": "A prostaglandin-related ocular agent lowers IOP and can stimulate eyelash growth; its cosmetic formulation is marketed as Latisse."}, {"text": "Brimonidine", "why": "An alpha-2 agonist reduces aqueous production and increases uveoscleral outflow; allergy and CNS effects are relevant."}, {"text": "Brinzolamide", "why": "A topical carbonic anhydrase inhibitor lowers aqueous production; local irritation or taste disturbance can occur."}], "answer": 1, "image": null}, {"id": "Q155", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [8], "page": 8, "ref": "slide-oph-8", "stem": "A drug produces miosis through direct cholinergic receptor stimulation rather than blocking acetylcholinesterase. The agent is also used intraoperatively. Which drug fits?", "options": [{"text": "Carbachol", "why": "Carbachol is a direct cholinergic agonist; echothiophate is an indirect cholinomimetic through enzyme inhibition."}, {"text": "Epinephrine", "why": "A mixed alpha/beta agonist has complex effects on aqueous dynamics and can dilate the pupil; it is not routinely used for glaucoma and is unsuitable in angle-closure risk."}, {"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}, {"text": "Betaxolol", "why": "A relatively beta-1-selective blocker lowers IOP, with less beta-2 blockade than timolol but continued potential cardiopulmonary risk."}, {"text": "Cyclopentolate", "why": "An antimuscarinic cycloplegic commonly used for refraction has an intermediate duration relative to tropicamide and atropine."}], "answer": 0, "image": null}, {"id": "Q156", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [8], "page": 8, "ref": "slide-oph-8", "stem": "Which ocular cholinomimetic inhibits acetylcholinesterase rather than directly activating muscarinic receptors?", "options": [{"text": "Cyclopentolate", "why": "An antimuscarinic cycloplegic commonly used for refraction has an intermediate duration relative to tropicamide and atropine."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}, {"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}, {"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Echothiophate", "why": "Echothiophate prolongs endogenous acetylcholine action, increasing muscarinic effects. It is a long-acting organophosphate-type inhibitor, not the same mechanism as pilocarpine."}], "answer": 4, "image": null}, {"id": "Q157", "deck": "oph", "topic": "Ophthalmic drug identification", "pages": [9], "page": 9, "ref": "slide-oph-9", "stem": "A patient receives Rhopressa, which reduces trabecular cellular stiffness and outflow resistance. Which generic agent is this?", "options": [{"text": "Mannitol", "why": "An osmotic agent increases plasma osmolality and shifts water out of ocular tissues to rapidly lower IOP in selected emergencies."}, {"text": "Echothiophate", "why": "A long-acting acetylcholinesterase inhibitor increases endogenous acetylcholine, indirectly producing miosis and increased trabecular outflow."}, {"text": "Carbachol", "why": "A direct cholinergic agonist produces muscarinic ocular effects such as miosis and ciliary contraction; it is not an acetylcholinesterase inhibitor."}, {"text": "Netarsudil", "why": "Netarsudil inhibits Rho kinase and improves conventional outflow. Ripasudil is another Rho kinase inhibitor named in the lecture, with availability differing by region."}, {"text": "Atropine", "why": "A long-acting muscarinic antagonist causes both mydriasis and cycloplegia, with effects lasting days."}], "answer": 3, "image": null}, {"id": "Q158", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [2, 12], "page": 2, "ref": "slide-oph-2", "stem": "What mechanism explains both dilation and cycloplegia after atropine eye drops?", "options": [{"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Alpha-2 receptor activation", "why": "This reduces aqueous synthesis and can increase uveoscleral outflow, unlike alpha-1-mediated dilation."}, {"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "This lowers aqueous secretion; it does not primarily improve trabecular outflow or dilate the pupil."}, {"text": "Muscarinic receptor blockade", "why": "Antimuscarinic action inhibits iris sphincter and ciliary accommodation. The pupil dilates and near focusing is impaired."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "PGF2-alpha-related drugs increase an alternative aqueous drainage pathway rather than mainly suppressing secretion."}], "answer": 3, "image": null}, {"id": "Q159", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "A pupil dilates after phenylephrine but near accommodation remains largely intact. Which mechanism explains this?", "options": [{"text": "Muscarinic receptor blockade", "why": "This relaxes iris sphincter and ciliary muscle, causing mydriasis and cycloplegia rather than miosis."}, {"text": "Carbonic anhydrase inhibition", "why": "Reduced bicarbonate-dependent fluid secretion lowers aqueous formation; systemic agents also affect renal acid-base balance."}, {"text": "Increased plasma osmolality", "why": "An osmotic gradient shifts water out of ocular tissues and rapidly reduces IOP in selected emergencies."}, {"text": "Alpha-1 receptor activation", "why": "The radial dilator contracts while ciliary muscarinic receptors are not directly blocked."}, {"text": "Alpha-2 receptor activation", "why": "This reduces aqueous synthesis and can increase uveoscleral outflow, unlike alpha-1-mediated dilation."}], "answer": 3, "image": null}, {"id": "Q160", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "How does timolol primarily lower IOP?", "options": [{"text": "Acetylcholinesterase inhibition", "why": "Higher endogenous acetylcholine indirectly produces ocular muscarinic effects; this differs from direct receptor agonism."}, {"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "Blocking beta-mediated signaling reduces aqueous production. It does not produce the muscarinic ciliary contraction of pilocarpine."}, {"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Increased plasma osmolality", "why": "An osmotic gradient shifts water out of ocular tissues and rapidly reduces IOP in selected emergencies."}, {"text": "Muscarinic receptor blockade", "why": "This relaxes iris sphincter and ciliary muscle, causing mydriasis and cycloplegia rather than miosis."}], "answer": 1, "image": null}, {"id": "Q161", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [5, 10], "page": 5, "ref": "slide-oph-5", "stem": "What receptor mechanism explains apraclonidine’s main pressure-lowering effect?", "options": [{"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Direct M3 receptor stimulation", "why": "Ciliary muscle and iris sphincter contraction produce increased trabecular outflow and miosis."}, {"text": "Increased plasma osmolality", "why": "An osmotic gradient shifts water out of ocular tissues and rapidly reduces IOP in selected emergencies."}, {"text": "Alpha-2 receptor activation", "why": "Alpha-2 activation reduces aqueous secretion. Brimonidine shares this class and can also improve uveoscleral outflow."}, {"text": "Muscarinic receptor blockade", "why": "This relaxes iris sphincter and ciliary muscle, causing mydriasis and cycloplegia rather than miosis."}], "answer": 3, "image": null}, {"id": "Q162", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "How does acetazolamide lower aqueous production?", "options": [{"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Direct M3 receptor stimulation", "why": "Ciliary muscle and iris sphincter contraction produce increased trabecular outflow and miosis."}, {"text": "Carbonic anhydrase inhibition", "why": "Ciliary bicarbonate-dependent secretion falls when carbonic anhydrase is inhibited, reducing aqueous formation."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "PGF2-alpha-related drugs increase an alternative aqueous drainage pathway rather than mainly suppressing secretion."}, {"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "This lowers aqueous secretion; it does not primarily improve trabecular outflow or dilate the pupil."}], "answer": 2, "image": null}, {"id": "Q163", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [6], "page": 6, "ref": "slide-oph-6", "stem": "Why can IV mannitol rapidly lower pressure in selected severe glaucoma cases?", "options": [{"text": "Alpha-2 receptor activation", "why": "This reduces aqueous synthesis and can increase uveoscleral outflow, unlike alpha-1-mediated dilation."}, {"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Increased plasma osmolality", "why": "Osmotic water movement reduces ocular volume, including vitreous water. The slide’s focus solely on anterior chamber fluid is too narrow."}, {"text": "Acetylcholinesterase inhibition", "why": "Higher endogenous acetylcholine indirectly produces ocular muscarinic effects; this differs from direct receptor agonism."}, {"text": "Alpha-1 receptor activation", "why": "This contracts the radial iris dilator and causes mydriasis without direct paralysis of accommodation."}], "answer": 2, "image": null}, {"id": "Q164", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [7, 10], "page": 7, "ref": "slide-oph-7", "stem": "What is the principal outflow mechanism of latanoprost?", "options": [{"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "This lowers aqueous secretion; it does not primarily improve trabecular outflow or dilate the pupil."}, {"text": "Muscarinic receptor blockade", "why": "This relaxes iris sphincter and ciliary muscle, causing mydriasis and cycloplegia rather than miosis."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "Latanoprost increases uveoscleral drainage rather than primarily decreasing secretion at the ciliary epithelium."}, {"text": "Increased plasma osmolality", "why": "An osmotic gradient shifts water out of ocular tissues and rapidly reduces IOP in selected emergencies."}, {"text": "Alpha-1 receptor activation", "why": "This contracts the radial iris dilator and causes mydriasis without direct paralysis of accommodation."}], "answer": 2, "image": null}, {"id": "Q165", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [8, 11], "page": 8, "ref": "slide-oph-8", "stem": "Which mechanism underlies pilocarpine’s therapeutic effect in glaucoma?", "options": [{"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "This lowers aqueous secretion; it does not primarily improve trabecular outflow or dilate the pupil."}, {"text": "Acetylcholinesterase inhibition", "why": "Higher endogenous acetylcholine indirectly produces ocular muscarinic effects; this differs from direct receptor agonism."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "PGF2-alpha-related drugs increase an alternative aqueous drainage pathway rather than mainly suppressing secretion."}, {"text": "Direct M3 receptor stimulation", "why": "Ciliary muscle contraction opens the conventional drainage apparatus and the iris sphincter produces miosis. This original question expands the lecture’s review item to five options."}, {"text": "Carbonic anhydrase inhibition", "why": "Reduced bicarbonate-dependent fluid secretion lowers aqueous formation; systemic agents also affect renal acid-base balance."}], "answer": 3, "image": null}, {"id": "Q166", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [8], "page": 8, "ref": "slide-oph-8", "stem": "Echothiophate increases trabecular drainage by which initiating mechanism?", "options": [{"text": "Alpha-1 receptor activation", "why": "This contracts the radial iris dilator and causes mydriasis without direct paralysis of accommodation."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "PGF2-alpha-related drugs increase an alternative aqueous drainage pathway rather than mainly suppressing secretion."}, {"text": "Acetylcholinesterase inhibition", "why": "Blocking acetylcholine breakdown indirectly activates ocular muscarinic receptors. Pilocarpine reaches similar downstream effects through direct agonism."}, {"text": "Rho kinase inhibition", "why": "Reduced trabecular contractility/stiffness lowers resistance in the conventional aqueous drainage pathway."}, {"text": "Carbonic anhydrase inhibition", "why": "Reduced bicarbonate-dependent fluid secretion lowers aqueous formation; systemic agents also affect renal acid-base balance."}], "answer": 2, "image": null}, {"id": "Q167", "deck": "oph", "topic": "Ophthalmic mechanisms", "pages": [9], "page": 9, "ref": "slide-oph-9", "stem": "Netarsudil improves aqueous drainage by which mechanism?", "options": [{"text": "Direct M3 receptor stimulation", "why": "Ciliary muscle and iris sphincter contraction produce increased trabecular outflow and miosis."}, {"text": "Beta-adrenergic blockade at ciliary epithelium", "why": "This lowers aqueous secretion; it does not primarily improve trabecular outflow or dilate the pupil."}, {"text": "Prostaglandin-mediated uveoscleral outflow", "why": "PGF2-alpha-related drugs increase an alternative aqueous drainage pathway rather than mainly suppressing secretion."}, {"text": "Acetylcholinesterase inhibition", "why": "Higher endogenous acetylcholine indirectly produces ocular muscarinic effects; this differs from direct receptor agonism."}, {"text": "Rho kinase inhibition", "why": "Relaxation and reduced stiffness in the trabecular outflow system lower resistance; antifibrotic effects are also discussed in the lecture."}], "answer": 4, "image": null}, {"id": "Q168", "deck": "oph", "topic": "Pupil and accommodation", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "What does cycloplegia mean?", "options": [{"text": "Permanent destruction of the retina", "why": "Cycloplegia is a focusing effect, not retinal ablation."}, {"text": "Loss of accommodation from ciliary muscle paralysis", "why": "Cycloplegia impairs near focusing. Mydriasis means pupil dilation and can occur with or without cycloplegia."}, {"text": "Constriction of the pupil", "why": "This is miosis, not cycloplegia."}, {"text": "Increased tear secretion", "why": "Tears do not define cycloplegia."}, {"text": "An enlarged optic cup", "why": "Cupping reflects optic nerve head tissue loss rather than ciliary paralysis."}], "answer": 1, "image": null}, {"id": "Q169", "deck": "oph", "topic": "Pupil and accommodation", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "A clinician wants dilation without directly blocking accommodation. Which choice best fits?", "options": [{"text": "Phenylephrine", "why": "Alpha-1 stimulation contracts the iris dilator without muscarinic ciliary blockade."}, {"text": "Atropine", "why": "This causes both dilation and cycloplegia for a prolonged period."}, {"text": "Tropicamide", "why": "It is shorter acting but still has antimuscarinic cycloplegic effects."}, {"text": "Pilocarpine", "why": "It causes miosis and ciliary contraction rather than diagnostic dilation."}, {"text": "Cyclopentolate", "why": "This antimuscarinic produces cycloplegia as well as dilation."}], "answer": 0, "image": null}, {"id": "Q170", "deck": "oph", "topic": "Pupil and accommodation", "pages": [2], "page": 2, "ref": "slide-oph-2", "stem": "Which ordering matches the lecture’s approximate duration of antimuscarinic dilation from longest to shortest?", "options": [{"text": "All have identical duration", "why": "Duration is a major practical distinction among the agents."}, {"text": "Cyclopentolate, atropine, tropicamide", "why": "Atropine generally lasts much longer than cyclopentolate."}, {"text": "Atropine, cyclopentolate, tropicamide", "why": "The lecture estimates 7–14 days, 24 hours, and six hours respectively; these are teaching approximations, not precise predictions for every patient."}, {"text": "Atropine, tropicamide, cyclopentolate", "why": "Tropicamide is usually shorter acting than cyclopentolate."}, {"text": "Tropicamide, cyclopentolate, atropine", "why": "This reverses the main duration relationship."}], "answer": 2, "image": null}, {"id": "Q171", "deck": "oph", "topic": "Beta-blocker safety", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "A patient develops wheezing soon after starting timolol eye drops. What is the best explanation?", "options": [{"text": "The effect is caused by selective alpha-1 stimulation", "why": "Timolol is a beta blocker, not phenylephrine."}, {"text": "The effect proves a direct muscarinic agonist was prescribed", "why": "Beta-blocker bronchospasm can occur without a muscarinic drug."}, {"text": "Systemic absorption causes beta-2 receptor blockade", "why": "Topical ocular administration can cause significant cardiopulmonary effects. Asthma or severe reactive airway disease is a major concern."}, {"text": "Timolol stimulates beta-2 receptors", "why": "Stimulation would tend toward bronchodilation rather than this blockade-related effect."}, {"text": "Eye drops cannot reach the systemic circulation", "why": "Nasolacrimal and other absorption routes permit systemic exposure."}], "answer": 2, "image": null}, {"id": "Q172", "deck": "oph", "topic": "Beta-blocker safety", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "Which cardiac history is especially concerning before starting topical timolol?", "options": [{"text": "A remote uncomplicated fracture", "why": "This does not identify the major cardiac risk."}, {"text": "Normal resting pulse and no cardiac disease", "why": "This does not establish the high-risk condition asked about."}, {"text": "Symptomatic sinus bradycardia or significant AV block", "why": "Systemic beta blockade can slow heart rate and conduction. Overt heart failure or cardiogenic shock also warrants avoidance according to labeling."}, {"text": "An isolated normal ECG", "why": "This is not itself a contraindication."}, {"text": "Only a need for reading glasses", "why": "Refractive correction does not identify a beta-blocker contraindication."}], "answer": 2, "image": null}, {"id": "Q173", "deck": "oph", "topic": "Beta-blocker safety", "pages": [4], "page": 4, "ref": "slide-oph-4", "stem": "Which adverse-effect cluster can occur with systemic exposure to ocular beta blockers?", "options": [{"text": "Fatigue, dizziness, bradycardia, and bronchospasm", "why": "The slide’s illustrations emphasize systemic effects despite ocular dosing. Risk depends on selectivity, exposure, and comorbidity."}, {"text": "Mydriasis with cycloplegia as the main therapeutic action", "why": "This is antimuscarinic pharmacology."}, {"text": "Metabolic acidosis, hypokalemia, and renal stones", "why": "These are characteristic systemic CA-inhibitor effects."}, {"text": "Iris darkening and eyelash growth as the defining cluster", "why": "These are more characteristic of prostaglandin-related drugs."}, {"text": "Acetylcholinesterase inhibition with prolonged miosis", "why": "This describes echothiophate rather than beta blockade."}], "answer": 0, "image": null}, {"id": "Q174", "deck": "oph", "topic": "Ocular drug safety", "pages": [5, 10], "page": 5, "ref": "slide-oph-5", "stem": "Which local adverse effects can occur with alpha-2 glaucoma agonists?", "options": [{"text": "Hyperemia, itchy eyes, foreign-body sensation, and allergic irritation", "why": "Brimonidine/apraclonidine can cause local ocular reactions; systemic fatigue, dry mouth, or CNS effects also require attention."}, {"text": "Only renal bicarbonate wasting", "why": "That is systemic CA-inhibitor pharmacology."}, {"text": "Only increased eyelash growth without irritation", "why": "This more strongly suggests a prostaglandin effect and omits alpha-agonist allergy."}, {"text": "Universal permanent retinal detachment", "why": "This is not the typical adverse-effect pattern."}, {"text": "No possible local effects because receptors are systemic only", "why": "Ocular receptors and local drug exposure can produce ocular effects."}], "answer": 0, "image": null}, {"id": "Q175", "deck": "oph", "topic": "Carbonic anhydrase inhibitor safety", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "A patient on oral acetazolamide has low serum bicarbonate and tingling. What acid-base disturbance is expected?", "options": [{"text": "Metabolic alkalosis from increased bicarbonate retention", "why": "This reverses the usual CA-inhibitor effect."}, {"text": "Isolated respiratory acidosis from beta blockade", "why": "That is not the primary CA-inhibition mechanism."}, {"text": "Primary respiratory alkalosis as the direct renal effect", "why": "Acetazolamide primarily alters renal bicarbonate handling."}, {"text": "Hyperchloremic metabolic acidosis", "why": "Renal bicarbonate loss produces a non-anion-gap acidosis. Hypokalemia, paresthesias, and kidney stones are additional relevant effects."}, {"text": "No acid-base effect because only the eye is exposed", "why": "Oral or IV treatment has systemic effects."}], "answer": 3, "image": null}, {"id": "Q176", "deck": "oph", "topic": "Carbonic anhydrase inhibitor safety", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "Which adverse effect is especially associated with systemic carbonic anhydrase inhibition?", "options": [{"text": "Selective hearing recovery after ototoxic injury", "why": "CA inhibition does not regenerate cochlear cells."}, {"text": "Renal stones with paresthesias and potassium depletion", "why": "Urinary changes from CA inhibition favor stones, while systemic electrolyte and acid-base effects can produce symptoms."}, {"text": "Increased eyelash length as the main systemic effect", "why": "This is associated with bimatoprost/related drugs."}, {"text": "Direct irreversible acetylcholinesterase inhibition", "why": "This is not a CA-inhibitor mechanism."}, {"text": "Mydriasis without cycloplegia", "why": "This is alpha-1 agonist pharmacology."}], "answer": 1, "image": null}, {"id": "Q177", "deck": "oph", "topic": "Carbonic anhydrase inhibitor safety", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "Why may topical dorzolamide cause fewer systemic effects than oral acetazolamide?", "options": [{"text": "Dorzolamide activates rather than inhibits carbonic anhydrase", "why": "Both are inhibitors."}, {"text": "Topical administration generally produces lower systemic exposure", "why": "Both inhibit carbonic anhydrase. Route changes the exposure and adverse-effect burden, though topical drugs are not completely free of systemic effects."}, {"text": "Acetazolamide has no effect outside the eye", "why": "Its renal actions are central to its systemic adverse effects."}, {"text": "Topical administration prevents every possible adverse event", "why": "Local irritation and some systemic exposure remain possible."}, {"text": "Dorzolamide works only by pupil dilation", "why": "Its primary mechanism is reduced aqueous synthesis."}], "answer": 1, "image": null}, {"id": "Q178", "deck": "oph", "topic": "Osmotic therapy", "pages": [6], "page": 6, "ref": "slide-oph-6", "stem": "After osmotic IOP-lowering therapy, a patient becomes volume depleted and creatinine rises. Which mechanism explains this risk?", "options": [{"text": "Mannitol selectively inhibits beta-2 receptors", "why": "It is not a beta blocker."}, {"text": "Only an iris pigmentation change explains the creatinine rise", "why": "Pigmentation does not explain systemic volume depletion."}, {"text": "Mannitol directly blocks M3 receptors", "why": "That is not its osmotic mechanism."}, {"text": "Mannitol always prevents renal injury regardless of volume status", "why": "Renal risk depends on dose, clearance, and fluid status."}, {"text": "Mannitol-induced osmotic diuresis can cause dehydration and prerenal injury", "why": "Volume status and renal/cardiac function require monitoring. Mannitol can also initially expand intravascular volume, so risk is not limited to dehydration."}], "answer": 4, "image": null}, {"id": "Q179", "deck": "oph", "topic": "Prostaglandin adverse effects", "pages": [7, 10], "page": 7, "ref": "slide-oph-7", "stem": "A glaucoma patient develops darker iris color and longer eyelashes. Which drug class best explains the change?", "options": [{"text": "Prostaglandin-related ocular agents", "why": "Latanoprost and bimatoprost can increase iris pigmentation and eyelash growth. Local redness/irritation may also occur."}, {"text": "Nonselective beta blockers", "why": "Their major systemic concerns are cardiac and pulmonary blockade."}, {"text": "Carbonic anhydrase inhibitors", "why": "These more characteristically cause taste disturbance/local irritation or systemic acidosis and stones."}, {"text": "Antimuscarinic cycloplegics", "why": "These dilate pupils and impair near focusing rather than produce the characteristic lash/pigment cluster."}, {"text": "Osmotic diuretics", "why": "These affect fluid distribution and do not characteristically lengthen eyelashes."}], "answer": 0, "image": null}, {"id": "Q180", "deck": "oph", "topic": "Cholinergic adverse effects", "pages": [8, 10], "page": 8, "ref": "slide-oph-8", "stem": "Why can pilocarpine make vision worse in dim light?", "options": [{"text": "It eliminates all aqueous secretion", "why": "Its primary pressure effect is increased outflow."}, {"text": "It directly removes retinal rods", "why": "Dim-light blur here is a pharmacologic pupil effect, not rod destruction."}, {"text": "It blocks every photopigment molecule", "why": "It does not directly inhibit photopigment synthesis."}, {"text": "Miosis reduces the amount of light entering the eye", "why": "Sphincter contraction constricts the pupil. Ciliary spasm can also cause brow pain, induced myopia, and near-focusing effects."}, {"text": "It causes maximal pupil dilation", "why": "Pilocarpine is miotic rather than mydriatic."}], "answer": 3, "image": null}, {"id": "Q181", "deck": "oph", "topic": "Cholinergic adverse effects", "pages": [8], "page": 8, "ref": "slide-oph-8", "stem": "Sweating, salivation, diarrhea, and wheezing after excessive ocular cholinergic exposure suggest what?", "options": [{"text": "A normal effect of routine accommodation without drug exposure", "why": "The systemic autonomic cluster requires evaluation."}, {"text": "Systemic cholinergic toxicity", "why": "Direct or indirect cholinomimetics can produce systemic muscarinic effects if exposure is sufficient. Eye-drop delivery does not guarantee purely local action."}, {"text": "Isolated alpha-1 agonism", "why": "That does not explain the secretory/cholinergic cluster."}, {"text": "Only a prostaglandin pigmentation effect", "why": "Pigmentation does not explain diarrhea and excess secretions."}, {"text": "Antimuscarinic toxicity", "why": "That more often causes dry mouth, reduced sweating, tachycardia, and dilation."}], "answer": 1, "image": null}, {"id": "Q182", "deck": "oph", "topic": "Outflow pathway comparison", "pages": [7, 8, 9], "page": 7, "ref": "slide-oph-7", "stem": "Which pairing correctly matches a drug with its main outflow pathway?", "options": [{"text": "Latanoprost: uveoscleral; pilocarpine: trabecular", "why": "Prostaglandin analogs increase alternative uveoscleral drainage. Ciliary contraction from pilocarpine improves conventional trabecular drainage; Rho kinase inhibitors also act on conventional resistance."}, {"text": "Latanoprost: aqueous synthesis blockade only; pilocarpine: no outflow effect", "why": "This misstates both principal mechanisms."}, {"text": "Timolol: direct M3 activation; phenylephrine: CA inhibition", "why": "Timolol is a beta blocker and phenylephrine is alpha-1 agonist."}, {"text": "Mannitol: acetylcholinesterase inhibition; echothiophate: osmotic shift", "why": "This reverses their pharmacologic identities."}, {"text": "Netarsudil: lens removal; dorzolamide: iris dilation", "why": "Neither is the drug’s pressure-lowering mechanism."}], "answer": 0, "image": null}, {"id": "Q183", "deck": "oph", "topic": "Angle-closure treatment context", "pages": [4, 5, 6, 8], "page": 4, "ref": "slide-oph-4", "stem": "A patient has acute angle closure with very high IOP. Which statement best places the lecture drug list in clinical context?", "options": [{"text": "Wait several weeks to assess whether pain resolves", "why": "Acute angle closure threatens vision rapidly."}, {"text": "Pilocarpine must work immediately at any pressure", "why": "An ischemic iris sphincter may not respond until IOP is lowered."}, {"text": "Urgent multidrug pressure reduction and definitive relief of the closure mechanism are needed", "why": "Beta blockers, alpha-2 agents, systemic CA inhibition, or osmotic therapy may be used as appropriate; laser iridotomy treats pupillary block. Miotics may be ineffective until very high IOP falls."}, {"text": "A single chronic eye drop always replaces definitive treatment", "why": "Persistent pupillary block requires relief of the mechanism."}, {"text": "Epinephrine dilation is the preferred way to open a crowded angle", "why": "Mydriasis can worsen susceptible angle closure."}], "answer": 2, "image": null}, {"id": "Q184", "deck": "oph", "topic": "Rho kinase inhibitors", "pages": [9], "page": 9, "ref": "slide-oph-9", "stem": "A slide calls Rho kinase inhibitors well tolerated. Which counseling statement remains appropriate?", "options": [{"text": "No patient can experience ocular redness", "why": "This is contradicted by known class effects."}, {"text": "They regenerate a destroyed optic nerve", "why": "Lowering IOP limits further damage but does not restore lost axons."}, {"text": "Conjunctival hyperemia and other local effects can still occur", "why": "Netarsudil commonly causes redness; tolerability is relative, not an absence of adverse effects. Ripasudil availability differs by country."}, {"text": "They primarily raise IOP through aqueous overproduction", "why": "They lower outflow resistance."}, {"text": "They are muscarinic antagonists that produce cycloplegia", "why": "Their mechanism is trabecular Rho kinase inhibition."}], "answer": 2, "image": null}, {"id": "Q185", "deck": "va", "topic": "Retinal cell functions", "pages": [5, 6], "page": 5, "ref": "slide-va-5", "stem": "Which photoreceptor is most important for detecting a faint object on a moonless night?", "options": [{"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}, {"text": "Cone photoreceptor", "why": "Cones support daylight color vision and high acuity, are concentrated in the fovea, and require greater light intensity than rods."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}, {"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "Rod photoreceptor", "why": "Rods have low light thresholds and large amounts of rhodopsin, making them sensitive in dim illumination. They do not encode color and have lower spatial acuity."}], "answer": 4, "image": null}, {"id": "Q186", "deck": "va", "topic": "Retinal cell functions", "pages": [5, 6, 15], "page": 5, "ref": "slide-va-5", "stem": "Which photoreceptor supports high-acuity color vision in bright daylight?", "options": [{"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}, {"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "Cone photoreceptor", "why": "Cones have wavelength-selective photopsins and are concentrated at the fovea. They require higher light levels than rods."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}], "answer": 2, "image": null}, {"id": "Q187", "deck": "va", "topic": "Retinal cell functions", "pages": [5, 6], "page": 5, "ref": "slide-va-5", "stem": "Which photoreceptor is absent from the central foveola and contributes little to fine central color discrimination?", "options": [{"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}, {"text": "Rod photoreceptor", "why": "The central foveola is cone dominated and lacks rods. Rods are optimized for sensitivity rather than fine color detail."}, {"text": "Retinal ganglion cell", "why": "Ganglion cells generate action potentials whose axons form the optic nerve; photoreceptors and bipolar cells mainly signal with graded potentials."}, {"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}], "answer": 2, "image": null}, {"id": "Q188", "deck": "va", "topic": "Retinal cell functions", "pages": [5, 6], "page": 5, "ref": "slide-va-5", "stem": "Which cells are densely packed in the fovea and support reading small print under adequate illumination?", "options": [{"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}, {"text": "Cone photoreceptor", "why": "Foveal cone density and limited convergence support high acuity. Rod convergence improves sensitivity while reducing spatial precision."}, {"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}, {"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}], "answer": 2, "image": null}, {"id": "Q189", "deck": "va", "topic": "Retinal cell functions", "pages": [9, 10, 12], "page": 9, "ref": "slide-va-9", "stem": "Reduced glutamate release from a light-stimulated rod depolarizes the bipolar pathway highlighted in the lecture. Which bipolar class is meant?", "options": [{"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}, {"text": "Cone photoreceptor", "why": "Cones support daylight color vision and high acuity, are concentrated in the fovea, and require greater light intensity than rods."}, {"text": "Retinal ganglion cell", "why": "Ganglion cells generate action potentials whose axons form the optic nerve; photoreceptors and bipolar cells mainly signal with graded potentials."}, {"text": "ON bipolar cell", "why": "The rod-to-ON bipolar synapse is sign inverting. Reduced glutamate relieves mGluR6-mediated suppression and depolarizes the ON bipolar cell; not all bipolar cells behave this way."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}], "answer": 3, "image": null}, {"id": "Q190", "deck": "va", "topic": "Retinal cell functions", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "A bipolar cell has ionotropic glutamate receptors and becomes less depolarized when a photoreceptor releases less glutamate. Which class is described?", "options": [{"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}, {"text": "OFF bipolar cell", "why": "OFF bipolar cells are sign preserving and typically hyperpolarize when light reduces glutamate. This qualifies the slide shorthand that glutamate inhibits all bipolar cells."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}, {"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}], "answer": 2, "image": null}, {"id": "Q191", "deck": "va", "topic": "Retinal cell functions", "pages": [10, 12], "page": 10, "ref": "slide-va-10", "stem": "Which retinal neurons send action potentials along axons that form the optic nerve?", "options": [{"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}, {"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}, {"text": "Retinal ganglion cell", "why": "Ganglion cell output is spiking. Rods, cones, and bipolar cells mainly communicate through graded changes in voltage and transmitter release."}, {"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}], "answer": 3, "image": null}, {"id": "Q192", "deck": "va", "topic": "Retinal cell functions", "pages": [8, 13, 14], "page": 8, "ref": "slide-va-8", "stem": "Which retinal support tissue is crucial to recycling the retinal chromophore for photopigment regeneration?", "options": [{"text": "Retinal ganglion cell", "why": "Ganglion cells generate action potentials whose axons form the optic nerve; photoreceptors and bipolar cells mainly signal with graded potentials."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}, {"text": "Cone photoreceptor", "why": "Cones support daylight color vision and high acuity, are concentrated in the fovea, and require greater light intensity than rods."}, {"text": "Retinal pigment epithelium", "why": "The RPE participates in the visual cycle that restores usable 11-cis-retinal. Vitamin A supply and intact recycling support photoreceptor function."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}], "answer": 3, "image": null}, {"id": "Q193", "deck": "va", "topic": "Retinal cell functions", "pages": [6], "page": 6, "ref": "slide-va-6", "stem": "Which photoreceptor contributes to the slower, more sensitive phase of dark adaptation?", "options": [{"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "Rod photoreceptor", "why": "Cones adapt earlier, while rods dominate the later phase as sensitivity increases. This accounts for the classic biphasic dark-adaptation curve."}, {"text": "Horizontal cell", "why": "Horizontal cells participate in lateral retinal processing, helping shape contrast and receptive fields rather than carrying optic nerve axons."}, {"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}, {"text": "ON bipolar cell", "why": "ON bipolar cells are depolarized by light-induced reduction of photoreceptor glutamate through a sign-inverting mGluR6 pathway."}], "answer": 1, "image": null}, {"id": "Q194", "deck": "va", "topic": "Retinal cell functions", "pages": [6], "page": 6, "ref": "slide-va-6", "stem": "Which photoreceptor contributes to the earlier phase of dark adaptation?", "options": [{"text": "Cone photoreceptor", "why": "Cone sensitivity improves relatively early, but rods later achieve much lower light thresholds."}, {"text": "Rod photoreceptor", "why": "Rods have high light sensitivity, support scotopic vision, lack color discrimination, and are absent from the central foveola; they converge for sensitivity at the cost of acuity."}, {"text": "Retinal pigment epithelium", "why": "RPE supports photoreceptors, participates in the visual cycle, and maintains outer retinal homeostasis; it is not the principal action-potential output neuron."}, {"text": "OFF bipolar cell", "why": "OFF bipolar cells have sign-preserving ionotropic glutamate responses and are relatively hyperpolarized by reduced photoreceptor glutamate in light."}, {"text": "Retinal ganglion cell", "why": "Ganglion cells generate action potentials whose axons form the optic nerve; photoreceptors and bipolar cells mainly signal with graded potentials."}], "answer": 0, "image": null}, {"id": "Q195", "deck": "va", "topic": "Photoreceptor structure", "pages": [5], "page": 5, "ref": "slide-va-5", "stem": "Which photoreceptor compartment contains the light-sensitive pigment-rich membranes?", "options": [{"text": "Outer segment", "why": "Pigment-bearing discs or membrane infoldings capture photons. Inner segments contain metabolic organelles, and terminals communicate with retinal interneurons."}, {"text": "Synaptic terminal only", "why": "The terminal releases transmitter but is not the principal pigment-bearing light-capture compartment."}, {"text": "Corneal epithelium", "why": "This protects the eye surface and is not a photoreceptor segment."}, {"text": "Ciliary muscle", "why": "This changes lens shape for accommodation rather than housing retinal pigment discs."}, {"text": "Optic nerve axon", "why": "Photoreceptors do not send their own axons into the optic nerve."}], "answer": 0, "image": null}, {"id": "Q196", "deck": "va", "topic": "Photoreceptor structure", "pages": [5], "page": 5, "ref": "slide-va-5", "stem": "Which compartment provides much of the photoreceptor’s metabolic machinery?", "options": [{"text": "Only the outer segment lumen", "why": "The outer segment specializes in phototransduction membranes rather than housing all metabolic organelles."}, {"text": "Only the aqueous humor", "why": "Aqueous is not the photoreceptor’s organelle-containing compartment."}, {"text": "Only the lens nucleus", "why": "The lens refracts light and does not supply photoreceptor organelles."}, {"text": "Only the optic chiasm", "why": "The chiasm carries retinal ganglion axons and is not part of a photoreceptor cell."}, {"text": "Inner segment", "why": "The inner segment contains mitochondria and other organelles that support the metabolically demanding outer segment and synapse."}], "answer": 4, "image": null}, {"id": "Q197", "deck": "va", "topic": "Photoreceptor pigment", "pages": [8], "page": 8, "ref": "slide-va-8", "stem": "What are the two molecular components of rhodopsin?", "options": [{"text": "Transducin and glutamate", "why": "Transducin is a signaling G protein and glutamate is transmitter, not the pigment pair."}, {"text": "Opsin protein and 11-cis-retinal", "why": "Retinal is a vitamin-A-derived chromophore; bound to rod opsin it forms rhodopsin, the light-sensitive pigment."}, {"text": "Retinoic acid and collagen", "why": "These do not form the rod visual pigment."}, {"text": "Opsin protein and acetylcholine", "why": "Acetylcholine is not the rhodopsin chromophore."}, {"text": "Arrestin and cGMP", "why": "These participate in shutoff and channel signaling rather than constituting rhodopsin."}], "answer": 1, "image": null}, {"id": "Q198", "deck": "va", "topic": "Photoreceptor pigment", "pages": [8, 10, 11], "page": 8, "ref": "slide-va-8", "stem": "What is the initial chromophore change after rhodopsin absorbs light?", "options": [{"text": "Calcium becomes potassium", "why": "Ions are not converted into one another during phototransduction."}, {"text": "All-trans-retinal directly becomes glutamate", "why": "Retinal is a chromophore and does not turn into the synaptic transmitter."}, {"text": "Opsin is immediately phosphorylated to create the first active state", "why": "Photoisomerization activates the pigment; kinase phosphorylation helps terminate signaling."}, {"text": "11-cis-retinal isomerizes to all-trans-retinal", "why": "This drives a conformational change in opsin and the activated metarhodopsin II state, initiating transducin signaling."}, {"text": "cGMP directly converts to vitamin A", "why": "cGMP is hydrolyzed to GMP downstream, not converted into vitamin A."}], "answer": 3, "image": null}, {"id": "Q199", "deck": "va", "topic": "Phototransduction sequence", "pages": [9], "page": 9, "ref": "slide-va-9", "stem": "What intracellular condition maintains the rod dark current?", "options": [{"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}, {"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "In darkness, relatively high cGMP keeps outer-segment cation channels open. Inward Na+/Ca2+ current maintains a relatively depolarized state and tonic transmitter release."}, {"text": "Rhodopsin phosphorylation and arrestin binding", "why": "These shut down activated pigment and reduce further transducin activation, helping terminate the light response."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}], "answer": 1, "image": null}, {"id": "Q200", "deck": "va", "topic": "Phototransduction sequence", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "Immediately downstream of metarhodopsin II, which signaling event initiates the G-protein cascade?", "options": [{"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "This is the dark-state condition, allowing inward cation current and relative photoreceptor depolarization."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Transducin is the G protein, not an enzyme called 'transduction.' Activated transducin stimulates the cGMP phosphodiesterase pathway."}, {"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}], "answer": 3, "image": null}, {"id": "Q201", "deck": "va", "topic": "Phototransduction sequence", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "What enzymatic step lowers cGMP during phototransduction?", "options": [{"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}, {"text": "Rhodopsin phosphorylation and arrestin binding", "why": "These shut down activated pigment and reduce further transducin activation, helping terminate the light response."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Phosphodiesterase hydrolyzes cGMP", "why": "Activated PDE converts cGMP to GMP, decreasing channel-opening ligand. Lower cGMP closes outer-segment cation channels."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}], "answer": 3, "image": null}, {"id": "Q202", "deck": "va", "topic": "Phototransduction sequence", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "Which membrane event directly reduces the photoreceptor dark current after cGMP falls?", "options": [{"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}, {"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Closure of outer-segment cation channels", "why": "The cyclic-nucleotide-gated channels carry Na+ and Ca2+ inward. Closing them reduces inward positive current and hyperpolarizes the cell."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}], "answer": 2, "image": null}, {"id": "Q203", "deck": "va", "topic": "Phototransduction sequence", "pages": [10, 12], "page": 10, "ref": "slide-va-10", "stem": "What synaptic change follows rod hyperpolarization in light?", "options": [{"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "This is the dark-state condition, allowing inward cation current and relative photoreceptor depolarization."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization reduces synaptic calcium entry and glutamate release. This depolarizes the ON pathway while affecting OFF cells differently."}, {"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}, {"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}], "answer": 1, "image": null}, {"id": "Q204", "deck": "va", "topic": "Phototransduction sequence", "pages": [11, 12], "page": 11, "ref": "slide-va-11", "stem": "What function do rhodopsin kinase and arrestin serve?", "options": [{"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Rhodopsin phosphorylation and arrestin binding", "why": "GRK1 phosphorylation followed by arrestin binding quenches light-activated rhodopsin. The source slide incorrectly describes phosphorylation as the activation event."}, {"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "This is the dark-state condition, allowing inward cation current and relative photoreceptor depolarization."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}], "answer": 2, "image": null}, {"id": "Q205", "deck": "va", "topic": "Phototransduction sequence", "pages": [11, 12], "page": 11, "ref": "slide-va-11", "stem": "After the light response ends, what helps restore open cyclic-nucleotide-gated channels?", "options": [{"text": "Rhodopsin phosphorylation and arrestin binding", "why": "These shut down activated pigment and reduce further transducin activation, helping terminate the light response."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}, {"text": "Restoration of cGMP and pigment readiness", "why": "Signal termination and cGMP replenishment permit cation channels to reopen. Continued PDE activity would instead keep cGMP low."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}], "answer": 2, "image": null}, {"id": "Q206", "deck": "va", "topic": "Phototransduction sequence", "pages": [9, 10, 11], "page": 9, "ref": "slide-va-9", "stem": "Which state is expected if cGMP phosphodiesterase is experimentally inhibited during a flash?", "options": [{"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "Preventing cGMP hydrolysis blunts normal channel closure and hyperpolarization. The response will differ from an intact light cascade."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}, {"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}, {"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}], "answer": 0, "image": null}, {"id": "Q207", "deck": "va", "topic": "Phototransduction sequence", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "A loss-of-function mutation prevents transducin from activating PDE. Which normal step is directly lost?", "options": [{"text": "Phosphodiesterase hydrolyzes cGMP", "why": "Without downstream PDE activation, the normal light-induced cGMP fall is impaired. The initial pigment photoisomerization can still occur."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "Closure of outer-segment cation channels", "why": "Reduced inward Na+/Ca2+ current shifts the photoreceptor toward hyperpolarization while outward current continues."}, {"text": "Rhodopsin phosphorylation and arrestin binding", "why": "These shut down activated pigment and reduce further transducin activation, helping terminate the light response."}, {"text": "Restoration of cGMP and pigment readiness", "why": "Recovery requires signaling shutoff, cGMP restoration, and visual-cycle support; returning dark current is not due to sustained PDE activity."}], "answer": 0, "image": null}, {"id": "Q208", "deck": "va", "topic": "Phototransduction sequence", "pages": [11, 12], "page": 11, "ref": "slide-va-11", "stem": "A rod lacks functional arrestin. Which normal process is impaired, prolonging the light response?", "options": [{"text": "Phosphodiesterase hydrolyzes cGMP", "why": "PDE activation reduces cGMP and closes cyclic-nucleotide-gated channels during the light response."}, {"text": "Reduced photoreceptor glutamate release", "why": "Hyperpolarization decreases calcium-dependent synaptic release, changing bipolar signaling in a receptor-dependent manner."}, {"text": "High cGMP with open cyclic-nucleotide-gated channels", "why": "This is the dark-state condition, allowing inward cation current and relative photoreceptor depolarization."}, {"text": "Rhodopsin phosphorylation and arrestin binding", "why": "Arrestin normally caps phosphorylated activated pigment and blocks further transducin engagement. Loss slows response termination."}, {"text": "Activated rhodopsin stimulates transducin", "why": "Light-activated pigment engages the G protein upstream of phosphodiesterase; kinase phosphorylation is not the activating step."}], "answer": 3, "image": null}, {"id": "Q209", "deck": "va", "topic": "Dark and light predictions", "pages": [9, 12], "page": 9, "ref": "slide-va-9", "stem": "What best describes a rod when moving from bright light into darkness?", "options": [{"text": "Depolarization with increased glutamate release", "why": "cGMP rises and outer-segment cation channels reopen. The rod becomes less negative and releases more glutamate than during bright stimulation."}, {"text": "No voltage or transmitter change", "why": "A functional photoreceptor light response changes graded voltage and transmitter output; it is not electrically silent."}, {"text": "Depolarization with decreased glutamate release", "why": "This is not the ordinary direct voltage-release relationship at a photoreceptor synapse, though downstream ON cells depolarize when glutamate falls."}, {"text": "Hyperpolarization with decreased glutamate release", "why": "This is the usual rod/cone response to light: cGMP falls, cation channels close, and transmitter release decreases."}, {"text": "Hyperpolarization with increased glutamate release", "why": "The ordinary photoreceptor relationship is the opposite: hyperpolarization reduces calcium entry and release."}], "answer": 0, "image": null}, {"id": "Q210", "deck": "va", "topic": "Dark and light predictions", "pages": [10, 11, 12], "page": 10, "ref": "slide-va-10", "stem": "What best describes a rod’s response to increased illumination?", "options": [{"text": "Depolarization with increased glutamate release", "why": "This is the response to greater inward depolarizing current or the relative dark state, not the usual photoreceptor response to light."}, {"text": "Depolarization with decreased glutamate release", "why": "This is not the ordinary direct voltage-release relationship at a photoreceptor synapse, though downstream ON cells depolarize when glutamate falls."}, {"text": "Hyperpolarization with decreased glutamate release", "why": "Light reduces cGMP, closes cation channels, and decreases transmitter release. Photoreceptors respond with graded potentials rather than spikes."}, {"text": "Hyperpolarization with increased glutamate release", "why": "The ordinary photoreceptor relationship is the opposite: hyperpolarization reduces calcium entry and release."}, {"text": "No voltage or transmitter change", "why": "A functional photoreceptor light response changes graded voltage and transmitter output; it is not electrically silent."}], "answer": 2, "image": null}, {"id": "Q211", "deck": "va", "topic": "Dark and light predictions", "pages": [9, 10], "page": 9, "ref": "slide-va-9", "stem": "An experiment rapidly lowers intracellular cGMP in an isolated rod. If cyclic-nucleotide-gated channel activation falls, what response is expected?", "options": [{"text": "Depolarization with decreased glutamate release", "why": "This is not the ordinary direct voltage-release relationship at a photoreceptor synapse, though downstream ON cells depolarize when glutamate falls."}, {"text": "Hyperpolarization with increased glutamate release", "why": "The ordinary photoreceptor relationship is the opposite: hyperpolarization reduces calcium entry and release."}, {"text": "No voltage or transmitter change", "why": "A functional photoreceptor light response changes graded voltage and transmitter output; it is not electrically silent."}, {"text": "Hyperpolarization with decreased glutamate release", "why": "Closing the inward cation current makes the cell more negative and reduces transmitter output. Physiologically, light lowers intracellular cGMP through PDE."}, {"text": "Depolarization with increased glutamate release", "why": "This is the response to greater inward depolarizing current or the relative dark state, not the usual photoreceptor response to light."}], "answer": 3, "image": null}, {"id": "Q212", "deck": "va", "topic": "Dark and light predictions", "pages": [9, 10], "page": 9, "ref": "slide-va-9", "stem": "A cGMP analog persistently holds rod outer-segment channels open despite illumination. Which tendency is expected?", "options": [{"text": "Hyperpolarization with decreased glutamate release", "why": "This is the usual rod/cone response to light: cGMP falls, cation channels close, and transmitter release decreases."}, {"text": "Depolarization with decreased glutamate release", "why": "This is not the ordinary direct voltage-release relationship at a photoreceptor synapse, though downstream ON cells depolarize when glutamate falls."}, {"text": "No voltage or transmitter change", "why": "A functional photoreceptor light response changes graded voltage and transmitter output; it is not electrically silent."}, {"text": "Depolarization with increased glutamate release", "why": "Maintaining inward current opposes normal light-induced hyperpolarization and preserves relatively greater transmitter release."}, {"text": "Hyperpolarization with increased glutamate release", "why": "The ordinary photoreceptor relationship is the opposite: hyperpolarization reduces calcium entry and release."}], "answer": 3, "image": null}, {"id": "Q213", "deck": "va", "topic": "Dark and light predictions", "pages": [10, 11], "page": 10, "ref": "slide-va-10", "stem": "A bright flash closes many cGMP-gated channels while outward potassium conductance continues. What is expected?", "options": [{"text": "No voltage or transmitter change", "why": "A functional photoreceptor light response changes graded voltage and transmitter output; it is not electrically silent."}, {"text": "Depolarization with decreased glutamate release", "why": "This is not the ordinary direct voltage-release relationship at a photoreceptor synapse, though downstream ON cells depolarize when glutamate falls."}, {"text": "Hyperpolarization with decreased glutamate release", "why": "The balance shifts toward outward positive current, making the cell more negative and reducing calcium-dependent release."}, {"text": "Hyperpolarization with increased glutamate release", "why": "The ordinary photoreceptor relationship is the opposite: hyperpolarization reduces calcium entry and release."}, {"text": "Depolarization with increased glutamate release", "why": "This is the response to greater inward depolarizing current or the relative dark state, not the usual photoreceptor response to light."}], "answer": 2, "image": null}, {"id": "Q214", "deck": "va", "topic": "Photoreceptor voltages", "pages": [9, 10], "page": 9, "ref": "slide-va-9", "stem": "The lecture uses about -30 mV in darkness and -70 mV in bright light. What is the important physiologic relationship?", "options": [{"text": "The dark state is more negative than the light state", "why": "This reverses the central relationship."}, {"text": "Light always produces a large positive action potential in rods", "why": "Rods mainly generate graded receptor potentials."}, {"text": "Both values mean the cell must be electrically identical", "why": "A substantial voltage change alters transmitter release."}, {"text": "Glutamate release rises because -70 mV is more depolarized", "why": "-70 mV is more negative than -30 mV and decreases ordinary synaptic release."}, {"text": "The dark state is relatively depolarized and light shifts the cell more negative", "why": "The precise voltages depend on conditions; the central prediction is hyperpolarization in light, not a photoreceptor action potential."}], "answer": 4, "image": null}, {"id": "Q215", "deck": "va", "topic": "ON and OFF pathways", "pages": [9, 10, 11, 12], "page": 9, "ref": "slide-va-9", "stem": "Why is “glutamate inhibits bipolar cells” an incomplete general statement?", "options": [{"text": "ON and OFF bipolar cells express different receptor/signaling arrangements", "why": "ON bipolar cells invert the photoreceptor signal through mGluR6; OFF cells use sign-preserving ionotropic receptors. The rod ON pathway fits the lecture’s inhibitory shorthand."}, {"text": "All bipolar cells lack glutamate receptors", "why": "They do respond to photoreceptor glutamate."}, {"text": "Only the optic nerve releases retinal glutamate", "why": "Photoreceptor synapses are a key retinal glutamatergic site."}, {"text": "Glutamate is never released by photoreceptors", "why": "It is their principal transmitter."}, {"text": "ON and OFF cells always have identical light responses", "why": "Their opposing responses are central to retinal contrast processing."}], "answer": 0, "image": null}, {"id": "Q216", "deck": "va", "topic": "Retinal signaling", "pages": [10, 12], "page": 10, "ref": "slide-va-10", "stem": "Which comparison between photoreceptors and ganglion cells is correct?", "options": [{"text": "Photoreceptors use graded potentials; ganglion axons carry action potentials", "why": "Graded photoreceptor voltage regulates glutamate release. Spiking ganglion output then transmits visual information through the optic nerve."}, {"text": "Photoreceptors form the optic nerve directly", "why": "Ganglion cell axons form the nerve."}, {"text": "Bipolar cells are all located in the optic chiasm", "why": "Bipolar neurons are within the retina."}, {"text": "Both mainly transmit to the brain by diffusion of retinal chromophore", "why": "Chromophore recycling does not carry the neural visual signal."}, {"text": "Ganglion cells capture light through rhodopsin as their main ordinary role", "why": "Rods and cones are the major image-forming photoreceptors; ganglion output integrates retinal signals."}], "answer": 0, "image": null}, {"id": "Q217", "deck": "va", "topic": "Vitamin A deficiency", "pages": [13, 14], "page": 13, "ref": "slide-va-13", "stem": "A patient with fat malabsorption has trouble seeing at dusk but relatively preserved daylight acuity. Which mechanism best explains the early symptom?", "options": [{"text": "Inadequate retinal chromophore reduces rod rhodopsin availability", "why": "Vitamin A supplies retinal for photopigments. Rod dysfunction causes nyctalopia before severe cone/ocular surface involvement necessarily develops."}, {"text": "Excess cGMP synthesis guarantees normal night vision", "why": "Without adequate pigment, sensitivity is impaired despite downstream signaling components."}, {"text": "Excess acetylcholine contracts the iris sphincter in every case", "why": "That is not the primary vitamin A deficiency mechanism."}, {"text": "A blocked external auditory canal", "why": "That affects hearing rather than photopigment supply."}, {"text": "Selective destruction of the optic chiasm", "why": "That causes a field pattern rather than typical nutrition-related night blindness."}], "answer": 0, "image": null}, {"id": "Q218", "deck": "va", "topic": "Vitamin A deficiency", "pages": [14], "page": 14, "ref": "slide-va-14", "stem": "Why may night blindness take months to develop after vitamin A intake falls?", "options": [{"text": "Retinal never depends on systemic vitamin A", "why": "Vitamin A is required for retinal chromophore supply."}, {"text": "Liver stores buffer supply until reserves are depleted", "why": "Substantial hepatic vitamin A stores can delay deficiency manifestations. Time course varies with initial stores and absorption."}, {"text": "Rods regenerate the entire vitamin indefinitely without any dietary requirement", "why": "Recycling conserves chromophore but does not remove the nutritional requirement."}, {"text": "All deficiency symptoms require decades in every patient", "why": "Infants or severe malabsorption can deplete reserves more quickly."}, {"text": "Only the lens stores all vitamin A", "why": "The lecture emphasizes hepatic reserves, not the lens."}], "answer": 1, "image": null}, {"id": "Q219", "deck": "va", "topic": "Vitamin A deficiency", "pages": [14], "page": 14, "ref": "slide-va-14", "stem": "The source slide depicts white foamy ocular surface patches in vitamin A deficiency. What are these findings most consistent with?", "options": [{"text": "A bitemporal visual field defect", "why": "A field pattern cannot be identified as a conjunctival patch."}, {"text": "Bitot spots from conjunctival epithelial changes", "why": "These are conjunctival surface lesions associated with xerophthalmia, distinct from retinal blind spots or a scotoma. The slide’s generic blind spots wording is imprecise."}, {"text": "A middle-ear effusion", "why": "That is an otoscopic rather than ocular surface finding."}, {"text": "Drusen beneath the retinal pigment epithelium", "why": "Drusen are fundus deposits rather than foamy conjunctival patches."}, {"text": "Glaucomatous optic nerve cupping", "why": "That is a posterior optic disc change."}], "answer": 1, "image": "figure-bitot.jpg"}, {"id": "Q220", "deck": "va", "topic": "Vitamin A deficiency", "pages": [14], "page": 14, "ref": "slide-va-14", "stem": "Which statement about treatment of vitamin A deficiency-related night blindness is most accurate?", "options": [{"text": "No visual symptom can improve with repletion", "why": "Reversible pigment-related dysfunction can improve."}, {"text": "Every patient must receive IV vitamin A immediately without assessing dose or cause", "why": "Route and dose require clinical assessment; excess vitamin A can be toxic."}, {"text": "Vitamin A treatment only works by lowering IOP", "why": "The main mechanism here is restoration of chromophore availability."}, {"text": "Repletion can improve reversible rod dysfunction, but route and recovery depend on clinical context", "why": "Oral treatment is common; severe malabsorption or other circumstances may require a parenteral route. The slide’s rapid IV response is not a universal dosing or recovery promise."}, {"text": "All structural corneal damage reverses within minutes", "why": "Established tissue injury may persist."}], "answer": 3, "image": null}, {"id": "Q221", "deck": "va", "topic": "Color vision", "pages": [15], "page": 15, "ref": "slide-va-15", "stem": "A boy has lifelong bilateral red-green discrimination difficulty with normal visual acuity and no progression. Which mechanism is most likely?", "options": [{"text": "An inherited abnormality of cone opsin genes, commonly X linked", "why": "Common red-green deficiency affects cone pigment discrimination. Rods do not distinguish colors, and ordinary acuity can remain normal."}, {"text": "An acute left optic tract infarct", "why": "That produces a contralateral field defect rather than lifelong bilateral color deficiency."}, {"text": "A conductive middle-ear lesion", "why": "This affects hearing, not color vision."}, {"text": "Vitamin A depletion exclusively destroying rods", "why": "That causes dim-light dysfunction rather than the classic stable inherited red-green pattern."}, {"text": "Loss of all cone cells causing complete central blindness", "why": "Common red-green deficiencies do not require complete cone destruction."}], "answer": 0, "image": null}, {"id": "Q222", "deck": "va", "topic": "Visual perception", "pages": [17], "page": 17, "ref": "slide-va-17", "stem": "A patient detects lines and light but cannot identify familiar visual objects after a cortical lesion. Which distinction is illustrated?", "options": [{"text": "Perception occurs entirely in the lens", "why": "The lens focuses light; cortical networks interpret it."}, {"text": "A normal retina guarantees recognition of every object", "why": "Cortical processing can be impaired despite retinal input."}, {"text": "Visual interpretation requires no neural processing", "why": "Meaningful recognition depends on brain function."}, {"text": "Visual sensation can be present while cortical interpretation is impaired", "why": "Perception organizes sensory input into meaningful objects, faces, motion, depth, and color. Normal detection alone does not guarantee normal recognition."}, {"text": "All recognition failure must be cataract", "why": "Media opacity reduces image quality but does not explain every cortical perceptual deficit."}], "answer": 3, "image": null}, {"id": "Q223", "deck": "va", "topic": "Depth perception", "pages": [18, 19], "page": 18, "ref": "slide-va-18", "stem": "How does binocular stereopsis arise?", "options": [{"text": "The cochlear nuclei fuse retinal signals", "why": "They process auditory input rather than stereopsis."}, {"text": "The cortex compares and fuses the slightly different images from the two eyes", "why": "Binocular disparity supplies depth information. Monocular cues such as perspective and motion parallax also support depth judgments, so monocular vision does not eliminate every depth cue."}, {"text": "One eye cannot support any depth judgment of any kind", "why": "Monocular cues remain despite loss of true binocular stereopsis."}, {"text": "Both eyes must receive exactly identical images with no disparity", "why": "Small differences are the key stereoscopic signal."}, {"text": "The lens directly calculates object meaning", "why": "The lens performs optical focusing, not cortical fusion."}], "answer": 1, "image": null}, {"id": "Q224", "deck": "va", "topic": "Visual field localization", "pages": [19], "page": 19, "ref": "slide-va-19", "stem": "Complete destruction of the left optic nerve causes which primary field deficit?", "options": [{"text": "Left monocular vision loss", "why": "The optic nerve carries all retinal output from its eye before the chiasm. Binocular stereopsis is lost, though monocular depth cues remain."}, {"text": "Bitemporal hemianopia", "why": "That suggests central chiasmal crossing-fiber injury."}, {"text": "Only right monocular blindness", "why": "That reverses the affected eye."}, {"text": "Right homonymous hemianopia", "why": "That indicates a left retrochiasmal lesion, not isolated left optic nerve loss."}, {"text": "Left homonymous hemianopia", "why": "That suggests a right retrochiasmal lesion."}], "answer": 0, "image": null}, {"id": "Q225", "deck": "va", "topic": "Visual field localization", "pages": [19], "page": 19, "ref": "slide-va-19", "stem": "A stroke destroys the left primary visual cortex. Which field deficit is expected?", "options": [{"text": "Right homonymous hemianopia", "why": "Left retrochiasmal pathways represent the right visual hemifield from both eyes. Macular sparing may occur in some occipital lesions but is not mandatory."}, {"text": "Right monocular blindness", "why": "This would localize before the chiasm on the right."}, {"text": "Left monocular blindness", "why": "This would localize before the chiasm on the left."}, {"text": "Bitemporal hemianopia", "why": "This is characteristic of central optic chiasm injury."}, {"text": "Left homonymous hemianopia", "why": "That points to a right retrochiasmal lesion."}], "answer": 0, "image": null}, {"id": "Q226", "deck": "va", "topic": "Visual field localization", "pages": [19], "page": 19, "ref": "slide-va-19", "stem": "A lesion behind the optic chiasm affects one side of the visual pathway. Which general pattern is most likely?", "options": [{"text": "Loss of all vision only in the contralateral eye", "why": "That does not match ordinary retrochiasmal organization."}, {"text": "Only a lens accommodation deficit", "why": "Accommodation is not the defining retrochiasmal field deficit."}, {"text": "Only reduced hearing on one side", "why": "This is a visual pathway lesion."}, {"text": "Loss of the contralateral visual hemifield in both eyes", "why": "Retrochiasmal pathways carry corresponding hemifields from both eyes, producing homonymous defects."}, {"text": "Loss of all vision only in the ipsilateral eye", "why": "That is an optic nerve/pre-chiasmal pattern."}], "answer": 3, "image": null}, {"id": "Q227", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [21, 22], "page": 21, "ref": "slide-va-21", "stem": "Which region collects and directs airborne sound before it reaches the eardrum?", "options": [{"text": "External ear", "why": "The pinna and external auditory canal conduct sound toward the tympanic membrane. Hearing and balance receptors themselves are deeper in the inner ear."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}, {"text": "Stria vascularis", "why": "This lateral cochlear duct tissue maintains potassium-rich endolymph and the endocochlear potential."}, {"text": "Reissner membrane", "why": "This separates scala vestibuli from scala media and helps maintain their distinct fluid compartments."}, {"text": "Tectorial membrane", "why": "This overlies cochlear hair cells and participates in relative shear that bends stereocilia, especially of outer hair cells."}], "answer": 0, "image": null}, {"id": "Q228", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [22, 28, 36], "page": 22, "ref": "slide-va-22", "stem": "Which ear region provides mechanical impedance matching between air and cochlear fluid?", "options": [{"text": "Stria vascularis", "why": "This lateral cochlear duct tissue maintains potassium-rich endolymph and the endocochlear potential."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}, {"text": "Scala tympani", "why": "This perilymph-filled compartment lies below the basilar membrane and communicates with the round window."}, {"text": "Middle ear", "why": "Ossicular leverage and the tympanic membrane-to-stapes area relationship increase pressure at the oval window, improving air-to-fluid energy transfer."}, {"text": "Round window", "why": "This compliant interface permits pressure displacement as the stapes moves at the oval window; it is not the site of stapes insertion."}], "answer": 3, "image": null}, {"id": "Q229", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24], "page": 24, "ref": "slide-va-24", "stem": "Which cochlear compartment contains potassium-rich endolymph?", "options": [{"text": "Scala vestibuli", "why": "This perilymph-filled compartment begins at the oval window and lies above the cochlear duct."}, {"text": "Stria vascularis", "why": "This lateral cochlear duct tissue maintains potassium-rich endolymph and the endocochlear potential."}, {"text": "Middle ear", "why": "The tympanic membrane/ossicular system transmits and impedance-matches sound to inner-ear fluid through the oval window."}, {"text": "External ear", "why": "The pinna and canal collect/direct airborne sound toward the tympanic membrane; they do not contain the main balance receptors."}, {"text": "Scala media", "why": "The cochlear duct has high potassium endolymph. Scala vestibuli and tympani contain perilymph with a more extracellular-fluid-like ionic composition."}], "answer": 4, "image": null}, {"id": "Q230", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24], "page": 24, "ref": "slide-va-24", "stem": "Which compartment receives stapes-driven pressure waves at the oval window?", "options": [{"text": "Scala vestibuli", "why": "The oval window interfaces with scala vestibuli perilymph. Waves then produce differential pressure and basilar membrane motion."}, {"text": "Middle ear", "why": "The tympanic membrane/ossicular system transmits and impedance-matches sound to inner-ear fluid through the oval window."}, {"text": "Round window", "why": "This compliant interface permits pressure displacement as the stapes moves at the oval window; it is not the site of stapes insertion."}, {"text": "Reissner membrane", "why": "This separates scala vestibuli from scala media and helps maintain their distinct fluid compartments."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}], "answer": 0, "image": null}, {"id": "Q231", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24], "page": 24, "ref": "slide-va-24", "stem": "Which fluid compartment lies below the basilar membrane and terminates at the round window?", "options": [{"text": "External ear", "why": "The pinna and canal collect/direct airborne sound toward the tympanic membrane; they do not contain the main balance receptors."}, {"text": "Tectorial membrane", "why": "This overlies cochlear hair cells and participates in relative shear that bends stereocilia, especially of outer hair cells."}, {"text": "Scala tympani", "why": "Scala tympani contains perilymph. The round window provides a compliant pressure outlet."}, {"text": "Reissner membrane", "why": "This separates scala vestibuli from scala media and helps maintain their distinct fluid compartments."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}], "answer": 2, "image": null}, {"id": "Q232", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24, 25], "page": 24, "ref": "slide-va-24", "stem": "Which membrane separates the cochlear duct from scala tympani and supports the organ of Corti?", "options": [{"text": "External ear", "why": "The pinna and canal collect/direct airborne sound toward the tympanic membrane; they do not contain the main balance receptors."}, {"text": "Middle ear", "why": "The tympanic membrane/ossicular system transmits and impedance-matches sound to inner-ear fluid through the oval window."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}, {"text": "Basilar membrane", "why": "The basilar membrane is the frequency-selective mechanical platform for the sensory organ, unlike Reissner membrane above the duct."}, {"text": "Scala vestibuli", "why": "This perilymph-filled compartment begins at the oval window and lies above the cochlear duct."}], "answer": 3, "image": null}, {"id": "Q233", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24], "page": 24, "ref": "slide-va-24", "stem": "Which membrane separates scala vestibuli from scala media?", "options": [{"text": "Scala tympani", "why": "This perilymph-filled compartment lies below the basilar membrane and communicates with the round window."}, {"text": "Reissner membrane", "why": "The vestibular/Reissner membrane partitions perilymph above from endolymph in the cochlear duct."}, {"text": "Stria vascularis", "why": "This lateral cochlear duct tissue maintains potassium-rich endolymph and the endocochlear potential."}, {"text": "Tectorial membrane", "why": "This overlies cochlear hair cells and participates in relative shear that bends stereocilia, especially of outer hair cells."}, {"text": "Scala vestibuli", "why": "This perilymph-filled compartment begins at the oval window and lies above the cochlear duct."}], "answer": 1, "image": null}, {"id": "Q234", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [25, 32], "page": 25, "ref": "slide-va-25", "stem": "Which structure overlies the hair bundles and participates in relative shear during cochlear motion?", "options": [{"text": "Tectorial membrane", "why": "Relative motion among the organ of Corti, basilar membrane, and tectorial membrane deflects hair bundles. Outer hair bundles are embedded more directly than inner bundles."}, {"text": "Scala tympani", "why": "This perilymph-filled compartment lies below the basilar membrane and communicates with the round window."}, {"text": "Stria vascularis", "why": "This lateral cochlear duct tissue maintains potassium-rich endolymph and the endocochlear potential."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}, {"text": "Basilar membrane", "why": "This supports the organ of Corti and separates scala media from scala tympani; stiffness varies from base to apex."}], "answer": 0, "image": null}, {"id": "Q235", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24, 28, 36], "page": 24, "ref": "slide-va-24", "stem": "Which window accommodates fluid displacement rather than receiving the stapes footplate?", "options": [{"text": "Middle ear", "why": "The tympanic membrane/ossicular system transmits and impedance-matches sound to inner-ear fluid through the oval window."}, {"text": "Scala tympani", "why": "This perilymph-filled compartment lies below the basilar membrane and communicates with the round window."}, {"text": "Basilar membrane", "why": "This supports the organ of Corti and separates scala media from scala tympani; stiffness varies from base to apex."}, {"text": "Round window", "why": "Because inner-ear fluid is poorly compressible, a compliant round window allows displacement as the stapes moves at the oval window."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}], "answer": 3, "image": null}, {"id": "Q236", "deck": "va", "topic": "Ear and cochlear anatomy", "pages": [24], "page": 24, "ref": "slide-va-24", "stem": "Which tissue maintains endolymph ionic composition and the endocochlear potential?", "options": [{"text": "Stria vascularis", "why": "The stria vascularis supports the electrochemical driving force for hair-cell transduction. Loop diuretic toxicity can disrupt this function."}, {"text": "Middle ear", "why": "The tympanic membrane/ossicular system transmits and impedance-matches sound to inner-ear fluid through the oval window."}, {"text": "Basilar membrane", "why": "This supports the organ of Corti and separates scala media from scala tympani; stiffness varies from base to apex."}, {"text": "Tectorial membrane", "why": "This overlies cochlear hair cells and participates in relative shear that bends stereocilia, especially of outer hair cells."}, {"text": "Scala media", "why": "The cochlear duct contains potassium-rich endolymph and the organ of Corti’s apical sensory environment."}], "answer": 0, "image": null}, {"id": "Q237", "deck": "va", "topic": "Cochlear supporting cells", "pages": [26], "page": 26, "ref": "slide-va-26", "stem": "Which supporting cells are also called outer phalangeal cells and support outer hair cells?", "options": [{"text": "Ossicular osteocytes", "why": "Bone cells are not the named organ of Corti supporting-cell class."}, {"text": "Retinal bipolar cells", "why": "These are in the eye, not the cochlea."}, {"text": "Vestibular dark cells", "why": "These maintain vestibular fluid homeostasis rather than serving as Deiters cells."}, {"text": "Spiral ganglion neurons", "why": "These are afferent neuronal cell bodies rather than outer hair-cell supports."}, {"text": "Deiters cells", "why": "These supporting cells stabilize outer hair cells. The slide’s pharyngeal wording is a typo for phalangeal."}], "answer": 4, "image": null}, {"id": "Q238", "deck": "va", "topic": "Cochlear supporting cells", "pages": [26], "page": 26, "ref": "slide-va-26", "stem": "Which cells help form the tunnel of Corti?", "options": [{"text": "Only stapes osteoblasts", "why": "These are bone-forming cells, not organ of Corti pillars."}, {"text": "Only retinal pigment cells", "why": "These are not cochlear supporting cells."}, {"text": "Inner and outer pillar cells", "why": "The lecture emphasizes outer pillar cells; together with inner pillar cells they form the tunnel’s supporting architecture."}, {"text": "Cochlear nerve Schwann cells only", "why": "These support axons rather than form the organ’s pillar tunnel."}, {"text": "Only stria vascularis marginal cells", "why": "These participate in fluid/ionic homeostasis."}], "answer": 2, "image": null}, {"id": "Q239", "deck": "va", "topic": "Acoustic conduction", "pages": [28, 36], "page": 28, "ref": "slide-va-28", "stem": "Which sequence correctly traces mechanical sound transmission?", "options": [{"text": "Canal, tympanic membrane, malleus, incus, stapes, oval window", "why": "The ossicular chain transmits and amplifies pressure before fluid displacement drives cochlear mechanics."}, {"text": "Canal, scala media air, vestibular cortex, stapes", "why": "The scala media is fluid-filled and the sequence is not the sound-conduction path."}, {"text": "Canal, stapes, malleus, incus, round window", "why": "This misorders the chain and places the stapes at the wrong window."}, {"text": "Canal, cochlear nerve, tympanic membrane, cortex", "why": "Mechanical transmission precedes hair-cell and neural signaling."}, {"text": "Tympanic membrane, round window, incus, retina", "why": "This sequence mixes unrelated structures and incorrect interfaces."}], "answer": 0, "image": null}, {"id": "Q240", "deck": "va", "topic": "Acoustic conduction", "pages": [28], "page": 28, "ref": "slide-va-28", "stem": "What is the helicotrema?", "options": [{"text": "A direct passage through the stapes footplate", "why": "The helicotrema is at the cochlear apex, not the oval window."}, {"text": "The tunnel between pillar cells", "why": "That is the tunnel of Corti, not the communication of perilymphatic scalae."}, {"text": "The opening from ear canal into the middle ear", "why": "That is not the helicotrema; the intact tympanic membrane separates these spaces."}, {"text": "A retinal membrane that contains rhodopsin", "why": "It is an inner-ear structure, not part of the retina."}, {"text": "An apical communication between scala vestibuli and scala tympani", "why": "Very low-frequency pressure changes can pass around the apex. The scala media retains a separate endolymphatic compartment."}], "answer": 4, "image": null}, {"id": "Q241", "deck": "va", "topic": "Tonotopy and traveling waves", "pages": [29, 30, 31], "page": 29, "ref": "slide-va-29", "stem": "Where does a 10-kHz tone produce its greatest basilar membrane response?", "options": [{"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}, {"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}, {"text": "Basal narrow stiff membrane", "why": "High frequencies peak near the cochlear base. The base is narrow and stiff compared with the apex."}, {"text": "Apical wide compliant membrane", "why": "The cochlear apex is broader and more flexible, with peak responses to lower frequencies."}], "answer": 3, "image": null}, {"id": "Q242", "deck": "va", "topic": "Tonotopy and traveling waves", "pages": [29, 30, 31], "page": 29, "ref": "slide-va-29", "stem": "Where does a low-frequency tone around 100 Hz produce its greatest response?", "options": [{"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Apical wide compliant membrane", "why": "Low-frequency waves travel farther toward the compliant apex before peaking. They do not simply have zero motion everywhere at the base."}, {"text": "Basal narrow stiff membrane", "why": "The cochlear base near the oval window has high mechanical stiffness and responds best to high frequencies."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}, {"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}], "answer": 1, "image": null}, {"id": "Q243", "deck": "va", "topic": "Tonotopy and traveling waves", "pages": [31], "page": 31, "ref": "slide-va-31", "stem": "Where does a middle-frequency tone peak relative to very low and very high tones?", "options": [{"text": "Basal narrow stiff membrane", "why": "The cochlear base near the oval window has high mechanical stiffness and responds best to high frequencies."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}, {"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}, {"text": "Intermediate cochlear region", "why": "The traveling-wave peak lies between basal high-frequency and apical low-frequency regions. The lecture uses about 800–1000 Hz as an illustrative middle example."}, {"text": "Apical wide compliant membrane", "why": "The cochlear apex is broader and more flexible, with peak responses to lower frequencies."}], "answer": 3, "image": null}, {"id": "Q244", "deck": "va", "topic": "Tonotopy and traveling waves", "pages": [29, 30], "page": 29, "ref": "slide-va-29", "stem": "What cochlear structure/location is most vulnerable when basal hair-cell injury first causes high-frequency loss?", "options": [{"text": "Apical wide compliant membrane", "why": "The cochlear apex is broader and more flexible, with peak responses to lower frequencies."}, {"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}, {"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Basal narrow stiff membrane", "why": "The basal place code represents high pitches. The stiffness gradient is the key principle; a blanket claim that all high-frequency distinctions are easier is not required."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}], "answer": 3, "image": null}, {"id": "Q245", "deck": "va", "topic": "Tonotopy and traveling waves", "pages": [29, 31], "page": 29, "ref": "slide-va-29", "stem": "Which mechanical region is wider and less stiff than the basal turn?", "options": [{"text": "Basal narrow stiff membrane", "why": "The cochlear base near the oval window has high mechanical stiffness and responds best to high frequencies."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}, {"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}, {"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Apical wide compliant membrane", "why": "The apical region supports low-frequency resonance. This mechanical gradient helps create a tonotopic map."}], "answer": 4, "image": null}, {"id": "Q246", "deck": "va", "topic": "Hair-cell roles", "pages": [25, 32], "page": 25, "ref": "slide-va-25", "stem": "Which cells provide the majority of sensory afferent input for ordinary hearing?", "options": [{"text": "Outer hair cells", "why": "Outer hair-cell electromotility amplifies and sharpens basilar motion and is subject to efferent modulation; their injury reduces sensitivity and tuning."}, {"text": "Vestibular hair cells", "why": "These transduce head movement/gravity signals rather than the cochlear frequency map."}, {"text": "Inner hair cells", "why": "Inner hair cells communicate through glutamate with spiral ganglion afferents. Outer hair cells primarily amplify mechanical tuning."}, {"text": "Spiral ganglion neurons", "why": "Their cell bodies receive hair-cell input and their axons form the cochlear nerve; they generate neural action potentials downstream."}, {"text": "Deiters supporting cells", "why": "These support outer hair cells mechanically rather than serving as the principal afferent sound receptors."}], "answer": 2, "image": null}, {"id": "Q247", "deck": "va", "topic": "Hair-cell roles", "pages": [32], "page": 32, "ref": "slide-va-32", "stem": "Which cells change length to amplify and sharpen basilar membrane vibration?", "options": [{"text": "Inner hair cells", "why": "Inner hair cells provide most afferent sensory information to spiral ganglion neurons and are the principal auditory receptor output cells."}, {"text": "Outer hair cells", "why": "Outer hair-cell electromotility improves sensitivity and frequency selectivity. Efferent pathways can modulate the amplifier."}, {"text": "Vestibular hair cells", "why": "These transduce head movement/gravity signals rather than the cochlear frequency map."}, {"text": "Deiters supporting cells", "why": "These support outer hair cells mechanically rather than serving as the principal afferent sound receptors."}, {"text": "Spiral ganglion neurons", "why": "Their cell bodies receive hair-cell input and their axons form the cochlear nerve; they generate neural action potentials downstream."}], "answer": 1, "image": null}, {"id": "Q248", "deck": "va", "topic": "Hair-cell roles", "pages": [25, 39], "page": 25, "ref": "slide-va-25", "stem": "Which neurons send axons that form the cochlear branch of CN VIII?", "options": [{"text": "Spiral ganglion neurons", "why": "These bipolar sensory neurons relay hair-cell output to ipsilateral cochlear nuclei before higher bilateral auditory processing."}, {"text": "Deiters supporting cells", "why": "These support outer hair cells mechanically rather than serving as the principal afferent sound receptors."}, {"text": "Outer hair cells", "why": "Outer hair-cell electromotility amplifies and sharpens basilar motion and is subject to efferent modulation; their injury reduces sensitivity and tuning."}, {"text": "Vestibular hair cells", "why": "These transduce head movement/gravity signals rather than the cochlear frequency map."}, {"text": "Inner hair cells", "why": "Inner hair cells provide most afferent sensory information to spiral ganglion neurons and are the principal auditory receptor output cells."}], "answer": 0, "image": null}, {"id": "Q249", "deck": "va", "topic": "Hair-cell roles", "pages": [26], "page": 26, "ref": "slide-va-26", "stem": "Which cells stabilize the outer hair-cell rows rather than generating the primary auditory afferent signal?", "options": [{"text": "Deiters supporting cells", "why": "Supporting cells help maintain the mechanical and cellular organization of the organ of Corti."}, {"text": "Outer hair cells", "why": "Outer hair-cell electromotility amplifies and sharpens basilar motion and is subject to efferent modulation; their injury reduces sensitivity and tuning."}, {"text": "Spiral ganglion neurons", "why": "Their cell bodies receive hair-cell input and their axons form the cochlear nerve; they generate neural action potentials downstream."}, {"text": "Inner hair cells", "why": "Inner hair cells provide most afferent sensory information to spiral ganglion neurons and are the principal auditory receptor output cells."}, {"text": "Vestibular hair cells", "why": "These transduce head movement/gravity signals rather than the cochlear frequency map."}], "answer": 0, "image": null}, {"id": "Q250", "deck": "va", "topic": "Hair-cell roles", "pages": [32], "page": 32, "ref": "slide-va-32", "stem": "A drug preferentially damages the cochlear amplifier while leaving many inner hair cells initially intact. Which cells are primarily injured?", "options": [{"text": "Inner hair cells", "why": "Inner hair cells provide most afferent sensory information to spiral ganglion neurons and are the principal auditory receptor output cells."}, {"text": "Outer hair cells", "why": "Outer hair-cell dysfunction raises thresholds and broadens tuning even if some afferent sensory transduction remains."}, {"text": "Vestibular hair cells", "why": "These transduce head movement/gravity signals rather than the cochlear frequency map."}, {"text": "Spiral ganglion neurons", "why": "Their cell bodies receive hair-cell input and their axons form the cochlear nerve; they generate neural action potentials downstream."}, {"text": "Deiters supporting cells", "why": "These support outer hair cells mechanically rather than serving as the principal afferent sound receptors."}], "answer": 1, "image": null}, {"id": "Q251", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [33, 34, 37], "page": 33, "ref": "slide-va-33", "stem": "A cochlear hair bundle bends toward its tallest stereocilia. What response follows?", "options": [{"text": "Depolarization caused primarily by potassium efflux at the apical bundle", "why": "The high-potassium endolymphatic environment drives potassium inward through apical channels, not the proposed outward depolarizing current."}, {"text": "No baseline activity and an all-or-none hair-cell spike", "why": "Hair cells normally have graded potentials and some resting transduction; spikes occur in afferent neurons."}, {"text": "Hyperpolarization with increased synaptic release", "why": "Ordinary hair-cell hyperpolarization reduces voltage-dependent calcium entry and release rather than increasing it."}, {"text": "Depolarization with increased glutamate and afferent firing", "why": "Tip-link tension opens mechanically gated channels. Potassium-rich endolymph drives inward cation current, followed by basal calcium entry and increased release."}, {"text": "Hyperpolarization with decreased glutamate and afferent firing", "why": "Deflection away from the tallest stereocilia closes channels and reduces sensory output."}], "answer": 3, "image": null}, {"id": "Q252", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [35, 37], "page": 35, "ref": "slide-va-35", "stem": "A hair bundle bends away from its tallest stereocilia. What response follows?", "options": [{"text": "Depolarization caused primarily by potassium efflux at the apical bundle", "why": "The high-potassium endolymphatic environment drives potassium inward through apical channels, not the proposed outward depolarizing current."}, {"text": "No baseline activity and an all-or-none hair-cell spike", "why": "Hair cells normally have graded potentials and some resting transduction; spikes occur in afferent neurons."}, {"text": "Depolarization with increased glutamate and afferent firing", "why": "Deflection toward the tallest stereocilia opens mechanotransduction channels; potassium enters from endolymph and promotes calcium-dependent release."}, {"text": "Hyperpolarization with increased synaptic release", "why": "Ordinary hair-cell hyperpolarization reduces voltage-dependent calcium entry and release rather than increasing it."}, {"text": "Hyperpolarization with decreased glutamate and afferent firing", "why": "Reduced tip-link tension closes mechanotransduction channels, decreasing inward current and transmitter output."}], "answer": 4, "image": null}, {"id": "Q253", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [33], "page": 33, "ref": "slide-va-33", "stem": "A drug increases the fraction of open hair-bundle channels at rest. What direction of response is expected?", "options": [{"text": "Depolarization caused primarily by potassium efflux at the apical bundle", "why": "The high-potassium endolymphatic environment drives potassium inward through apical channels, not the proposed outward depolarizing current."}, {"text": "Depolarization with increased glutamate and afferent firing", "why": "Some hair-cell channels are open at rest, permitting tonic output. Increasing opening increases depolarizing current and release; baseline firing allows bidirectional modulation rather than only an on/off response."}, {"text": "Hyperpolarization with decreased glutamate and afferent firing", "why": "Deflection away from the tallest stereocilia closes channels and reduces sensory output."}, {"text": "No baseline activity and an all-or-none hair-cell spike", "why": "Hair cells normally have graded potentials and some resting transduction; spikes occur in afferent neurons."}, {"text": "Hyperpolarization with increased synaptic release", "why": "Ordinary hair-cell hyperpolarization reduces voltage-dependent calcium entry and release rather than increasing it."}], "answer": 1, "image": null}, {"id": "Q254", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [34, 37], "page": 34, "ref": "slide-va-34", "stem": "A sound deflects the bundle in the excitatory direction and increases synaptic calcium entry. Which downstream result is expected?", "options": [{"text": "Hyperpolarization with decreased glutamate and afferent firing", "why": "Deflection away from the tallest stereocilia closes channels and reduces sensory output."}, {"text": "Depolarization caused primarily by potassium efflux at the apical bundle", "why": "The high-potassium endolymphatic environment drives potassium inward through apical channels, not the proposed outward depolarizing current."}, {"text": "Depolarization with increased glutamate and afferent firing", "why": "Increased calcium promotes glutamate exocytosis onto cochlear afferents. Neural firing changes encode the mechanically transduced signal."}, {"text": "Hyperpolarization with increased synaptic release", "why": "Ordinary hair-cell hyperpolarization reduces voltage-dependent calcium entry and release rather than increasing it."}, {"text": "No baseline activity and an all-or-none hair-cell spike", "why": "Hair cells normally have graded potentials and some resting transduction; spikes occur in afferent neurons."}], "answer": 2, "image": null}, {"id": "Q255", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [35], "page": 35, "ref": "slide-va-35", "stem": "An experiment closes hair-bundle mechanotransduction channels while other conductances remain. Which result is expected?", "options": [{"text": "No baseline activity and an all-or-none hair-cell spike", "why": "Hair cells normally have graded potentials and some resting transduction; spikes occur in afferent neurons."}, {"text": "Hyperpolarization with decreased glutamate and afferent firing", "why": "Removing inward depolarizing current reduces receptor voltage, calcium entry, and transmitter release."}, {"text": "Depolarization with increased glutamate and afferent firing", "why": "Deflection toward the tallest stereocilia opens mechanotransduction channels; potassium enters from endolymph and promotes calcium-dependent release."}, {"text": "Depolarization caused primarily by potassium efflux at the apical bundle", "why": "The high-potassium endolymphatic environment drives potassium inward through apical channels, not the proposed outward depolarizing current."}, {"text": "Hyperpolarization with increased synaptic release", "why": "Ordinary hair-cell hyperpolarization reduces voltage-dependent calcium entry and release rather than increasing it."}], "answer": 1, "image": null}, {"id": "Q256", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [34], "page": 34, "ref": "slide-va-34", "stem": "Why does opening apical potassium-permeable channels depolarize cochlear hair cells?", "options": [{"text": "Potassium concentration is zero in endolymph", "why": "Endolymph is potassium rich."}, {"text": "The apical channel only carries outward potassium", "why": "The relevant transduction current is inward under normal conditions."}, {"text": "The cochlear duct contains only air", "why": "It contains endolymph, not air."}, {"text": "Potassium is actively transformed into sodium", "why": "Ions are not chemically converted during transduction."}, {"text": "Potassium-rich endolymph and its positive potential drive potassium into the cell", "why": "The unusual apical electrochemical environment differs from ordinary low-potassium extracellular fluid. Basolateral potassium exit then helps repolarize the cell."}], "answer": 4, "image": null}, {"id": "Q257", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [34, 37], "page": 34, "ref": "slide-va-34", "stem": "Which event couples hair-cell depolarization to glutamate release?", "options": [{"text": "Release of rhodopsin into the synapse", "why": "Rhodopsin is a retinal pigment, not the cochlear transmitter."}, {"text": "An action potential traveling from cortex back into the stapes", "why": "This is not the local excitation-release sequence."}, {"text": "Conversion of glutamate into endolymph", "why": "Glutamate is released as transmitter, not converted into bulk fluid."}, {"text": "Opening of basal voltage-gated calcium channels", "why": "Calcium influx triggers synaptic vesicle fusion at the hair-cell ribbon synapse onto afferent fibers."}, {"text": "Closure of every calcium channel", "why": "That would reduce, rather than promote, release."}], "answer": 3, "image": null}, {"id": "Q258", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [33, 34, 35], "page": 33, "ref": "slide-va-33", "stem": "What role do tip links play in cochlear hair bundles?", "options": [{"text": "They are retinal pigment discs", "why": "Those are photoreceptor structures."}, {"text": "They connect the stapes directly to the auditory cortex", "why": "They are microscopic bundle structures rather than a macroscopic conduction tract."}, {"text": "They couple bundle displacement to mechanotransduction channel gating", "why": "Deflection toward the tallest row increases tension and channel opening; deflection away reduces tension and opening."}, {"text": "They are the axons forming the optic nerve", "why": "They are mechanical hair-bundle connections."}, {"text": "They synthesize glutamate from cGMP", "why": "They do not serve as that enzyme."}], "answer": 2, "image": null}, {"id": "Q259", "deck": "va", "topic": "Auditory mechanotransduction", "pages": [32, 33], "page": 32, "ref": "slide-va-32", "stem": "Which qualification is important when reading that the tallest stereocilium touches the tectorial membrane?", "options": [{"text": "All auditory hair cells retain a mature kinocilium", "why": "Mature mammalian cochlear hair cells lack a kinocilium; stereociliary orientation still defines polarity."}, {"text": "Inner hair cells are in the external canal", "why": "They reside in the organ of Corti."}, {"text": "No cochlear hair cell experiences mechanical bending", "why": "Bundle deflection is central to auditory transduction."}, {"text": "Outer hair bundles are embedded, while inner hair bundles are generally driven by local fluid/shear motion", "why": "The slide is a useful simplified mechanical model but should not imply that every inner hair bundle is identically embedded."}, {"text": "The tectorial membrane is the same as the tympanic membrane", "why": "They are separate inner- and middle-ear structures."}], "answer": 3, "image": null}, {"id": "Q260", "deck": "va", "topic": "Sensory comparison", "pages": [10, 34], "page": 10, "ref": "slide-va-10", "stem": "Which comparison of light and excitatory cochlear bundle deflection is correct?", "options": [{"text": "Both receptors transmit to the brain by their own long spiking axons", "why": "Ganglion/afferent neurons carry the long-distance action potentials."}, {"text": "Light hyperpolarizes photoreceptors; excitatory bundle deflection depolarizes hair cells", "why": "Both change graded receptor potentials and glutamate output, but their initial voltage responses to the respective stimuli are opposite."}, {"text": "Both always depolarize their receptor cells", "why": "Light usually hyperpolarizes rods and cones."}, {"text": "Neither uses synaptic transmitter release", "why": "Both employ transmitter release onto downstream neurons."}, {"text": "Both always hyperpolarize their receptor cells", "why": "Excitatory hair-bundle deflection depolarizes."}], "answer": 1, "image": null}, {"id": "Q261", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "Where does the cochlear nerve make its first central synapse?", "options": [{"text": "Primary auditory cortex", "why": "Heschl transverse temporal cortex, chiefly BA41 with adjacent BA42 auditory processing, supports tonotopic conscious sound analysis."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Cochlear nuclei", "why": "Dorsal and ventral cochlear nuclei receive ipsilateral CN VIII input before ascending projections distribute information bilaterally."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}, {"text": "Spiral ganglion", "why": "These peripheral auditory sensory neuron bodies relay cochlear hair-cell information into the cochlear nerve."}], "answer": 2, "image": null}, {"id": "Q262", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "Which binaural center is particularly important for interaural time differences at lower frequencies?", "options": [{"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Primary auditory cortex", "why": "Heschl transverse temporal cortex, chiefly BA41 with adjacent BA42 auditory processing, supports tonotopic conscious sound analysis."}, {"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Medial superior olive", "why": "Time differences provide useful low-frequency localization cues. The lateral superior olive emphasizes level differences."}], "answer": 4, "image": null}, {"id": "Q263", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "Which binaural center particularly uses interaural intensity differences for high-frequency localization?", "options": [{"text": "Spiral ganglion", "why": "These peripheral auditory sensory neuron bodies relay cochlear hair-cell information into the cochlear nerve."}, {"text": "Lateral superior olive", "why": "High-frequency head-shadow differences help lateralization. The LSO integrates excitation and inhibition to compare ear levels."}, {"text": "Lateral lemniscus", "why": "This ascending brainstem auditory tract carries predominantly contralateral but bilateral-derived information toward the inferior colliculus."}, {"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}], "answer": 1, "image": null}, {"id": "Q264", "deck": "va", "topic": "Auditory pathway localization", "pages": [40], "page": 40, "ref": "slide-va-40", "stem": "Which ascending tract connects lower auditory relays with the inferior colliculus?", "options": [{"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}, {"text": "Lateral lemniscus", "why": "The lateral lemniscus is an ascending brainstem tract, not confined exclusively to the midbrain. It carries information derived from both ears."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}], "answer": 2, "image": null}, {"id": "Q265", "deck": "va", "topic": "Auditory pathway localization", "pages": [40], "page": 40, "ref": "slide-va-40", "stem": "Which midbrain structure integrates auditory information and supports orienting to sound?", "options": [{"text": "Lateral lemniscus", "why": "This ascending brainstem auditory tract carries predominantly contralateral but bilateral-derived information toward the inferior colliculus."}, {"text": "Inferior colliculus", "why": "The inferior colliculus is auditory; the superior colliculus is more strongly associated with visual orienting and multisensory functions."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}], "answer": 1, "image": null}, {"id": "Q266", "deck": "va", "topic": "Auditory pathway localization", "pages": [40, 41], "page": 40, "ref": "slide-va-40", "stem": "Which thalamic nucleus relays auditory information to cortex?", "options": [{"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}, {"text": "Spiral ganglion", "why": "These peripheral auditory sensory neuron bodies relay cochlear hair-cell information into the cochlear nerve."}, {"text": "Medial geniculate body", "why": "MGN/MGB is the auditory relay. The lateral geniculate nucleus relays vision."}, {"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}], "answer": 2, "image": null}, {"id": "Q267", "deck": "va", "topic": "Auditory pathway localization", "pages": [41], "page": 41, "ref": "slide-va-41", "stem": "Which cortical region receives the main thalamic auditory projection?", "options": [{"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}, {"text": "Primary auditory cortex", "why": "Heschl’s transverse temporal gyri contain primary auditory cortex, predominantly BA41. The lecture groups BA41/42 as the core/adjacent auditory region."}, {"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}], "answer": 1, "image": null}, {"id": "Q268", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "Where are the cell bodies of the neurons whose central axons form the cochlear nerve?", "options": [{"text": "Primary auditory cortex", "why": "Heschl transverse temporal cortex, chiefly BA41 with adjacent BA42 auditory processing, supports tonotopic conscious sound analysis."}, {"text": "Lateral lemniscus", "why": "This ascending brainstem auditory tract carries predominantly contralateral but bilateral-derived information toward the inferior colliculus."}, {"text": "Spiral ganglion", "why": "Spiral ganglion afferents receive inner hair-cell input and carry frequency-coded information to brainstem cochlear nuclei."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}], "answer": 2, "image": null}, {"id": "Q269", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "A lesion selectively disrupts comparison of arrival timing between ears. Which circuit is most directly implicated?", "options": [{"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Spiral ganglion", "why": "These peripheral auditory sensory neuron bodies relay cochlear hair-cell information into the cochlear nerve."}, {"text": "Medial superior olive", "why": "Binaural timing comparison is especially associated with MSO circuitry, useful for localizing lower-frequency sounds."}, {"text": "Lateral lemniscus", "why": "This ascending brainstem auditory tract carries predominantly contralateral but bilateral-derived information toward the inferior colliculus."}], "answer": 3, "image": null}, {"id": "Q270", "deck": "va", "topic": "Auditory pathway localization", "pages": [39], "page": 39, "ref": "slide-va-39", "stem": "A lesion impairs use of a high-frequency sound’s loudness difference across ears. Which circuit is implicated?", "options": [{"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Lateral superior olive", "why": "The LSO contributes to interaural level comparison, especially where the head creates a substantial acoustic shadow."}, {"text": "Lateral lemniscus", "why": "This ascending brainstem auditory tract carries predominantly contralateral but bilateral-derived information toward the inferior colliculus."}, {"text": "Primary auditory cortex", "why": "Heschl transverse temporal cortex, chiefly BA41 with adjacent BA42 auditory processing, supports tonotopic conscious sound analysis."}, {"text": "Cochlear nuclei", "why": "These are the first central auditory synapses at the pontomedullary region; input from each auditory nerve initially enters its ipsilateral nuclei."}], "answer": 1, "image": null}, {"id": "Q271", "deck": "va", "topic": "Auditory pathway localization", "pages": [41], "page": 41, "ref": "slide-va-41", "stem": "Which auditory area preserves a frequency map that the lecture describes as posteromedial high frequencies and anterolateral low frequencies?", "options": [{"text": "Spiral ganglion", "why": "These peripheral auditory sensory neuron bodies relay cochlear hair-cell information into the cochlear nerve."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}, {"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Primary auditory cortex", "why": "Tonotopy persists through the pathway. Cortical maps are more complex than a single strip, but the lecture’s orientation is a useful teaching description."}], "answer": 4, "image": null}, {"id": "Q272", "deck": "va", "topic": "Auditory pathway localization", "pages": [42, 44, 45], "page": 42, "ref": "slide-va-42", "stem": "A focal lesion at the first central auditory relay causes marked ipsilateral hearing loss. Which site fits?", "options": [{"text": "Cochlear nuclei", "why": "A lesion at or before the cochlear nuclei can interrupt information from one ear before robust bilateral distribution. Higher unilateral lesions rarely cause complete monaural deafness."}, {"text": "Inferior colliculus", "why": "This midbrain auditory integration center contributes to orienting/reflex processing and projects toward the medial geniculate body."}, {"text": "Medial geniculate body", "why": "This thalamic auditory relay sends information toward auditory cortex; the lateral geniculate body is visual."}, {"text": "Lateral superior olive", "why": "This circuit compares interaural level/intensity differences, particularly for high frequencies where head shadow is important."}, {"text": "Medial superior olive", "why": "This binaural circuit is especially important for interaural timing differences, useful for low-frequency sound localization."}], "answer": 0, "image": null}, {"id": "Q273", "deck": "va", "topic": "Auditory pathway sequence", "pages": [39, 40, 41, 45], "page": 39, "ref": "slide-va-39", "stem": "Which ordering follows the principal ascending auditory route?", "options": [{"text": "Spiral ganglion, lateral geniculate, visual cortex, superior olive", "why": "The lateral geniculate and visual cortex are not the main auditory relays."}, {"text": "Auditory cortex, middle ear, spiral ganglion, cochlear nuclei", "why": "This reverses the direction of the ordinary ascending sensory sequence."}, {"text": "Spiral ganglion, cochlear nuclei, superior olive, lateral lemniscus, inferior colliculus, medial geniculate, auditory cortex", "why": "The pathway includes parallel and crossing routes, but this sequence summarizes the major relays."}, {"text": "Cochlear nuclei, optic chiasm, inferior colliculus, retina", "why": "The optic chiasm and retina are visual structures."}, {"text": "Inner hair cell, vestibulospinal tract, motor endplate", "why": "This is not the conscious auditory pathway."}], "answer": 2, "image": null}, {"id": "Q274", "deck": "va", "topic": "Auditory lesion patterns", "pages": [42, 44, 45], "page": 42, "ref": "slide-va-42", "stem": "A complete lesion of the right cochlear nerve most directly produces which deficit?", "options": [{"text": "Only bitemporal visual loss", "why": "This is a chiasmal visual pattern."}, {"text": "No hearing effect because all peripheral signals are bilateral before entering the nerve", "why": "Each cochlear nerve initially carries its own ear’s information."}, {"text": "Marked right sensorineural hearing loss", "why": "The auditory nerve carries ipsilateral cochlear output before bilateral central projections. This is distinct from most higher unilateral lesions."}, {"text": "Only a conductive air-bone gap", "why": "A nerve lesion is sensorineural, not a middle-ear transmission deficit."}, {"text": "Complete left deafness with preserved right hearing", "why": "This reverses the peripheral nerve laterality."}], "answer": 2, "image": null}, {"id": "Q275", "deck": "va", "topic": "Auditory lesion patterns", "pages": [43, 45], "page": 43, "ref": "slide-va-43", "stem": "A unilateral auditory cortex lesion is less likely than a cochlear nerve lesion to cause complete deafness in one ear. Why?", "options": [{"text": "Higher auditory pathways receive substantial bilateral input", "why": "Binaural ascending projections preserve basic hearing from both ears despite many higher unilateral lesions, while localization/discrimination may suffer."}, {"text": "All cortical lesions leave every aspect of auditory processing normal", "why": "Complex processing can be impaired despite preserved thresholds."}, {"text": "The cortex receives no auditory information", "why": "Auditory cortex receives and processes thalamic auditory input."}, {"text": "Only the ossicles encode conscious sound meaning", "why": "Ossicles transfer mechanics; cortex interprets sound."}, {"text": "The cochlear nerve already contains equal input from both cochleae", "why": "Bilateral distribution becomes substantial centrally, after initial ipsilateral entry."}], "answer": 0, "image": null}, {"id": "Q276", "deck": "va", "topic": "Auditory lesion patterns", "pages": [43, 44, 45], "page": 43, "ref": "slide-va-43", "stem": "A patient has profound isolated left-ear hearing loss. Which site is least likely to be the sole cause?", "options": [{"text": "Left cochlea", "why": "Cochlear injury can cause severe ipsilateral SNHL."}, {"text": "Right primary auditory cortex alone", "why": "A single higher unilateral lesion usually does not eliminate hearing exclusively in one ear because of bilateral representation."}, {"text": "Left cochlear nerve", "why": "This can markedly impair ipsilateral neural transmission."}, {"text": "Left middle ear", "why": "A severe mechanical transmission lesion can substantially reduce left hearing through a conductive mechanism."}, {"text": "Left cochlear nuclei", "why": "A complete early central relay lesion can cause major ipsilateral loss before bilateral distribution."}], "answer": 1, "image": null}, {"id": "Q277", "deck": "va", "topic": "Auditory processing", "pages": [41, 43], "page": 41, "ref": "slide-va-41", "stem": "A patient detects sounds but has reduced sound localization and complex discrimination after a higher auditory lesion. Which interpretation is best?", "options": [{"text": "Bilateral input can preserve detection while central processing is impaired", "why": "Preserved thresholds do not mean every function of auditory cortex and pathways is intact. Speech-in-noise and temporal judgments may also suffer."}, {"text": "A unilateral cortical lesion must create total ipsilateral deafness", "why": "That is not the usual higher unilateral lesion pattern."}, {"text": "All auditory function is normal if a tone is detected", "why": "Detection is only one aspect of hearing."}, {"text": "The patient must have an isolated blocked ear canal", "why": "Central deficits can occur without a conductive lesion."}, {"text": "No CNS processing is needed for localization", "why": "Binaural and cortical networks contribute to localization."}], "answer": 0, "image": null}, {"id": "Q278", "deck": "av", "topic": "Auditory foundations", "pages": [14, 15], "page": 14, "ref": "slide-av-14", "stem": "A middle-ear lesion prevents efficient transfer of airborne sound energy into cochlear fluid. Which loss category is expected?", "options": [{"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Conductive hearing loss", "why": "The external ear captures sound, the middle ear impedance-matches air to fluid, and the inner ear transduces fluid motion to neural activity. Failure of the transmission stage is conductive."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}], "answer": 3, "image": null}, {"id": "Q279", "deck": "av", "topic": "Auditory foundations", "pages": [16, 17], "page": 16, "ref": "slide-av-16", "stem": "An experiment preserves ossicular motion but destroys the sensory apparatus that converts the resulting traveling wave into neural activity. Which loss category is expected?", "options": [{"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Sensorineural hearing loss", "why": "The basilar traveling wave is the hydromechanical input to cochlear hair-cell transduction. Destroying sensory cells produces cochlear SNHL rather than a pure transmission gap."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}, {"text": "Central auditory processing impairment", "why": "Higher auditory lesions can impair localization, discrimination, or speech-in-noise processing despite preserved basic peripheral thresholds; this is not defined by an air-bone gap."}], "answer": 1, "image": null}, {"id": "Q280", "deck": "av", "topic": "Auditory foundations", "pages": [19, 20], "page": 19, "ref": "slide-av-19", "stem": "A higher unilateral auditory lesion reduces localization and speech-in-noise performance without eliminating detection in either ear. Which category fits?", "options": [{"text": "Central auditory processing impairment", "why": "Ascending auditory pathways distribute information bilaterally. The lecture gives simplified dorsal/ventral crossing patterns; the key clinical principle is bilateral representation above the initial cochlear input."}, {"text": "Sensorineural hearing loss", "why": "Air and bone thresholds are both elevated without a substantial air-bone gap, indicating cochlear or neural dysfunction."}, {"text": "Mixed hearing loss", "why": "Bone thresholds are elevated and air thresholds are still worse, indicating combined sensorineural and conductive components."}, {"text": "Conductive hearing loss", "why": "Air thresholds are worse than bone thresholds, with relatively preserved cochlear bone conduction; pathology lies in external or middle-ear transmission."}, {"text": "Normal hearing", "why": "Air and bone thresholds are within the usual normal range, without a meaningful gap. Abnormally elevated thresholds indicate hearing loss."}], "answer": 0, "image": null}, {"id": "Q281", "deck": "av", "topic": "Cochlear place coding", "pages": [16, 17, 18], "page": 16, "ref": "slide-av-16", "stem": "A high-frequency tone produces a traveling-wave maximum near the oval window. Which part of the basilar membrane is involved?", "options": [{"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}, {"text": "Basal narrow stiff membrane", "why": "The traveling-wave framework, associated with von Bekesy, links frequency to the place of maximal basilar displacement. High frequencies peak basally."}, {"text": "Apical wide compliant membrane", "why": "The cochlear apex is broader and more flexible, with peak responses to lower frequencies."}, {"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}], "answer": 1, "image": null}, {"id": "Q282", "deck": "av", "topic": "Cochlear place coding", "pages": [16, 17, 18], "page": 16, "ref": "slide-av-16", "stem": "A low-pitch tone produces maximal displacement near the cochlear apex. Which region is involved?", "options": [{"text": "Uniform response at every cochlear position", "why": "This would eliminate place coding and is inconsistent with the stiffness gradient and traveling-wave peaks."}, {"text": "Intermediate cochlear region", "why": "Middle frequencies peak between the extreme base and apex; the map is continuous rather than divided into only three discrete sites."}, {"text": "Apical wide compliant membrane", "why": "Lower-frequency traveling waves peak farther along the wider, more flexible apical membrane. Tonotopy then persists in auditory neural coding."}, {"text": "Basal narrow stiff membrane", "why": "The cochlear base near the oval window has high mechanical stiffness and responds best to high frequencies."}, {"text": "Frequency coded only by sound amplitude", "why": "Amplitude primarily relates to intensity; it does not replace the cochlear place code for pitch."}], "answer": 2, "image": null}, {"id": "Q283", "deck": "oph", "topic": "Drug class members", "pages": [4, 10], "page": 4, "ref": "slide-oph-4", "stem": "Timolol, carteolol, and levobunolol belong to which glaucoma drug class?", "options": [{"text": "Rho kinase inhibitors", "why": "Netarsudil and ripasudil are members of that class."}, {"text": "Direct muscarinic agonists", "why": "Pilocarpine and carbachol are members of that class."}, {"text": "Beta-adrenergic antagonists", "why": "These agents reduce aqueous production. Betaxolol is a relatively beta-1-selective member; the others named here are nonselective."}, {"text": "Prostaglandin analogs", "why": "Latanoprost, travoprost, and bimatoprost-related therapy belong to that group."}, {"text": "Carbonic anhydrase inhibitors", "why": "Acetazolamide, dorzolamide, and brinzolamide belong to that class."}], "answer": 2, "image": null}, {"id": "Q284", "deck": "oph", "topic": "Drug class members", "pages": [5, 10], "page": 5, "ref": "slide-oph-5", "stem": "Apraclonidine and brimonidine are which receptor agonists?", "options": [{"text": "Alpha-2 agonists", "why": "They reduce aqueous synthesis, with uveoscleral outflow effects particularly relevant to brimonidine."}, {"text": "Dopamine D2 agonists", "why": "This is not the glaucoma class of these agents."}, {"text": "Alpha-1 agonists", "why": "Phenylephrine is the classic alpha-1 mydriatic."}, {"text": "Beta-2 agonists", "why": "These would not describe the named alpha-2 pressure-lowering drugs."}, {"text": "M3 agonists", "why": "Pilocarpine and carbachol have direct muscarinic activity."}], "answer": 0, "image": null}, {"id": "Q285", "deck": "oph", "topic": "Drug class members", "pages": [7, 10], "page": 7, "ref": "slide-oph-7", "stem": "Latanoprost, travoprost, and bimatoprost-related ocular therapy share which major effect?", "options": [{"text": "Increased uveoscleral aqueous outflow", "why": "These prostaglandin-related agents lower IOP through outflow enhancement and can cause pigmentation, redness, and lash changes."}, {"text": "Renal bicarbonate wasting as their principal ocular mechanism", "why": "That is systemic CA-inhibitor pharmacology."}, {"text": "Direct inhibition of acetylcholinesterase", "why": "That describes echothiophate."}, {"text": "Selective alpha-1-mediated dilation without cycloplegia", "why": "That describes phenylephrine."}, {"text": "Systemic osmotic extraction of ocular water", "why": "That is mannitol therapy."}], "answer": 0, "image": null}, {"id": "Q286", "deck": "av", "topic": "Ototoxic drug class members", "pages": [49], "page": 49, "ref": "slide-av-49", "stem": "Streptomycin, gentamicin, tobramycin, and amikacin share which clinically important class risk?", "options": [{"text": "Purely cortical visual field loss without inner-ear involvement", "why": "That does not capture the characteristic class toxicity."}, {"text": "Uniformly reversible salicylate-like toxicity only", "why": "Aminoglycoside damage can be permanent."}, {"text": "Selective external canal wax production", "why": "This is not the mechanism of their hearing/vestibular risk."}, {"text": "Direct therapeutic cochlear hair-cell regeneration", "why": "These drugs can damage rather than regenerate sensory cells."}, {"text": "Aminoglycoside cochlear and/or vestibular toxicity", "why": "Risk patterns differ among agents, but all can injure inner-ear structures. Basal outer hair cells and vestibular sensory cells are important targets."}], "answer": 4, "image": null}, {"id": "Q287", "deck": "av", "topic": "Extended clinical cases", "pages": [3, 4, 33], "page": 3, "ref": "slide-av-3", "stem": "A 3-year-old boy has had several documented episodes of acute otitis media during the past year. His parents now report that he turns up the television and does not always respond when called. He is afebrile and has no acute ear pain today. Otoscopy shows an intact dull amber membrane, and tympanometry is flat with a normal canal volume. Masked bone thresholds are near normal, while air thresholds are elevated. Which diagnosis best explains the persistent hearing problem between acute infections?", "options": [{"text": "Connexin-26-related hearing loss", "why": "GJB2 variants can cause congenital nonsyndromic sensorineural loss, often recessive and present without a known family history."}, {"text": "Otitis media with effusion", "why": "Persistent middle-ear fluid produces a conductive air-bone gap and a flat normal-volume tympanogram. It can affect functional hearing without fever or the bulging inflamed drum of an acute episode."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}], "answer": 1, "image": "figure-effusion.jpg"}, {"id": "Q288", "deck": "av", "topic": "Extended clinical cases", "pages": [6, 7, 34, 46], "page": 6, "ref": "slide-av-6", "stem": "A 7-month-old infant failed bilateral newborn hearing screening. ABR at three months showed profound loss, and repeated evaluation confirms minimal useful auditory response despite an appropriately fitted hearing-aid trial. The external and middle ears are normal. Genetic testing finds biallelic GJB2 variants, while both parents have normal hearing and no known affected relatives. Imaging and specialist assessment suggest that the auditory nerves are present. Which diagnosis best explains the hearing impairment and the apparently negative family history?", "options": [{"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Connexin-26-related hearing loss", "why": "Recessive GJB2-related loss can occur in children of unaffected carrier parents. Connexin-26 dysfunction disrupts cochlear homeostasis; selected profound cases may benefit from implantation plus language rehabilitation."}, {"text": "Noise-induced hearing loss", "why": "Chronic acoustic injury commonly produces a 3–6 kHz notch, often near 4 kHz, rather than a flat conductive air-bone gap."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve Schwann-cell tumor can cause progressive asymmetric SNHL, unilateral tinnitus, and imbalance; MRI of the internal auditory canals evaluates it."}, {"text": "Cerumen impaction", "why": "Obstructing wax causes conductive loss in the external canal; a normal canal with inner-ear deficits needs another explanation."}], "answer": 1, "image": null}, {"id": "Q289", "deck": "av", "topic": "Extended clinical cases", "pages": [8, 9, 10, 51], "page": 8, "ref": "slide-av-8", "stem": "A 56-year-old man reports gradually progressive hearing loss in the left ear for five years. He has constant left-sided high-pitched tinnitus and has noticed that he drifts to the left when walking. Otoscopy is normal. Audiometry confirms asymmetric SNHL with poor left word recognition rather than a large air-bone gap. MRI of the internal auditory canals with contrast shows the enhancing lesion pictured. Which diagnosis best accounts for the combination of asymmetric auditory and vestibular dysfunction?", "options": [{"text": "Presbycusis", "why": "Age-related loss is usually bilateral symmetric high-frequency sensorineural loss with impaired speech understanding, particularly in noise."}, {"text": "Vestibular schwannoma", "why": "A vestibular nerve schwannoma can involve hearing through its internal canal/CPA location and produce imbalance. MRI identifies the lesion; the audiogram alone does not establish a tumor."}, {"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}, {"text": "Connexin-26-related hearing loss", "why": "GJB2 variants can cause congenital nonsyndromic sensorineural loss, often recessive and present without a known family history."}], "answer": 1, "image": "figure-schwannoma.jpg"}, {"id": "Q290", "deck": "av", "topic": "Extended clinical cases", "pages": [47, 48], "page": 47, "ref": "slide-av-47", "stem": "A 78-year-old retired machinist says he can hear that people are speaking but has difficulty understanding them in restaurants. The problem has worsened slowly over a decade and affects both ears similarly. He has a history of occupational noise exposure, smoking, and cardiovascular disease. Otoscopy is normal, and audiometry shows a symmetric high-frequency sensorineural pattern. No new unilateral tinnitus or abrupt threshold change is present. Which age-associated disorder is the best overall explanation, while allowing that prior noise exposure may also contribute?", "options": [{"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Ototoxic cochlear injury", "why": "Aminoglycosides, cisplatin, loop diuretics, and salicylates can impair inner-ear function; reversibility and target vary by agent."}, {"text": "Presbycusis", "why": "Age-associated sensory and neural degeneration causes symmetric SNHL and impaired complex speech understanding. Multiple risk factors can contribute, but symmetry and gradual progression differ from sudden loss or a focal retrocochlear presentation."}, {"text": "Cholesteatoma", "why": "Keratinizing squamous tissue in the middle ear can erode ossicles and cause conductive loss, retraction debris, and chronic drainage."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}], "answer": 2, "image": null}, {"id": "Q291", "deck": "av", "topic": "Extended clinical cases", "pages": [50], "page": 50, "ref": "slide-av-50", "stem": "A 43-year-old woman notices a marked reduction in hearing in the right ear on awakening. She assumes the ear is blocked and waits until the next afternoon, but the deficit persists. Otoscopy reveals no wax, fluid, or drum abnormality. Weber lateralizes left, and Rinne remains air greater than bone on the right. Urgent audiometry identifies a new loss exceeding 30 dB at three contiguous frequencies within 48 hours. Which diagnosis should guide time-sensitive otologic evaluation and discussion of corticosteroid therapy?", "options": [{"text": "Tympanic membrane perforation", "why": "A hole in the eardrum impairs mechanical transmission and can cause conductive loss; its appearance differs from an intact effusion-filled drum."}, {"text": "Congenital aural atresia", "why": "External canal malformation impairs sound conduction; it is not equivalent to congenital destruction of cochlear sensory cells."}, {"text": "Sudden sensorineural hearing loss", "why": "Abrupt cochlear/neural loss with the rule-of-threes threshold pattern is SSNHL. Normal otoscopy and a positive Rinne do not rule it out. Prompt treatment assessment matters even when the patient describes fullness rather than explicitly reporting deafness."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid causes conductive loss and often an amber or dull tympanic membrane; it does not primarily damage the cochlear nerve."}, {"text": "Otosclerosis", "why": "Stapes fixation impairs sound transmission and causes conductive or mixed loss, often with a relatively normal tympanic membrane."}], "answer": 2, "image": null}, {"id": "Q292", "deck": "av", "topic": "Extended vestibular cases", "pages": [85, 86, 88, 89], "page": 85, "ref": "slide-av-85", "stem": "A 62-year-old woman reports spinning every time she rolls toward her right side in bed or looks up to reach a high shelf. Each episode lasts less than a minute, and she is comfortable while sitting still between spells. She denies new hearing loss, aural fullness, severe headache, or limb symptoms. Right Dix-Hallpike positioning produces a brief delayed torsional-upbeating nystagmus that fades. The neurologic examination is otherwise normal. Which diagnosis best fits this triggered episodic pattern and supports a canalith repositioning maneuver?", "options": [{"text": "Posterior canal BPPV", "why": "Brief positional attacks with the characteristic posterior-canal nystagmus support BPPV. Epley addresses displaced otoconia; it is more appropriate than routine chronic suppression or assuming the symptoms are Meniere attacks."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibular loss causes head-motion oscillopsia and imbalance, often worse in darkness or on uneven surfaces; ototoxicity is a possible cause."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}], "answer": 0, "image": "figure-dix.jpg"}, {"id": "Q293", "deck": "av", "topic": "Extended vestibular cases", "pages": [85, 90, 105, 106], "page": 85, "ref": "slide-av-85", "stem": "A 38-year-old man develops continuous severe spinning and vomiting several days after an upper respiratory illness. Symptoms persist at rest for two days and worsen with any head movement. Hearing is unchanged, and there is no fluctuating aural fullness. Specialist examination supports an acute peripheral vestibular deficit after appropriate assessment for central disease. He is given short-term nausea control, then encouraged to begin graded mobilization and vestibular exercises. Which diagnosis best matches the sustained time course and absence of new cochlear symptoms?", "options": [{"text": "Vestibular neuritis", "why": "Vestibular neuritis causes a sustained acute vestibular syndrome, unlike seconds-long triggered BPPV. Preserved hearing distinguishes it from classic labyrinthitis; recovery depends partly on central compensation."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}], "answer": 0, "image": null}, {"id": "Q294", "deck": "av", "topic": "Extended vestibular cases", "pages": [91], "page": 91, "ref": "slide-av-91", "stem": "A 24-year-old with a severe bacterial middle-ear infection develops new intense vertigo, vomiting, and a substantial hearing decline in the same ear. The symptoms persist rather than occurring only during brief positional maneuvers. The clinician is concerned about spread of inflammation or infection to the inner ear and arranges urgent specialist management. Which diagnosis best explains combined cochlear and vestibular involvement and the need for infection-directed treatment rather than symptomatic medication alone?", "options": [{"text": "Labyrinthitis", "why": "Labyrinthine involvement causes vertigo plus hearing loss. In a bacterial context, antibiotics and source management are essential; antiemetics or steroids cannot substitute for control of suppurative infection."}, {"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Vestibular migraine", "why": "Recurrent vestibular symptoms associated with a migraine history and migrainous features suggest vestibular migraine; fluctuating cochlear loss is not required."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}, {"text": "Multisensory disequilibrium", "why": "Combined visual, proprioceptive, and vestibular deficits can impair balance, especially in older adults; no single end-organ lesion need explain all symptoms."}], "answer": 0, "image": null}, {"id": "Q295", "deck": "av", "topic": "Extended vestibular cases", "pages": [92, 93, 94, 95, 96, 97], "page": 92, "ref": "slide-av-92", "stem": "A 49-year-old woman has had several spontaneous vertigo attacks over six months, each lasting about one to two hours. During attacks she notices roaring left tinnitus, pressure in the left ear, and reduced hearing. Audiograms taken at different visits document fluctuating low-frequency SNHL. Between attacks she is often functional, although hearing has begun to decline. There is no consistent seconds-long trigger when rolling over in bed. Which diagnosis best unifies the episodic vestibular and fluctuating cochlear symptoms?", "options": [{"text": "Vestibular neuritis", "why": "An acute sustained peripheral vestibular syndrome lasts days and typically lacks new hearing loss; hearing loss suggests labyrinthine or other pathology."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Meniere disease", "why": "The classic tetrad and duration favor Meniere disease. Endolymphatic hydrops is its characteristic histopathologic correlate, though the causal relationship and individual course are complex."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 3, "image": "figure-hydrops.jpg"}, {"id": "Q296", "deck": "av", "topic": "Extended vestibular cases", "pages": [49, 104, 109], "page": 49, "ref": "slide-av-49", "stem": "A 67-year-old received prolonged gentamicin for a serious infection. Since discharge, objects appear to bounce when he walks or turns his head. He is fairly steady while sitting, but becomes very unstable in a dark hallway or on an uneven surface. Examination demonstrates impaired compensatory eye movements with rapid head turns to either side. There is no single seconds-long positional trigger. Which disorder best explains the oscillopsia and increased dependence on vision and proprioception?", "options": [{"text": "Labyrinthitis", "why": "Inflammation involving the labyrinth causes vertigo with hearing loss; bacterial spread from middle ear or meninges is a serious possibility."}, {"text": "Orthostatic presyncope", "why": "Lightheadedness after standing with a blood-pressure fall reflects cerebral hypoperfusion rather than necessarily a labyrinthine spinning sensation."}, {"text": "Bilateral vestibular hypofunction", "why": "Bilateral vestibulotoxic injury reduces VOR function and produces head-motion oscillopsia. Darkness and unstable surfaces remove reliable alternative inputs; rehabilitation aims to improve compensation and remaining sensory use."}, {"text": "Central vestibular lesion", "why": "Focal neurologic deficits, direction-changing gaze-evoked or vertical nystagmus, or severe truncal ataxia raise concern for a central lesion such as stroke."}, {"text": "Posterior canal BPPV", "why": "Brief triggered episodes after rolling, looking up, or bending, with torsional-upbeating positional nystagmus, suggest displaced otoconia in the posterior canal."}], "answer": 2, "image": null}, {"id": "Q297", "deck": "oph", "topic": "Extended pharmacology cases", "pages": [4, 6, 7, 10], "page": 4, "ref": "slide-oph-4", "stem": "A 71-year-old man with open-angle glaucoma starts a new eye drop that reduces aqueous secretion without changing pupil size. Within days he develops wheezing, unusual fatigue, and a pulse of 46/min. He has a history of asthma and takes no new oral medication. The clinician explains that topical ocular drugs can still enter the systemic circulation and decides to stop the suspected agent while arranging an alternative pressure-lowering strategy. Which medication most plausibly caused this combined pulmonary and cardiac reaction?", "options": [{"text": "Pilocarpine", "why": "A cholinergic drug can cause systemic secretory effects, but the question centers on a classic beta-blocker cardiopulmonary reaction in an asthmatic patient."}, {"text": "Latanoprost", "why": "This commonly causes local pigmentation/lash changes rather than this beta-blockade cluster."}, {"text": "Dorzolamide", "why": "A topical CA inhibitor can cause irritation or taste disturbance, but it does not primarily block cardiac and bronchial beta receptors."}, {"text": "Netarsudil", "why": "This acts at trabecular outflow and commonly causes hyperemia, not nonselective beta blockade."}, {"text": "Timolol", "why": "Nonselective systemic beta blockade can provoke bronchospasm and bradycardia after ophthalmic absorption. Asthma and conduction disease are important contraindication concerns."}], "answer": 4, "image": null}, {"id": "Q298", "deck": "oph", "topic": "Extended pharmacology cases", "pages": [6, 10], "page": 6, "ref": "slide-oph-6", "stem": "A 59-year-old woman receives an oral medication to reduce aqueous production while awaiting further glaucoma treatment. Several days later she reports tingling around the mouth and in the fingers. Laboratory testing shows reduced bicarbonate and potassium, with a normal anion gap. She also has a history of calcium-containing kidney stones. The clinician suspects systemic inhibition of an enzyme involved in both ciliary secretion and renal bicarbonate handling. Which drug best explains the therapeutic and adverse effects?", "options": [{"text": "Timolol", "why": "Beta blockade explains bradycardia/bronchospasm rather than bicarbonate wasting."}, {"text": "Echothiophate", "why": "Acetylcholinesterase inhibition causes cholinergic effects rather than carbonic anhydrase-mediated bicarbonate loss."}, {"text": "Tropicamide", "why": "Antimuscarinic dilation/cycloplegia does not explain the renal acid-base pattern."}, {"text": "Mannitol", "why": "Osmotic diuresis affects volume and osmolality but does not produce this characteristic CA-inhibitor mechanism."}, {"text": "Acetazolamide", "why": "Systemic carbonic anhydrase inhibition reduces aqueous formation while causing bicarbonate wasting, hyperchloremic acidosis, potassium depletion, paresthesias, and stone risk."}], "answer": 4, "image": null}, {"id": "Q299", "deck": "va", "topic": "Extended physiology cases", "pages": [8, 9, 10, 11, 12], "page": 8, "ref": "slide-va-8", "stem": "A researcher records from an isolated rod while delivering a brief flash. In a control cell, the flash lowers cGMP, reduces inward cation current, makes the membrane potential more negative, and decreases glutamate release. In a mutant cell, the pigment still absorbs light normally, but activated transducin cannot stimulate its downstream effector. The mutant therefore fails to lower cGMP appropriately. Which normal enzymatic event is directly disrupted in this experiment?", "options": [{"text": "Renal bicarbonate secretion", "why": "This is unrelated to the isolated rod signaling defect."}, {"text": "Spiral ganglion action-potential generation", "why": "That belongs to auditory rather than retinal transduction."}, {"text": "Phosphodiesterase-mediated cGMP hydrolysis", "why": "Transducin normally activates PDE6, which lowers cGMP and closes cyclic-nucleotide-gated channels. Normal pigment absorption does not rescue a block at this downstream step."}, {"text": "Direct M3-mediated ciliary contraction", "why": "That is an ocular drug mechanism, not rod phototransduction."}, {"text": "Initial 11-cis-retinal photoisomerization", "why": "The question states that pigment absorption/activation remains intact."}], "answer": 2, "image": null}, {"id": "Q300", "deck": "va", "topic": "Extended physiology cases", "pages": [24, 25, 32, 33, 34, 35], "page": 24, "ref": "slide-va-24", "stem": "An investigator applies a controlled shear displacement to a cochlear hair bundle toward its tallest stereocilia. The apical surface is bathed in normal potassium-rich endolymph, while the basal membrane remains in its usual environment. The investigator records a graded depolarization followed by increased synaptic transmitter release and greater firing of the connected auditory afferent. Which explanation correctly links the initial mechanical event to the electrical and synaptic changes?", "options": [{"text": "The external canal produces neurotransmitter that diffuses through the stapes", "why": "The local sensory synapse is in the cochlea, not the external canal."}, {"text": "A large action potential in the hair cell directly travels into the cortex", "why": "Hair cells use graded receptor potentials; the connected neurons carry spikes."}, {"text": "Potassium exits apically and directly activates glutamate receptors inside the hair cell", "why": "The excitatory apical transduction current is inward, and glutamate acts downstream at the afferent synapse."}, {"text": "Tip-link tension opens apical channels, potassium enters, and depolarization opens basal calcium channels", "why": "The unusual endolymphatic potassium/electrical environment drives inward transduction current. Calcium then triggers glutamate release to spiral ganglion afferents."}, {"text": "Light activates rhodopsin, lowering cGMP and depolarizing the cell", "why": "This is not the cochlear mechanical pathway; light also hyperpolarizes ordinary photoreceptors."}], "answer": 3, "image": null}, {"id": "Q301", "deck": "va", "topic": "Extended localization cases", "pages": [39, 40, 41, 42, 43, 44, 45], "page": 39, "ref": "slide-va-39", "stem": "A patient develops difficulty identifying where sounds originate after a focal unilateral lesion in a higher auditory pathway. Pure-tone testing still demonstrates useful hearing from both ears. The neurologist contrasts this with a lesion of the cochlear nerve, which can markedly reduce hearing from its own ear. The difference is explained by how auditory information is distributed after reaching the brainstem. Which principle best accounts for the patient’s preserved bilateral sound detection?", "options": [{"text": "A unilateral higher lesion must produce complete contralateral ear deafness", "why": "Bilateral representation makes that an unusual isolated pattern."}, {"text": "The ossicles independently generate conscious sound recognition", "why": "They transfer mechanical energy rather than interpret sound."}, {"text": "The auditory cortex receives only ipsilateral input", "why": "Higher auditory processing is bilaterally supplied, often with contralateral predominance."}, {"text": "Each cochlear nerve already carries equal input from both ears", "why": "Peripheral cochlear nerves initially carry input from their own cochlea."}, {"text": "Substantial bilateral representation develops above the initial ipsilateral cochlear input", "why": "Information from each ear reaches both higher auditory systems. Unilateral higher lesions often impair localization or discrimination more than basic monaural detection."}], "answer": 4, "image": null}]};
